INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Araku Tribal Museum', 'araku-tribal-museum', 'Tribal cultural museum in Araku Valley showcasing the lifestyle, indigenous arts, crafts, and instruments of 19 regional Eastern Ghats tribes, featuring live Dhimsa dance and official ITDA/GCC forest honey and organic coffee counters.', 'Nature & Wildlife', 'Andhra Pradesh', 'Alluri Sitharama Raju (ASR) District', 'Araku Valley', '09:00 AM', '06:00 PM', 40, '/images/aptourism/tribal_museum.jpg', 'EASY', 4.1, 11583, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Araku Coffee Museum & GCC Experience Center', 'araku-coffee-museum-gcc-experience-center', 'Dedicated museum celebrating the history of Eastern Ghats Arabica coffee cultivation since 1898, featuring historical bean exhibits, live roasting demonstrations, and single-origin coffee tasting.', 'Artisans & Culture', 'Andhra Pradesh', 'Alluri Sitharama Raju (ASR) District', 'Araku Valley', '08:30 AM', '07:00 PM', 20, '/images/aptourism/asr/araku_coffee_museum.jpg', 'EASY', 4.1, 4288, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Padmapuram Botanical Gardens & Tree Top Huts', 'padmapuram-botanical-gardens-tree-top-huts', 'Padmapuram Gardens, located in Araku Valley within the Alluri Sitharama Raju district of Andhra Pradesh, is a beautifully maintained botanical garden spread over 26 acres. Established in 1942 during World War II to supply vegetables to soldiers, it was later transformed into a horticultural nursery and training center.', 'Scenic & Cultural', 'Andhra Pradesh', 'Alluri Sitharama Raju (ASR) District', 'Araku Valley', '08:30 AM', '06:00 PM', 40, '/images/aptourism/asr/padmapuram_gardens.jpg', 'EASY', 4, 9015, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Araku Chocolate Factory & Homemade Chocolate World', 'araku-chocolate-factory-homemade-chocolate-world', 'The Araku Chocolate factory produces craft chocolates from cocoa grown in the Eastern Ghats, offering visitors live demonstrations of bean roasting, stone-grinding, and packaging alongside local organic cocoa products.', 'Scenic & Cultural', 'Andhra Pradesh', 'Alluri Sitharama Raju (ASR) District', 'Araku Valley', '09:00 AM', '07:30 PM', 0, '/images/aptourism/asr/araku_chocolate_factory.jpg', 'EASY', 3.3, 928, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Chaparai Water Cascades (Dumbriguda)', 'chaparai-water-cascades-dumbriguda', 'Chaparai Water Cascade, located in Alluri Sitharama Raju district of Andhra Pradesh, India, is an extraordinary natural formation characterized by a series of cascading waterfalls that descend over rocky terrain. This site serves as both a vital ecological resource and a cultural landmark, reflecting the intricate relationship between the local community and their environment.', 'Waterfalls & Gorges', 'Andhra Pradesh', 'Alluri Sitharama Raju (ASR) District', 'Dumbriguda', '08:00 AM', '05:30 PM', 20, '/images/aptourism/asr/chaparai_cascades.jpg', 'EASY', 4.1, 14932, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Galikonda Viewpoint', 'galikonda-viewpoint', 'Highest panoramic viewpoint on the Vizag–Araku ghat road at 1,320m elevation (second highest peak in the Eastern Ghats). Offers 360-degree vistas of morning cloud inversions over deep valleys, coffee plantations, and the railway line. Popular stop for mountain pineapple slices and fresh ginger tea.', 'Scenic & Cultural', 'Andhra Pradesh', 'Alluri Sitharama Raju (ASR) District', 'Ananthagiri', '08:00 AM', '06:00 PM', 0, '/images/aptourism/asr/galikonda_viewpoint.jpg', 'EASY', 4.5, 5726, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Borra Caves', 'borra-caves', 'Borra Caves (Telugu: Borrā Guhalu) are a limestone cave system in Ananthagiri hills of the Araku Valley in Alluri Sitharama Raju district, Andhra Pradesh. They feature extensive karst formations, including stalactites, stalagmites, and other speleothems.', 'Scenic & Cultural', 'Andhra Pradesh', 'Alluri Sitharama Raju (ASR) District', 'Ananthagiri', '10:00 AM', '02:00 PM', 80, '/images/aptourism/borra_caves.jpg', 'EASY', 4.5, 37566, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Katiki Waterfalls', 'katiki-waterfalls', 'Katiki Waterfalls is located in Alluri Sitharama Raju district of the Indian state of Andhra Pradesh. The waterfall originates at River Gosthani. The waterfall is named after its location Katiki. This waterfall is near to borra caves and distance will be around 30 Kms by road. Remote view', 'Waterfalls & Gorges', 'Andhra Pradesh', 'Alluri Sitharama Raju (ASR) District', 'Ananthagiri', '09:00 AM', '04:00 PM', 30, '/images/aptourism/asr/katiki_waterfalls.jpg', 'EASY', 4.5, 1190, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Tyda Jungle Bells Nature Camp', 'tyda-jungle-bells-nature-camp', 'Everything to know Tyda Nature Camp jungle bells on the Vizag-Araku route — activities, log hut stays, distance, and booking tips.', 'Scenic & Cultural', 'Andhra Pradesh', 'Alluri Sitharama Raju (ASR) District', 'Ananthagiri', '09:00 AM', '05:30 PM', 50, '/images/aptourism/tyda.jpg', 'EASY', 4.1, 1530, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Vanjangi Cloud Hills (Meghalaya of AP)', 'vanjangi-cloud-hills-meghalaya-of-ap', 'Vanjangi is a hill station located near Paderu in the Alluri Sitharama Raju district of Andhra Pradesh, India. It is situated approximately 3,400 feet (1,000 m) above sea level.', 'Scenic & Cultural', 'Andhra Pradesh', 'Alluri Sitharama Raju (ASR) District', 'Paderu', '04:30 AM', '09:00 AM', 30, '/images/aptourism/asr/vanjangi_hills.jpg', 'EASY', 4.7, 2737, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Matsyagundam (Sacred Fish River Gorge)', 'matsyagundam-sacred-fish-river-gorge', 'Matsyagundam Temple is one of the lesser-known spiritual and natural attractions near Paderu in Alluri Sitharama Raju district, offering a peaceful combination of devotion, river scenery, greenery, and local traditions.', 'Waterfalls & Gorges', 'Andhra Pradesh', 'Alluri Sitharama Raju (ASR) District', 'Hukumpeta', '06:00 AM', '06:00 PM', 0, '/images/aptourism/asr/matsyagundam_gorge.jpg', 'EASY', 4.5, 175, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Modakondamma Temple', 'sri-modakondamma-temple', 'Revered tribal goddess shrine located in Paderu, worshipped as the patron protector deity of the Agency tracts across the Eastern Ghats. Hosts the celebrated annual Modakondamma Jathara in May, attracting thousands of indigenous devotees celebrating forest rituals.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Alluri Sitharama Raju (ASR) District', 'Paderu', '06:00 AM', '08:30 PM', 0, '/images/aptourism/asr/modakondamma_temple.jpg', 'EASY', 4.3, 25, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Lambasingi (Kashmir of Andhra Pradesh)', 'lambasingi-kashmir-of-andhra-pradesh', 'Lambasingi (or Lammasingi) is a small village in the Eastern Ghats of Chintapalli Mandal of Alluri Sitharama Raju district in the Indian state of Andhra Pradesh.', 'Scenic & Cultural', 'Andhra Pradesh', 'Alluri Sitharama Raju (ASR) District', 'Chintapalli', '08:00 AM', '06:00 PM', 0, '/images/aptourism/lambasingi.jpg', 'EASY', 4.5, 466, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Thajangi Reservoir & Adventure Camp', 'thajangi-reservoir-adventure-camp', 'Serene mountain reservoir located near Lambasingi and Chintapalli, featuring tranquil lake waters surrounded by mist-clad hill ranges, pine groves, and adventure campsites with zip-lining and boating.', 'Lakes, Dams & Waterways', 'Andhra Pradesh', 'Alluri Sitharama Raju (ASR) District', 'Chintapalli', '08:30 AM', '05:30 PM', 20, '/images/aptourism/asr/thajangi_reservoir.jpg', 'EASY', 4.3, 201, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Susan Garden (Yellow Blossom Hill Fields)', 'susan-garden-yellow-blossom-hill-fields', 'Vibrant hillside fields blooming with dense yellow Niger seed flowers (Guizotia abyssinica) every winter between November and January. Cultivated by local tribal farmers, creating a glowing golden landscape against misty mountains.', 'Scenic & Cultural', 'Andhra Pradesh', 'Alluri Sitharama Raju (ASR) District', 'Chintapalli', '07:00 AM', '05:30 PM', 30, '/images/aptourism/asr/susan_garden.jpg', 'EASY', 5, 3, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kothapalli Waterfalls', 'kothapalli-waterfalls', 'The Kothapally Waterfalls is a waterfall near the southeastern coast of India at Gangaraju Madugula, near Paderu in the Visakhapatnam district of Andhra Pradesh. The falls were only recently discovered by a village boy, Vanthala Abbi. Although the falls lack any public infrastructure, they have become a tourist attraction in the Visakhapatnam district.', 'Waterfalls & Gorges', 'Andhra Pradesh', 'Alluri Sitharama Raju (ASR) District', 'G. Madugula', '08:00 AM', '05:00 PM', 30, '/images/aptourism/asr/kothapalli_waterfalls.jpg', 'EASY', 4.4, 6165, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Maredumilli Eco-Tourism Corridor (Jalatharangini & Amruthadhara)', 'maredumilli-eco-tourism-corridor-jalatharangini-amruthadhara', 'Maredumilli is a village and prominent eco-tourism destination located in the Alluri Sitharama Raju district of Andhra Pradesh, India, located within the semi-evergreen forests of the Eastern Ghats and renowned for its rich biodiversity, undulating terrain, and cascading streams.', 'Nature & Wildlife', 'Andhra Pradesh', 'Alluri Sitharama Raju (ASR) District', 'Maredumilli', '08:00 AM', '04:30 PM', 30, '', 'EASY', 4.5, 539, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Gudisa Grassland Plateau & Hilltop Cloud Camp', 'gudisa-grassland-plateau-hilltop-cloud-camp', 'High-altitude rolling grassland plateau situated at 1,250m elevation near Maredumilli, celebrated for its 360-degree horizon and mesmerizing sea of clouds at sunrise.', 'Nature & Wildlife', 'Andhra Pradesh', 'Alluri Sitharama Raju (ASR) District', 'Maredumilli', '06:00 AM', '04:00 PM', 50, '', 'EASY', 4.6, 85, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Rampa Waterfalls & Sri Rameswara Shiva Temple', 'rampa-waterfalls-sri-rameswara-shiva-temple', 'Cascading forest stream falling into a rocky plunge pool located within the dense Eastern Ghats jungle near Chodavaram, adjacent to an ancient 8th-century Shiva shrine where Lord Rama is traditionally believed to have worshipped.', 'Waterfalls & Gorges', 'Andhra Pradesh', 'Alluri Sitharama Raju (ASR) District', 'Rampachodavaram', '08:00 AM', '05:00 PM', 20, '', 'EASY', 4.3, 2129, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Polluru (Mothugudem) Waterfalls', 'polluru-mothugudem-waterfalls', 'Polluru Waterfalls, also known as Mothugudem Waterfalls, Located in Andhra Pradesh is a popular destination. amidst the lush greenery of the Eastern Ghats, this pristine waterfall is a popular weekend getaway near Rajahmundry and Bhadrachalam. Location of Polluru Waterfalls District: Alluri Sitharama Raju (formerly part of East Godavari district)', 'Waterfalls & Gorges', 'Andhra Pradesh', 'Alluri Sitharama Raju (ASR) District', 'Mothugudem', '08:30 AM', '04:30 PM', 30, '', 'EASY', 4.5, 1988, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Papikondalu Godavari River Cruise Boarding Points', 'papikondalu-godavari-river-cruise-boarding-points', 'Scenic riverboat boarding points (Polavaram / Pochavaram / Gandi Posamma) for navigating the deep Godavari River gorge carving through the grand Papikonda hill range between Rajahmundry and Bhadrachalam.', 'Waterfalls & Gorges', 'Andhra Pradesh', 'Alluri Sitharama Raju (ASR) District', 'Devipatnam', '08:30 AM', '06:30 PM', 1, '/images/aptourism/papikondalu_boat_cruise.jpg', 'EASY', 4.8, 84, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ananthagiri Coffee Plantations & Waterfalls', 'ananthagiri-coffee-plantations-waterfalls', 'Ananthagiri Hills & Coffee Estates: Often called a "health resort" due to its pristine air, Ananthagiri is famous for its extensive organic coffee plantations. Eco-tourists visit for the numerous waterfalls, specifically the Tadimada (Ananthagiri) Waterfalls, which are surrounded by lush greenery and offer hiking opportunities.', 'Waterfalls & Gorges', 'Andhra Pradesh', 'Alluri Sitharama Raju (ASR) District', 'Ananthagiri', '08:00 AM', '05:30 PM', 0, '/images/aptourism/anantagiri_hills.jpg', 'EASY', 4.4, 2274, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('INS Kurusura Submarine Museum', 'ins-kurusura-submarine-museum', 'INS Kursura (S20) was a Kalvari -class (variant of the Foxtrot-class) diesel-electric submarine of the Indian Navy. It was India''s fourth submarine. Kursura was commissioned on 18 December 1969 and was decommissioned on 27 February 2001 after 31 years of service.', 'Artisans & Culture', 'Andhra Pradesh', 'Visakhapatnam District', 'Visakhapatnam Urban (Beach Road)', '02:00 PM', '08:30 PM', 70, '', 'EASY', 4.6, 54682, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('TU-142M Aircraft Museum', 'tu-142m-aircraft-museum', 'Massive long-range anti-submarine maritime patrol bomber that flew for 29,000 hours without an accident. Interior cockpit and radar console walk.', 'Artisans & Culture', 'Andhra Pradesh', 'Visakhapatnam District', 'Visakhapatnam Urban (Beach Road)', '02:00 PM', '08:30 PM', 70, '', 'EASY', 4.6, 6089, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sea Harrier Museum (Victory at Sea)', 'sea-harrier-museum-victory-at-sea', 'The museum provides detailed information the aircraft''s features, operational history, and its role in strengthening India''s maritime defense. Visitors can closely observe the design, weapon systems, and advanced technology that made the Sea Harrier one of the most effective naval fighter aircraft of its time.', 'Artisans & Culture', 'Andhra Pradesh', 'Visakhapatnam District', 'Visakhapatnam Urban (Beach Road)', '02:00 PM', '08:30 PM', 50, '', 'EASY', 4.6, 6556, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kailasagiri Hilltop Park & Ropeway', 'kailasagiri-hilltop-park-ropeway', 'Kailasagiri is a hilltop park in the city of Visakhapatnam in the Indian state of Andhra Pradesh. The park was developed by the Visakhapatnam Metropolitan Region Development Authority (VMRDA) and consists of land filled with native trees and other flora.', 'Scenic & Cultural', 'Andhra Pradesh', 'Visakhapatnam District', 'Visakhapatnam Urban', '06:00 AM', '08:00 PM', 20, '/images/aptourism/kailasagiri_hill.jpg', 'EASY', 4.6, 785, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Rushikonda Beach (Blue Flag Certified)', 'rushikonda-beach-blue-flag-certified', 'Rushikonda Beach in Visakhapatnam regains its ''Blue Flag'' certification, thanks to conservation efforts ensuring cleanliness, sustainability, and eco-tourism appeal.', 'Scenic & Cultural', 'Andhra Pradesh', 'Visakhapatnam District', 'Bheemunipatnam', '06:00 AM', '06:00 PM', 0, '', 'EASY', 4.6, 10216, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ramakrishna (RK) Beach & Seafront Promenade', 'ramakrishna-rk-beach-seafront-promenade', 'Ramakrishna Beach also known as R K Beach is situated on the east coast of Bay of Bengal in Visakhapatnam, Andhra Pradesh. It is located near Dolphin''s Nose. Ramakrishna Math, Visakhapatnam Ramakrishna Mission Ashrama Library, Visakhapatnam Statue of Sri Vivekananda Swamy, Ramakrishna Math, Visakhapatnam RK Beach gets its name from the Ramakrishna Mission ashram situated near the beach.', 'Scenic & Cultural', 'Andhra Pradesh', 'Visakhapatnam District', 'Visakhapatnam Urban', '05:00 AM', '07:30 AM', 0, '', 'EASY', 4.5, 51122, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Yarada Beach & Dolphin''s Nose Lighthouse', 'yarada-beach-dolphin-s-nose-lighthouse', 'Dolphin''s Nose is a hill in Visakhapatnam between Yarada and Gangavaram Port. The hill is named Dolphin''s Nose because it resembles a dolphin''s nose. It is a conspicuous land mark in Visakhapatnam. Dolphin''s Nose is a huge rocky head land which is 174 meters high and 358 meters above sea level.', 'Scenic & Cultural', 'Andhra Pradesh', 'Visakhapatnam District', 'Pedagantyada', '06:00 AM', '05:00 PM', 0, '', 'EASY', 4.4, 7330, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Varaha Lakshmi Narasimha Swamy Temple (Simhachalam)', 'sri-varaha-lakshmi-narasimha-swamy-temple-simhachalam', 'Sri Varaha Lakshmi Narasimha temple, Simhachalam, is a Hindu temple situated on the Simhachalam Hill Range, which is 300 metres above the sea level in the city of Visakhapatnam, Andhra Pradesh, India. It is dedicated to Lord Vishnu, who is worshipped there as Varaha Narasimha.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Visakhapatnam District', 'Gopalapatnam', '07:00 AM', '09:00 PM', 0, '', 'EASY', 4.7, 70128, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Thotlakonda & Bavikonda Buddhist Complexes', 'thotlakonda-bavikonda-buddhist-complexes', 'Thotlakonda Buddhist Complex is situated on a hill near Bheemunipatnam about 15 kilometres (9.3 mi) from Visakhapatnam in Andhra Pradesh, India. The hill is about 128 metres (420 ft) above sea level and overlooks the ocean.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Visakhapatnam District', 'Bheemunipatnam', '08:00 AM', '05:30 PM', 20, '', 'EASY', 4.3, 9114, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Bheemunipatnam (Bheemili) Dutch Cemetery & Beach', 'bheemunipatnam-bheemili-dutch-cemetery-beach', 'A winding road through one of the narrow lanes of Bheemunipatnam leads to a 17th-Century Dutch cemetery at Kummaripalem. One has to ask the locals how to get there as there is no signage.', 'Scenic & Cultural', 'Andhra Pradesh', 'Visakhapatnam District', 'Bheemunipatnam', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.3, 19, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Indira Gandhi Zoological Park & Kambalakonda Eco-Park', 'indira-gandhi-zoological-park-kambalakonda-eco-park', 'Gharial Indira Gandhi Zoological Park is located amidst Kambalakonda Reserve Forest in Visakhapatnam, Andhra Pradesh, India. It is the third largest zoo in the country. The zoological park is named after the former Prime Minister of India, Indira Gandhi. It was declared open to the public on 19 May 1977.', 'Nature & Wildlife', 'Andhra Pradesh', 'Visakhapatnam District', 'Visakhapatnam Urban / Anandapuram', '09:00 AM', '05:00 PM', 50, '', 'EASY', 4.2, 28117, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Tenneti Park & Shipwreck Beach Viewpoint', 'tenneti-park-shipwreck-beach-viewpoint', 'Tenneti Park also known as (Vuda Tenneti Park) is an urban park in the city of Visakhapatnam. It is a coastal park in the city known for its scenery and recreational amenities.', 'Scenic & Cultural', 'Andhra Pradesh', 'Visakhapatnam District', 'Visakhapatnam Urban', '06:00 AM', '08:30 PM', 0, '', 'EASY', 4.5, 29781, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
