INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('V. Madugula & Authentic Dangeti Madugula Halwa', 'v-madugula-authentic-dangeti-madugula-halwa', 'Our Process Crafting the Perfect Madugula Halwa Every batch of our halwa is handmade using time-honored techniques, pure ghee, and wheat milk — maintaining the same authentic taste passed down over generations.', 'Artisans & Culture', 'Andhra Pradesh', 'Anakapalli District', 'V. Madugula', '08:30 AM', '09:00 PM', 0, '', 'EASY', 4.7, 220, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Bojjannakonda & Lingalakonda Buddhist Monasteries', 'bojjannakonda-lingalakonda-buddhist-monasteries', 'Bojjannakonda and Lingalakonda are two rock-cut caves of Buddhist origin on adjacent hillocks situated near the village of Sankaram, Anakapalle of ancient Kalinga in the Indian state of Andhra Pradesh.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Anakapalli District', 'Sankaram (Anakapalli)', '09:00 AM', '05:30 PM', 0, '', 'EASY', 4.4, 1868, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kondakarla Ava Freshwater Lake & Bird Sanctuary', 'kondakarla-ava-freshwater-lake-bird-sanctuary', 'Kondakarla Ava is a lake and bird sanctuary in Anakapalli district in Andhra Pradesh state in South India. It has a unique and endangered forest in the foothills of the Eastern Ghats.', 'Lakes, Dams & Waterways', 'Andhra Pradesh', 'Anakapalli District', 'Atchutapuram', '06:30 AM', '05:00 PM', 20, '', 'EASY', 4.6, 348, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Anakapalli Jaggery Market (South India''s Jaggery Capital)', 'anakapalli-jaggery-market-south-india-s-jaggery-capital', 'History Anakapalle is a suburb of Visakhapatnam in the Indian state of Andhra Pradesh. The municipality was merged with Greater Visakhapatnam Municipal Corporation. It has the second largest jaggery market of the country.', 'Scenic & Cultural', 'Andhra Pradesh', 'Anakapalli District', 'Anakapalli', '08:00 AM', '03:00 PM', 0, '', 'EASY', 4.4, 699, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Nookambika Ammavari Temple', 'sri-nookambika-ammavari-temple', 'Sri Sri Nookambika Ammavari Temple or Sri Nookallamma Ammavaari Devasthanamu, is a temple located in Gavarapalem in the municipality of Anakapalli near the southeastern coast of India. The temple houses the goddess Nookambika. The King who ruled this area - Sri Kakarlapudi Appala Raju Payakarao, built this temple to Kakatambika, a family goddess.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Anakapalli District', 'Anakapalli', '05:30 AM', '09:00 PM', 0, '', 'EASY', 4.7, 4121, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Panchadarla Sri Dharmalingeswara Alayam', 'panchadarla-sri-dharmalingeswara-alayam', 'An Ancient Lord Shiva Teple is located in Panchadarla village of Rambilli Mandal of Anakapalli District. It is one of the ancient Shiva Temples of Andhra Pradesh. that is believed to have been built in the 9th century by the Eastern Chalukya Cholas.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Anakapalli District', 'Munagapaka / Kasimkota border', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.6, 415, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Devipuram Sri Chakra Maha Meru Temple', 'devipuram-sri-chakra-maha-meru-temple', 'Overview Devipuram''s primary focus is the Sahasrakshi Meru Temple, a unique three-story structure built in the shape of a Sri Meru Yantra; i.e., three-dimensional projection of the sacred Hindu diagram known as Sri Chakra, which is central to Srividya upasana (an ancient and intricate form of Tantric Shakta worship).', 'Heritage & Spiritual', 'Andhra Pradesh', 'Anakapalli District', 'Parawada', '07:00 AM', '07:30 PM', 0, '', 'EASY', 4.5, 1177, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Seethapalem Beach & Natural Cliff Cove', 'seethapalem-beach-natural-cliff-cove', 'The town was originally under the rule of the Kalinga Empire (ancient Orissa), different dynasties ruled this region i.e. Chedi Kingdom of Kalinga (Orissa), Eastern Ganga dynasty of Orissa, Gajapati Kingdom of Orissa, Kakatiya, and Qutub Shahi empires.', 'Scenic & Cultural', 'Andhra Pradesh', 'Anakapalli District', 'Atchutapuram', '06:00 AM', '06:00 PM', 0, '', 'EASY', 4.6, 300, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Pudimadaka Beach & Coastal Lighthouse Promontory', 'pudimadaka-beach-coastal-lighthouse-promontory', 'Pudimadaka Lighthouse There is a lighthouse at Pudimadaka village. It was first time commissioned in 1971 and renovated in 1991. The lighthouse was on a masonry tower of 26 meters height. It has a visible range of 27 nautical miles.', 'Scenic & Cultural', 'Andhra Pradesh', 'Anakapalli District', 'Atchutapuram', '06:00 AM', '06:00 PM', 0, '', 'EASY', 3.9, 1080, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Upamaka Sri Venkateswara Swamy Temple', 'upamaka-sri-venkateswara-swamy-temple', 'Upamaka Temple view near Nakkapalli Upamaka is a village in Nakkapalle mandal of Anakapalli district of Andhra Pradesh in India, where an ancient temple of Lord Venkateswara Swamy is present.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Anakapalli District', 'Nakkapalli', '06:00 AM', '08:00 PM', 0, '/images/candidates/tirupati/sri-venkateswara-swamy-vaari-temple-tirupati-andhra-pradesh-1-new-attr-popular.jpg', 'EASY', 4.7, 850, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
