INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ramanarayanam (Srimadramayana Pranganam)', 'ramanarayanam-srimadramayana-pranganam', 'Ramanarayanam is a Hindu temple located on Korukonda Road in Vizianagaram, Andhra Pradesh, India. The temple is themed on the Ramayana and is designed in the shape of a bow and arrow.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Vizianagaram District', 'Vizianagaram (Korukonda Road)', '10:00 AM', '08:30 PM', 0, '', 'EASY', 4.7, 9654, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
