INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Bobbili Veena GI Craft Guild', 'bobbili-veena-gi-craft-guild', 'Bobbili Veena is considered to be invented in Bobbili of Vizianagaram district, Andhra Pradesh. The making of the Veena started in the 17th century during the reign of Pedda Rayudu. At that time, playing Veena was a common practice in India, specially South India. The entire development process of the Veena took more than three centuries.', 'Artisans & Culture', 'Andhra Pradesh', 'Vizianagaram District', 'Bobbili', '09:00 AM', '06:00 PM', 0, '/images/aptourism/bobbili_veena.jpg', 'EASY', 5, 9, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
