INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Addapuseela Sri Kasi Visweswara Swamy Temple', 'addapuseela-sri-kasi-visweswara-swamy-temple', 'Kaasi Visweswara temple This temple is located in Addapuseela Village in Parvathipuram Mandal located at 4 KM away from parvathipuram town.. it is a 15th Century temple. Temple timings are 5 AM to 12 PmM and 4 PM to 7 PM. Shivaratri, Karitika Masam, Shravana Masam, Dola Yatra are festivals celebrated here.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Parvathipuram Manyam District', 'Parvathipuram', '06:00 AM', '07:30 PM', 0, '/images/candidates/parvathipurammanyam/2022031982.jpg', 'EASY', 4.6, 95, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kurupam Heritage Palace & Royal Gardens', 'kurupam-heritage-palace-royal-gardens', 'Culture & Heritage Brief History Of Kurupam Palace Primarily constructed in 1878, the present edifice is a unique medley of architectural style.The overal appearance has been mainaine just as stately and grand as it was originally envisioned. Different generations took to ading extensions to the fort in different eras.', 'Historical Forts & Monuments', 'Andhra Pradesh', 'Parvathipuram Manyam District', 'Kurupam', '09:00 AM', '05:00 PM', 0, '', 'EASY', 4.3, 184, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Salur Ghats & Sunki Pass (Odisha Gateway)', 'salur-ghats-sunki-pass-odisha-gateway', 'This disrict is newly formed disrtrict as per the state bifurcation with head quarters as Parvthipuram town. This consists of 16 mandals and 2 Revenue Divisions.', 'Scenic & Cultural', 'Andhra Pradesh', 'Parvathipuram Manyam District', 'Salur', '06:00 AM', '06:30 PM', 0, '', 'EASY', 4.5, 105, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sambara Polamamba Ammavari Temple', 'sambara-polamamba-ammavari-temple', 'Explore Sri Polamamba Ammavari Temples in Sambara, Manyam. Check darshan timings, history, deity details, location map, and travel guide.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Parvathipuram Manyam District', 'Makkuva', '06:00 AM', '08:00 PM', 0, '/images/candidates/parvathipurammanyam/2022030762.jpg', 'EASY', 4.7, 313, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Suryanarayana Swamy Temple (Arasavalli)', 'sri-suryanarayana-swamy-temple-arasavalli', 'Arasavalli Sri Surya Narayana Swamy Devalayam is a temple for Lord Surya, the solar deity, at Arasavalli in the Indian state of Andhra Pradesh. It is located in Arasavalli Village 1 km east of Srikakulam.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Srikakulam District', 'Srikakulam Urban', '06:00 AM', '08:00 PM', 0, '', 'EASY', 4.7, 16851, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Kurmanatha Swamy Temple (Srikurmam)', 'sri-kurmanatha-swamy-temple-srikurmam', 'Underground tunnel to Varanasi The Kurmanathaswamy temple, also known as the Kurmanatha temple, Srikurma or Srikurmam temple, is a Hindu temple dedicated to Kurma - the second avatar of Vishnu. It is located in Srikurmam village, Srikakulam district in Andhra Pradesh, India.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Srikakulam District', 'Gara', '06:00 AM', '08:00 PM', 0, '', 'EASY', 4.7, 8246, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Mukhalingam Kalinga Temples (Madhukeswara Swamy)', 'sri-mukhalingam-kalinga-temples-madhukeswara-swamy', 'Mukhalingam, also known as Srimukhalingam or Mukhalinga, is a village and gram panchayat in Jalumuru mandal of Srikakulam district in the Indian state of Andhra Pradesh. Historically known as Kalinganagari, Mukhalingam served as the capital of the Eastern Ganga dynasty from the 6th to the 12th century.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Srikakulam District', 'Jalumuru', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.7, 2441, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Salihundam Buddhist Heritage Stupa Complex', 'salihundam-buddhist-heritage-stupa-complex', 'Salihundam, is a village and panchayat in Gara Mandal of Srikakulam district in Andhra Pradesh. It is a historically important Buddhist monument of ancient Kalinga and a major tourist attraction It is a village lying on top of the hill on the south bank of the Vamsadhara River.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Srikakulam District', 'Gara', '08:30 AM', '05:30 PM', 25, '/images/aptourism/salihundam.jpg', 'EASY', 4.5, 736, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kalingapatnam Beach & Colonial Lighthouse', 'kalingapatnam-beach-colonial-lighthouse', 'Field guide to Kalingapatnam Beach in Srikakulam, Andhra Pradesh: 1876 operational lighthouse, Vamsadhara river confluence, Buddhist Salihundam, and travel info.', 'Scenic & Cultural', 'Andhra Pradesh', 'Srikakulam District', 'Gara', '03:00 PM', '05:00 PM', 0, '/images/aptourism/kalingapatnam_beach.jpg', 'EASY', 4.2, 332, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ponduru Khadi GI Craft Village', 'ponduru-khadi-gi-craft-village', 'Ponduru is famous across India for producing superfine hand-spun khadi cotton cloth, crafted by local weaving families using indigenous hill cotton and traditional wooden instruments.', 'Artisans & Culture', 'Andhra Pradesh', 'Srikakulam District', 'Ponduru', '09:30 AM', '06:00 PM', 0, '', 'EASY', 4.4, 271, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Telineelapuram & Telukunchi Bird Sanctuaries', 'telineelapuram-telukunchi-bird-sanctuaries', 'Telineelapuram and Telukunchi Bird Sanctuaries are located in Srikakulam district of Andhra Pradesh, India. Telineelapuram is a village located 65 kilometres (40 mi) from Srikakulam in Tekkali mandal, while Telukunchi is at a distance of 115 kilometres (71 mi) from Srikakulam in Ichchapuram mandal.', 'Scenic & Cultural', 'Andhra Pradesh', 'Srikakulam District', 'Tekkali / Santhabommali', '06:30 AM', '05:30 PM', 0, '', 'EASY', 4.5, 631, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Baruva Beach & Someshwara Temple', 'baruva-beach-someshwara-temple', 'Baruva Beach is one of the oldest beaches in Andhra Pradesh. It was used as seaport until 1948. On the beach is a commemorative pillar placed in remembrance of a cargo ship that sank nearby in 1917. It is also called as the second Goa of India.', 'Scenic & Cultural', 'Andhra Pradesh', 'Srikakulam District', 'Sompeta', '06:00 AM', '06:00 PM', 0, '', 'EASY', 4.4, 487, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Mandasa Vasudeva Perumal Temple & Fort', 'mandasa-vasudeva-perumal-temple-fort', 'Sri Vasudeva Perumal Temple is located in Mandasa village, about 15 km from Palasa in Srikakulam district. Built during the 14th century, the temple stands as a remarkable symbol of Sri Vaishnava heritage and Odisha style architecture.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Srikakulam District', 'Mandasa', '06:30 AM', '07:30 PM', 0, '', 'EASY', 4.7, 317, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kaviti & Sompeta ''Uddanam'' Coastal Coconut & Cashew Belt', 'kaviti-sompeta-uddanam-coastal-coconut-cashew-belt', 'Kaviti village is located at a distance of 130 Kms. from District head quarters in between two towns Viz Sompeta and Ichapuram, towards East. The area constituting Kaviti Mandal is populary known as Uddanam (Udyanavanam). The coastal belt at this place presents a pleasant appearance, covered with large extents of Coconut, Cashewnut, Jack and other fruit trees.', 'Scenic & Cultural', 'Andhra Pradesh', 'Srikakulam District', 'Kaviti', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.3, 83, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Palasa Cashew Processing Capital of South India', 'palasa-cashew-processing-capital-of-south-india', 'Palasa is a significant center for cashew production in Andhra Pradesh, with more than 350 cashew processing industries operating in the region. Making it the highest among the northern coastal districts in Andhra Pradesh. The town''s prominence in cashew processing also makes it one of the largest cashew processing hubs in India.', 'Scenic & Cultural', 'Andhra Pradesh', 'Srikakulam District', 'Palasa', '09:00 AM', '08:30 PM', 0, '', 'EASY', 4.8, 98, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ichchapuram & Bahuda River Estuary', 'ichchapuram-bahuda-river-estuary', 'scenic coastal confluence where the Bahuda River meets the Bay of Bengal near the Andhra-Odisha border, noted for coconut groves and tranquil backwaters.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Srikakulam District', 'Ichchapuram', '06:00 AM', '07:00 PM', 0, '', 'EASY', 4.3, 52, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Coringa Wildlife Sanctuary & Mangrove Boardwalk', 'coringa-wildlife-sanctuary-mangrove-boardwalk', 'Coringa Wildlife Sanctuary is an estuary situated near Kakinada in Andhra Pradesh, India. It is the third largest stretch of mangrove forests in India with 24 mangrove tree species and more than 120 bird species.', 'Nature & Wildlife', 'Andhra Pradesh', 'Kakinada District', 'Thallarevu', '09:00 AM', '05:00 PM', 50, '/images/aptourism/coringa_wildlife_sanctuary.jpg', 'EASY', 4.2, 6095, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Hope Island & Natural Harbor Sand Spit', 'hope-island-natural-harbor-sand-spit', 'Hope Island protects the city of Kakinada from the strong storm surges coming from the Bay of Bengal.', 'Scenic & Cultural', 'Andhra Pradesh', 'Kakinada District', 'Kakinada Port', '07:00 AM', '04:00 PM', 2, '', 'EASY', 4, 262, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Veera Venkata Satyanarayana Swamy Temple (Annavaram)', 'sri-veera-venkata-satyanarayana-swamy-temple-annavaram', 'Sri Veera Venkata Satyanarayana Swamy Temple is a Hindu - Vaishnavite temple located in Annavaram in Kakinada district of Andhra Pradesh, India. Dedicated to Lord Satyanarayana Swamy, an incarnation of Lord Vishnu, the temple is situated on Ratnagiri Hill. It is one of the most visited religious sites in Andhra Pradesh and is recognized as one of the state''s wealthiest temples.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Kakinada District', 'Annavaram', '05:00 AM', '09:00 PM', 0, '', 'EASY', 4.7, 30663, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Kukkuteswara Swamy & Pada Gaya Kshetram (Pithapuram)', 'sri-kukkuteswara-swamy-pada-gaya-kshetram-pithapuram', 'The Kukkuteswara Temple or Sri Kukkuteswara Swami Temple is a Hindu temple in Pitapuram town of Kakinada district, Andhra Pradesh, India. The temple is prominent in both Saivite and Shakta Hindu traditions.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Kakinada District', 'Pithapuram', '05:30 AM', '08:30 PM', 0, '', 'EASY', 4.7, 12491, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Draksharamam Bhimeswara Swamy Temple (Pancharama Kshetram)', 'draksharamam-bhimeswara-swamy-temple-pancharama-kshetram', 'Draksharamam or Daksharamam is one of the five Pancharama Kshetras, Trilinga Kshetras that are sacred to the Hindu god Shiva and also 12th of Ashtadasha Shakthi Peetams. The temple is located in Draksharamam town of Konaseema district in the Indian state of Andhra Pradesh.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Kakinada District', 'Ramachandrapuram', '06:00 AM', '08:00 PM', 0, '', 'EASY', 4.8, 13545, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Uppada Jamdani Handloom Silk Village (GI Tag)', 'uppada-jamdani-handloom-silk-village-gi-tag', 'The Government of India have identified Uppada Jamdhani Sarees as One District One Product in Kakinada District. The idea is to select, brand, and promote One Product from each District of the country,', 'Artisans & Culture', 'Andhra Pradesh', 'Kakinada District', 'U.Kothapalli', '08:30 AM', '07:00 PM', 0, '', 'EASY', 4.9, 156, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Samalkota Kumararama Bhimeswara Swamy Temple', 'samalkota-kumararama-bhimeswara-swamy-temple', 'Kumararama or Bhimarama (Chalukya Kumararama Bhimeswara Temple) is one of the five Pancharama Kshetras that are sacred to the Hindu god Shiva. The temple is located in Samalkota of Kakinada district in the Indian state of Andhra Pradesh.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Kakinada District', 'Samalkota', '06:00 AM', '08:00 PM', 0, '', 'EASY', 4.8, 5493, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kakinada Kaja Sweet Guilds (Kotaiah Kaja & Gottam Kaja)', 'kakinada-kaja-sweet-guilds-kotaiah-kaja-gottam-kaja', 'Kakinada Kaja (Telugu: కాకినాడ కాజా) is a traditional Indian sweet pastry from Kakinada, Andhra Pradesh, India, known for its unique taste and preparation. It comes in two main varieties: the hollow, cylindrical Gottam Kaja and the layered Madatha Kaja, each offering distinct textures and flavours.', 'Scenic & Cultural', 'Andhra Pradesh', 'Kakinada District', 'Kakinada Urban', '08:00 AM', '10:00 PM', 0, '', 'EASY', 4, 7432, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kakinada Subbayya Gari Hotel (Iconic Andhra Butta Bhojanam)', 'kakinada-subbayya-gari-hotel-iconic-andhra-butta-bhojanam', 'Subbayya Gari Hotel (also known as Kakinada Vaari Subbayya Gari Hotel) is an Indian chain of vegetarian restaurants headquartered in Kakinada, Andhra Pradesh. Founded in 1950 by G. Subbayya, the establishment is renowned for its traditional Andhra cuisine, particularly its signature "Butta Bhojanam" served on banana leaves.', 'Scenic & Cultural', 'Andhra Pradesh', 'Kakinada District', 'Kakinada Urban', '11:30 AM', '10:30 PM', 220, '', 'EASY', 4.2, 18831, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('NTR Beach & Kakinada Harbor Coastal Promenade', 'ntr-beach-kakinada-harbor-coastal-promenade', 'Kakinada, a coastal city in Andhra Pradesh, has a rich history dating back to ancient times, being part of the Kalinga and Andhra kingdoms and later ruled by various South Indian dynasties. The city evolved from its original name Kakanandivada to Kakinada and became significant during the colonial period as a port town known for shipbuilding and agriculture.', 'Scenic & Cultural', 'Andhra Pradesh', 'Kakinada District', 'Kakinada Urban', '06:00 AM', '09:00 PM', 0, '/images/candidates/kakinada/kakinada-beach-kakinada-andhra-pradesh-1-attr-nearby.jpg', 'EASY', 4.1, 1773, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Yanam River Estuary & French Enclave Border', 'yanam-river-estuary-french-enclave-border', 'Explore Yanam enclave in Puducherry — Godavari river delta, French colonial obelisk, Coringa mangrove gateway, and Telugu-French coastal culture.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Kakinada District', 'Thallarevu border', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.2, 1762, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Tuni Betel Leaf & Bamboo Craft Corridor', 'tuni-betel-leaf-bamboo-craft-corridor', 'It is a commercial marketing centre for more than 200 surrounding villages in the district. Tuni is a border point for the district of Kakinada. It is known for mango production, with nearly 250 varieties being exported from the area; Tuni City is known as "Mango City". Tuni is also known for the production of betel leaves and jute bags.', 'Artisans & Culture', 'Andhra Pradesh', 'Kakinada District', 'Tuni', '07:00 AM', '08:00 PM', 0, '', 'EASY', 4.5, 2500, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Antarvedi Sri Lakshmi Narasimha Swamy & Sagara Sangamam', 'antarvedi-sri-lakshmi-narasimha-swamy-sagara-sangamam', 'Sri Lakshmi Narasimha Swamy Temple in Antarvedi is a sacred pilgrimage site at the Godavari Sagara sangamam, known for its ancient history, rituals, festivals and spiritual significance.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Dr. B.R. Ambedkar Konaseema District', 'Sakhinetipalli', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.7, 10901, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Dindi Backwaters & Godavari Luxury Houseboats', 'dindi-backwaters-godavari-luxury-houseboats', 'The visual identity of Konaseema district is coconut emerald green and delta sunrise sand gold.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Dr. B.R. Ambedkar Konaseema District', 'Malikipuram', '09:00 AM', '12:00 PM', 600, '', 'EASY', 4.4, 1684, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
