INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kovvur Goshpada Kshetram & Sacred Bathing Ghats', 'kovvur-goshpada-kshetram-sacred-bathing-ghats', 'Gopadala Ghat, also known as Goshpada Kshetram, is a significant bathing ghat on the banks of the Godavari River in Kovvur, near Rajahmundry. It is believed to be one of the oldest and most historically important bathing ghats on the Godavari.', 'Scenic & Cultural', 'Andhra Pradesh', 'East Godavari District', 'Kovvur', '05:00 AM', '08:30 PM', 0, '', 'EASY', 4.6, 707, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
