INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Tapaswaram Madhuram Sweets Guilds (Origin of Madatha Kaja)', 'tapaswaram-madhuram-sweets-guilds-origin-of-madatha-kaja', 'Tapeswaram Kaja This variant, originating from Tapeshwaram, is also known as Madatha Kaja. It features a perfectly layered structure, made by rolling the maida -and- ghee dough into thin sheets, folding them into diamond shapes, and cutting them into smaller pieces before frying and soaking them in sugar syrup.', 'Scenic & Cultural', 'Andhra Pradesh', 'East Godavari District', 'Mandapeta border', '08:30 AM', '09:00 PM', 0, '', 'EASY', 4.7, 9266, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
