INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Bondada Wetland & Winter Waterbird Refuge', 'bondada-wetland-winter-waterbird-refuge', 'Bondada Foundation is the social impact initiative of the Bondada Group, building on a strong legacy of innovation, responsibility and community development. Together, we are committed to creating meaningful and sustainable change across communities through education, healthcare, rural development, sports and social transformation.', 'Scenic & Cultural', 'Andhra Pradesh', 'West Godavari District', 'Kalla', '06:30 AM', '05:30 PM', 0, '', 'EASY', 4.4, 2234, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Maruteru Agricultural Research Station & Paddy Fields', 'maruteru-agricultural-research-station-paddy-fields', 'Marteru is a village in Penumantra mandal of West Godavari district, Andhra Pradesh, India, situated in the fertile Godavari delta region and renowned for its important role in rice research and agriculture.', 'Scenic & Cultural', 'Andhra Pradesh', 'West Godavari District', 'Penumantra', '09:30 AM', '05:00 PM', 0, '', 'EASY', 4.7, 70, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Dwaraka Tirumala Sri Venkateswara Swamy Temple (Chinna Tirupati)', 'dwaraka-tirumala-sri-venkateswara-swamy-temple-chinna-tirupati', 'Sri Venkateswara Temple is a Hindu temple located in Dwaraka Tirumala of Eluru district in the Indian state of Andhra Pradesh. It is dedicated to Lord Venkateswara, an incarnation of Lord Vishnu. Known as "Chinna Tirupati" (transl. "Mini Tirupati"), it is considered a spiritual alternative to the famous Tirupati temple.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Eluru District', 'Dwaraka Tirumala', '06:00 AM', '09:00 PM', 0, '', 'EASY', 4.8, 12956, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kolleru Lake & Atapaka Pelican Bird Sanctuary', 'kolleru-lake-atapaka-pelican-bird-sanctuary', 'Atapaka (Kolleru) Bird Sanctuary, situated in the Eluru & Krishna district of Andhra Pradesh, is one of India''s most celebrated avian sanctuaries. Atapaka Bird Sanctuary, located within the expansive Kolleru Lake ecosystem in Andhra Pradesh, is one of Asia''s largest nesting havens for the vulnerable Spot-billed Pelican and Painted Stork.', 'Lakes, Dams & Waterways', 'Andhra Pradesh', 'Eluru District', 'Kaikalur border / Nidamarru', '06:00 AM', '06:00 PM', 20, '', 'EASY', 4.3, 56, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Guntupalli (Kamavarapukota) Buddhist Rock Caves', 'guntupalli-kamavarapukota-buddhist-rock-caves', 'The Guntupalle or Guntupalli Group of Buddhist Monuments is located near Kamavarapukota, Eluru district, in the state of Andhra Pradesh in India. It is around 40 km away from Eluru. The rock-cut part of the site has two Buddhist caves, a chaitya hall and a large group of stupas.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Eluru District', 'Kamavarapukota', '09:00 AM', '05:30 PM', 0, '', 'EASY', 4.3, 1078, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Polavaram National Irrigation Mega Project & Viewpoint', 'polavaram-national-irrigation-mega-project-viewpoint', 'The Polavaram Project is an under-construction multi-purpose irrigation project on the Godavari River in the Eluru District and Polavaram District in Andhra Pradesh, India. The project has been accorded National Project status by the Central Government of India. Its reservoir back water spreads up to the Dummugudem Anicut, i.e.', 'Scenic & Cultural', 'Andhra Pradesh', 'Eluru District', 'Polavaram', '09:00 AM', '05:00 PM', 0, '', 'EASY', 4.4, 56, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Nuzvid GI Mango Orchards & Historic Fort', 'nuzvid-gi-mango-orchards-historic-fort', 'Nuzvid Area History Nuzvid is a mandal and municipality in Krishna District, Andhra Pradesh, India. It is 50 km from Vijayawada and 35 km from Eluru. This place is well connected by bus and rail. Nuzvid is well known for its mangos, which are exported world wide. Nuzvid is a historical fort city in Krishna District, Andhra Pradesh.', 'Historical Forts & Monuments', 'Andhra Pradesh', 'Eluru District', 'Nuzvid', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4, 6, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Agiripalli Sri Sobhanachala Swamy Hill Temple', 'agiripalli-sri-sobhanachala-swamy-hill-temple', 'Sobhanachala Swamy Temple is dedicated to Lord Vishnu and Lord Siva. Devulapalli Achyutabagavantulu built this temple in 1626 A.D. Car (Rathotsavam) festival will be celebrated in a grand, where thousands of devotees participate in this mega event.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Eluru District', 'Agiripalli', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.5, 107, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Eluru Hand-Knotted Wool Pile Carpets (GI Tag)', 'eluru-hand-knotted-wool-pile-carpets-gi-tag', 'The hand knotted carpet industry of Eluru originated in the 13th century when Persian Muslims settled in the Tangellamudi area and introduced the art of weaving woolen pile carpets. By the 1900s, there were over 100 workshops employing around 3000 weavers. Under the British rule, the industry struggled due to changing tastes and weavers seeking other jobs.', 'Artisans & Culture', 'Andhra Pradesh', 'Eluru District', 'Eluru Urban (Sanivarapupeta)', '09:30 AM', '06:00 PM', 0, '', 'EASY', 5, 3, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Pedavegi Ancient Vengi Capital Excavation Site', 'pedavegi-ancient-vengi-capital-excavation-site', 'Vengi or Venginadu (Telugu: వేంగి, IPA: [ʋeːŋɡi]) is a historic region located in present-day Andhra Pradesh, India spread over the Godavari and Krishna river deltas. Its capital was located at Pedavegi, near Eluru.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Eluru District', 'Pedavegi', '09:00 AM', '05:00 PM', 0, '', 'EASY', 4, 154, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Denduluru Someswara Swamy Historic Temple', 'denduluru-someswara-swamy-historic-temple', 'The early rulers of the dynasty migrated from eastern Deccan to the west Deccan in search of employment and under the Vakatakas they might have attained feudatory status. During the reign of Madhava Varma, they became independent and conquered coastal Andhra from the Salankayanas and established their capital at Denduluru near Eluru, West Godavari district.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Eluru District', 'Denduluru', '06:00 AM', '07:30 PM', 0, '', 'EASY', 5, 7, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Jeelugumilli & Buttayagudem Tribal Agency Corridors', 'jeelugumilli-buttayagudem-tribal-agency-corridors', 'Jilugumilli or Jeelugu-milli is a village in Eluru district of the Indian state of Andhra Pradesh.', 'Nature & Wildlife', 'Andhra Pradesh', 'Eluru District', 'Jeelugumilli', '07:00 AM', '05:00 PM', 0, '', 'EASY', 4.5, 2500, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Durga Malleswara Swamy Temple (Kanakadurga, Indrakeeladri)', 'sri-durga-malleswara-swamy-temple-kanakadurga-indrakeeladri', 'Kanaka Durga Temple, officially known as Sri Durga Malleswara Swamyvarla Devasthanam, is a Hindu temple dedicated to Kanaka Durga. The deity in this temple is also popularly referred as Kanaka Durga. The temple is located in Vijayawada, Andhra Pradesh, India on the Indrakeeladri hill on the banks of Krishna River.', 'Heritage & Spiritual', 'Andhra Pradesh', 'NTR District', 'Vijayawada Urban', '04:00 AM', '03:30 PM', 0, '', 'EASY', 4.7, 56503, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Prakasam Barrage & Krishna Riverfront Walkway', 'prakasam-barrage-krishna-riverfront-walkway', 'The Prakasam Barrage is a 1,223.5-metre-long (4,014 ft) tidal barrage across the Krishna River connecting Vijayawada and Guntur districts in Andhra Pradesh, India.', 'Lakes, Dams & Waterways', 'Andhra Pradesh', 'NTR District', 'Vijayawada Urban', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.6, 46610, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Bhavani Island Tourism Resort & Water Adventure Sports', 'bhavani-island-tourism-resort-water-adventure-sports', 'Bhavani Island situated in the midst of the Krishna River, at Vijayawada. It is located at the upstream of Prakasam Barrage and is considered one of the largest river islands in India, with an area of 133 acres (54 ha).', 'Scenic & Cultural', 'Andhra Pradesh', 'NTR District', 'Ibrahimpatnam / Vijayawada Urban', '09:00 AM', '06:00 PM', 120, '/images/aptourism/bhavani_islands.jpg', 'EASY', 4, 1302, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kondapalli Fort & GI-Tagged Wooden Toy Artisans Village', 'kondapalli-fort-gi-tagged-wooden-toy-artisans-village', 'Toy making in Kondapalli had been an industry since 400 years. Kondapalli Village overview History & Significance Kondapalli Toys, also known as Kondapalli Bommalu, are a unique form of Indian wooden toys that originate from the town of Kondapalli in the NTR district of Andhra Pradesh.', 'Historical Forts & Monuments', 'Andhra Pradesh', 'NTR District', 'Kondapalli', '09:00 AM', '08:00 PM', 25, '/images/aptourism/kondapalli.jpg', 'EASY', 4.8, 5, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Bapu Museum (Victoria Jubilee Museum - 1887)', 'bapu-museum-victoria-jubilee-museum-1887', 'The museum was created as part of the celebrations of the Golden Jubilee of Queen Victoria in 1887. The foundation stone was laid by Robert Sewell, District Collector of Krishna district, on 27 June 1887. Sri Pingali Venkayya presented a tri-colour flag to Mahatma Gandhi at this location in 1921. The building initially housed industrial exhibitions.', 'Heritage & Spiritual', 'Andhra Pradesh', 'NTR District', 'Vijayawada Urban', '10:30 AM', '05:00 PM', 50, '', 'EASY', 4.2, 2691, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Mogalarajapuram Rock-Cut Cave Temples', 'mogalarajapuram-rock-cut-cave-temples', 'The Mogalrajapuram Caves are five rock-cut cave temple groups located in different parts of Vijayawada, Andhra Pradesh, India. Dedicated to Shiva, they were excavated during the Eastern Chalukya reign or the Vishnukundins reign. They are generally dated to the 7th century, after the Akkanna Madanna Caves.', 'Heritage & Spiritual', 'Andhra Pradesh', 'NTR District', 'Vijayawada Urban', '09:00 AM', '05:30 PM', 20, '', 'EASY', 3.9, 195, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Gunadala Mary Matha Shrine (St. Mary''s Hill Cathedral)', 'gunadala-mary-matha-shrine-st-mary-s-hill-cathedral', 'Gunadala Matha Shrine (also: Our Lady of Lourdes or Mary Matha Church), located in the city of Vijayawada, Andhra Pradesh, is a renowned Catholic pilgrimage site attracting approximately 10 lakh devotees during its annual festival.', 'Heritage & Spiritual', 'Andhra Pradesh', 'NTR District', 'Vijayawada Urban (Gunadala)', '06:00 AM', '08:30 PM', 0, '', 'EASY', 4.6, 4285, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Penuganchiprolu Sri Tirupatamma Ammavari Temple', 'penuganchiprolu-sri-tirupatamma-ammavari-temple', 'The next day, the idols of Sri Tirupatamma and Gopayya were found and the village head man Sri Srisailapathi constructed the temple at the Yogagni Pyre place. The tiger responsible for the death of Gopayya visited the Holy pyre area and took its breath.', 'Heritage & Spiritual', 'Andhra Pradesh', 'NTR District', 'Penuganchiprolu', '06:00 AM', '08:30 PM', 0, '', 'EASY', 4.7, 9345, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Hinkar Thirtha Jain Temple & Dhyana Mandir', 'hinkar-thirtha-jain-temple-dhyana-mandir', 'Hinkar Thirtha Jain Temple is located in Vijayawada, which is known for its rich cultural heritage, history, and divine surroundings. From ancient rock-cut caves, historical forts, bustling markets, and serene river islands, each site unfolds different aspects of the present and past, making places near Mangalagiri Jain Temple a popular destination place.', 'Heritage & Spiritual', 'Andhra Pradesh', 'NTR District', 'Mangalagiri / Vijayawada border', '06:00 AM', '08:30 PM', 0, '/images/candidates/amaravati/dhyana-buddha-statue-amaravati-vijayawada-andhra-pradesh-1-city-homepage.jpeg', 'EASY', 4.7, 377, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Rajiv Gandhi Park & Musical Laser Fountain', 'rajiv-gandhi-park-musical-laser-fountain', 'NTR Gardens is a small public, urban park of 15 hectares (36 acres) adjacent to Hussain Sagar lake in Hyderabad, where earlier a thermal power station building stood until 1995.', 'Nature & Wildlife', 'Andhra Pradesh', 'NTR District', 'Vijayawada Urban', '02:00 PM', '08:30 PM', 20, '', 'EASY', 3.9, 8572, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Gandhi Hill & Sound and Light Planetarium', 'gandhi-hill-sound-and-light-planetarium', 'The Gandhi Hill (elevation 500 ft (150 m)) is a hill in Vijayawada, situated behind the Vijayawada railway station in the Tarapet area. A Gandhi Memorial, built on this hill, is the first in the country to have seven stupas.', 'Heritage & Spiritual', 'Andhra Pradesh', 'NTR District', 'Vijayawada Urban', '04:30 PM', '08:30 PM', 20, '/images/aptourism/gandhi_hill.jpg', 'EASY', 3.6, 30, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Muktyala Sri Koteswara Swamy Temple & Muktyala Fort', 'muktyala-sri-koteswara-swamy-temple-muktyala-fort', 'The Muktyala Shiva Temple, known as Sri Kotilinga Hari Hara Mahakshetram, is an ancient riverfront pilgrimage shrine situated on the banks of the Krishna River in NTR District.', 'Heritage & Spiritual', 'Andhra Pradesh', 'NTR District', 'Jaggayyapeta', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.6, 276, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Manginapudi Beach & Natural Black Soil Coast', 'manginapudi-beach-natural-black-soil-coast', 'Manginapudi Beach is a famous natural coastal haven and spiritual destination situated in Krishna district, Andhra Pradesh, located 11 km east of Machilipatnam city and 75 km from Vijayawada.', 'Scenic & Cultural', 'Andhra Pradesh', 'Krishna District', 'Machilipatnam', '06:00 AM', '06:30 PM', 0, '', 'EASY', 4.1, 5242, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Pedana Kalamkari GI Handblock Textile Guilds', 'pedana-kalamkari-gi-handblock-textile-guilds', 'Pedana Kalamkari also known as Machilipatnam style of Kalamkari work which involves vegetable dyed block-painting of a fabric. it is produced at Pedana a nearby town of Machilipatnam in Krishna district of the Indian state of Andhra Pradesh.', 'Scenic & Cultural', 'Andhra Pradesh', 'Krishna District', 'Pedana', '08:30 AM', '06:00 PM', 0, '', 'EASY', 3.9, 152, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Mopidevi Sri Subrahmanyeswara Swamy Temple', 'mopidevi-sri-subrahmanyeswara-swamy-temple', 'Sri Subrahmanyeswara Swamy - Mopidevi Kshetra Mahatmyam Blessed by Sage Agastya''s southern pilgrimage, Mopidevi remains a revered shrine of Bala Subrahmanya — renowned for serpent harmony, Shanti Kalyanam, and blessings of progeny and wellness.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Krishna District', 'Mopidevi', '05:30 AM', '08:30 PM', 0, '', 'EASY', 4.7, 11472, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Hamsaladeevi & Krishna Sagara Sangamam Confluence', 'hamsaladeevi-krishna-sagara-sangamam-confluence', 'Hamsaladeevi hosts an old temple of Lord Krishna (Venugopalaswamy), constructed during the rule of Chola kings. It is one of the 108 Vishnu temples. The Krishna River converges into the Bay of Bengal right outside the village. The confluence is known as Sagara Sangamam; three colours of water can be seen there.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Krishna District', 'Koduru', '06:00 AM', '05:30 PM', 0, '/images/candidates/krishna/2022040313.png', 'EASY', 4.1, 52, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ghantasala Buddhist Stupa & Archaeological Museum', 'ghantasala-buddhist-stupa-archaeological-museum', 'Ghantasala Stupa located in the peaceful village of Ghantasala in Andhra Pradesh''s Krishna district, the Ghantasala Stupa stands as one of the most important reminders of the region''s rich Buddhist heritage.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Krishna District', 'Ghantasala', '09:00 AM', '05:00 PM', 0, '', 'EASY', 4.5, 142, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kuchipudi Village & Siddhendra Yogi Classical Dance Academy', 'kuchipudi-village-siddhendra-yogi-classical-dance-academy', 'Kuchipudi (/ ˌkuːtʃɪˈpuːdi / KOO-chih-POO-dee) is one of the eight major Indian classical dance forms. It originated in Kuchipudi, a village in the Indian state of Andhra Pradesh. Kuchipudi is a dance-drama performance, with its roots in the ancient Hindu Sanskrit text of Natya Shastra (c. 500 BCE —500 CE).', 'Scenic & Cultural', 'Andhra Pradesh', 'Krishna District', 'Movva', '09:00 AM', '05:30 PM', 0, '/images/aptourism/kuchipudi.jpg', 'EASY', 4.6, 52, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Machilipatnam Bandar Laddu (GI Tag) & Thoka Kaja Guilds', 'machilipatnam-bandar-laddu-gi-tag-thoka-kaja-guilds', 'Bandar laddu, also known as Thokkudu laddu, is a mithai made with jaggery and ghee from Machilipatnam of Krishna district in the Indian state of Andhra Pradesh.', 'Scenic & Cultural', 'Andhra Pradesh', 'Krishna District', 'Machilipatnam', '08:00 AM', '10:00 PM', 0, '', 'EASY', 4.2, 2755, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Machilipatnam 17th-Century Dutch Fort Belfry & Old Cemetery', 'machilipatnam-17th-century-dutch-fort-belfry-old-cemetery', 'The Dutch Fort ruins in Machilipatnam date back to the 17th century when the port served as a key trading center for the Dutch East India Company. The site features an old armory belfry, stone obelisks, and carved gravestones bearing historic European coats of arms.', 'Historical Forts & Monuments', 'Andhra Pradesh', 'Krishna District', 'Machilipatnam', '08:00 AM', '06:00 PM', 0, '/images/aptourism/machilipatnam.jpg', 'EASY', 4.2, 340, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Challapalli Royal Heritage Palace', 'challapalli-royal-heritage-palace', 'Explore the Challapalle Fort''s Rich History Challapalle Fort, which is situated in Andhra Pradesh''s Krishna district, is evidence of the area''s rich cultural legacy and history. Yaralagadda Ankineedu Prasad, the Raja of Challapalli,constructed … Challapalli Vijayawada to Challapalle distance 65 kms', 'Historical Forts & Monuments', 'Andhra Pradesh', 'Krishna District', 'Challapalli', '09:30 AM', '05:00 PM', 0, '', 'EASY', 4.2, 2507, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Movva Sri Venugopala Swamy Temple (Kshetrayya Heritage)', 'movva-sri-venugopala-swamy-temple-kshetrayya-heritage', 'Sri Movva Venugopala Swany Temple is the place where Kshetrayya is said to have composed his famous lyrics. The Kshetrayya Kala Samithi at Movva now teaches music and dance to students.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Krishna District', 'Movva', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.6, 134, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Dattashram & Manginapudi Seafront Temple', 'dattashram-manginapudi-seafront-temple', 'Datta Rameshwaram Manginapudi, Machilipatnam, Andhra Pradesh, India To protect the area of Manginapudi (Tallapalem) near Machilipatnam, Andhra Pradesh, from severe cyclones and strong tidal waves, at the seaside temple of Lord Nagareswara, Sri Swamiji consecrated Lord Dattatreya in 1991.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Krishna District', 'Machilipatnam', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.6, 104, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Nagayalanka Coastal Mangroves & Lighthouse', 'nagayalanka-coastal-mangroves-lighthouse', 'Lighthouse Digest has I.C.R. Prasad''s account of a severe tropical cyclone that flooded the station in November 1977. Located on the east side of the mouth of the Krishna River south of the village of Nagayalanka.', 'Scenic & Cultural', 'Andhra Pradesh', 'Krishna District', 'Nagayalanka', '06:00 AM', '06:00 PM', 0, '', 'EASY', 4.5, 94, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Panakala Lakshmi Narasimha Swamy Temple (Mangalagiri)', 'sri-panakala-lakshmi-narasimha-swamy-temple-mangalagiri', 'Lakshmi Narasimha Temple is a Vaishnavite temple and one of the eight sacred places of Lord Vishnu in India. It is also known for being one of the eight mahakshetras Narasimha in India. It is situated at the foot of the Auspicious Hill in Mangalagiri which is part of the Vijayawada part of Guntur district of Andhra Pradesh, India.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Guntur District', 'Mangalagiri', '06:00 AM', '08:30 PM', 0, '', 'EASY', 4.7, 12101, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Mangalagiri GI Handloom Saree Guilds & Nizam Border Weavers', 'mangalagiri-gi-handloom-saree-guilds-nizam-border-weavers', 'Mangalagiri sarees and fabrics are produced by performing handicraft weaving in Mangalagiri, a town in Guntur district of the Indian state of Andhra Pradesh.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Guntur District', 'Mangalagiri', '09:00 AM', '08:30 PM', 0, '/images/aptourism/mangalagiri.jpg', 'EASY', 4.8, 1242, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Haailand Water Theme Park & Cultural Resort', 'haailand-water-theme-park-cultural-resort', 'Resorts Guntur - Read Reviews from Verified Guests to Get the Real Story. Special Offers for Guntur Hotels. Check Agoda''s Deals & Book Now Flexible Cancellation · 24/7 Customer Support', 'Heritage & Spiritual', 'Andhra Pradesh', 'Guntur District', 'Mangalagiri (Chinakakani)', '10:30 AM', '05:00 PM', 650, '', 'EASY', 4.2, 719, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Amaravati Buddhist Mahastupa & Archaeological Museum', 'amaravati-buddhist-mahastupa-archaeological-museum', 'Ruins of the stupa, 2012 A model of the original stupa, final phase, as reconstructed by archaeologists Amarāvati Stupa is a ruined Buddhist stūpa at the village of Amaravathi, Palnadu district, Andhra Pradesh, India, probably built in phases between the third century BCE and about 250 CE. It was enlarged and new sculptures replaced the earlier ones, beginning in about 50 CE.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Guntur District', 'Amaravati', '09:00 AM', '05:00 PM', 0, '/images/candidates/amaravati/amaravati-mahachaitya-amaravati-andhra-pradesh-1-attr-nearby.jpg', 'EASY', 4.2, 2937, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Dhyana Buddha 125-Foot Colossal Statue & Theme Park', 'dhyana-buddha-125-foot-colossal-statue-theme-park', 'The Dhyana Buddha is a statue of Gautama Buddha seated in a meditative posture located in Amaravathi, Andhra Pradesh, India. Completed in 2015, the statue is 125 ft (38 m) tall and is occupies a 4.5-acre site on the banks of the Krishna River. It is embellished with modern reproductions of sculptures from the Amaravati School of art which flourished in the region from 200 BC to 200 AD.', 'Artisans & Culture', 'Andhra Pradesh', 'Guntur District', 'Amaravati', '08:00 AM', '07:00 PM', 30, '', 'EASY', 4.3, 5669, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Amaralingeswara Swamy Temple (Amaravati Pancharama)', 'amaralingeswara-swamy-temple-amaravati-pancharama', 'The Amaralingeswara Swamy temple lies in Amararama, in Amaravati town in Andhra Pradesh. It is one of the Pancharama Kshetras, located on the southern bank of the river Krishna. The principal deity is Shiva, also called Amareswara Swamy. His consort is Bala Chamundika. The temple lies on a small hammock called Krouncha Shaila in Amaravati.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Guntur District', 'Amaravati', '05:00 AM', '08:30 PM', 0, '', 'EASY', 4.7, 7813, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Chebrolu Historic Chaturmukha Brahma Temple & Chola Shrines', 'chebrolu-historic-chaturmukha-brahma-temple-chola-shrines', 'Chebrolu Brahma Temple is believed to be 1000 years old. Temple is located in Guntur district and is the only temple for Brahma in Andhra Pradesh. One Temple for Brahma is located in Kasi and another one at Chebrolu. Temples in Chebrolu is of 2000 years old and dates to Chola, Chalukya, Pallava, and Kakatiya dynasties.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Guntur District', 'Chebrolu', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.7, 668, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Guntur Global Chilli Yard (Asia''s Largest Dry Chilli Market)', 'guntur-global-chilli-yard-asia-s-largest-dry-chilli-market', 'The Guntur Mirchi Yard is Asia''s largest trading center for dried red chillies, handling hundreds of regional varieties including Guntur Sannam and Teja for domestic supply and international spice export.', 'Scenic & Cultural', 'Andhra Pradesh', 'Guntur District', 'Guntur Urban', '08:00 AM', '03:00 PM', 0, '', 'EASY', 4.4, 429, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Pedakakani Sri Malleswara Swamy Temple', 'pedakakani-sri-malleswara-swamy-temple', 'Explore Sri Malleswara Swamy Temple in Pedakakani, Guntur. Check darshan timings, history, deity details, location map, and travel guide.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Guntur District', 'Pedakakani', '05:30 AM', '08:30 PM', 0, '/images/aptourism/pedakakani.jpg', 'EASY', 4.5, 2500, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Tenali ''Andhra Paris'' Cultural Canal Trail & Vaikuntapuram', 'tenali-andhra-paris-cultural-canal-trail-vaikuntapuram', 'Tenali is a town in Guntur district of the Indian state of Andhra Pradesh. It is a municipality, and the headquarters of Tenali mandal and Tenali revenue division. The town is renowned for art, culture, drama, and hence, it is called "Andhra Paris".', 'Scenic & Cultural', 'Andhra Pradesh', 'Guntur District', 'Tenali', '06:00 AM', '08:30 PM', 0, '', 'EASY', 4.7, 3542, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Uppalapadu Bird Sanctuary', 'uppalapadu-bird-sanctuary', 'The Uppalapadu Bird Sanctuary is located in Uppalapadu, near Guntur City, India. Painted storks, spot-billed pelicans and other birds that migrate from various countries such as Siberia and Australia use the village water tanks for nesting.', 'Nature & Wildlife', 'Andhra Pradesh', 'Guntur District', 'Pedakakani', '06:00 AM', '05:30 PM', 20, '/images/aptourism/uppalapadu_bird_sanctuary.jpg', 'EASY', 4.2, 4480, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ponnur Sri Sakshi Bhavanarayana Swamy Temple', 'ponnur-sri-sakshi-bhavanarayana-swamy-temple', 'An 11th-century Vishnu shrine in Ponnur, Guntur district, revered as "Sakshi" (witness) Bhavanarayana Swamy for a legend of divine testimony, and counted among the five sacred Pancha Bhavanarayana Kshetrams of Andhra Pradesh.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Guntur District', 'Ponnur', '06:00 AM', '08:00 PM', 0, '', 'EASY', 4.8, 176, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Suryalanka Beach & AP Tourism Coastal Resort', 'suryalanka-beach-ap-tourism-coastal-resort', 'At the heart of this transformation lies Suryalanka Beach, one of the most recognisable coastal destinations in Andhra Pradesh, located near Bapatla town overlooking the Bay of Bengal.', 'Scenic & Cultural', 'Andhra Pradesh', 'Bapatla District', 'Bapatla', '06:00 AM', '07:00 PM', 0, '/images/aptourism/suryalanka.jpg', 'EASY', 4.4, 1667, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Chirala GI Handloom Silk & Cotton Textile Cluster', 'chirala-gi-handloom-silk-cotton-textile-cluster', 'Mainly Chirala looms manufactures cotton, pure silk sarees with half fine zari, with jacquard weave and dress materials. In Chirala City, 40% population belongs to Padmasali & Devanga community. These communities are majorly depending on handloom profession. In early days, the weavers are weaving in plain & Jacquard Kuppadam sarees.', 'Artisans & Culture', 'Andhra Pradesh', 'Bapatla District', 'Chirala', '09:00 AM', '09:00 PM', 0, '', 'EASY', 4.7, 1396, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Bhattiprolu Ancient Buddhist Stupa & Script Birthplace', 'bhattiprolu-ancient-buddhist-stupa-script-birthplace', 'Bhattiprolu is one of the Holy relic sites of Andhra Pradesh Bhattiprolu is a village in Bapatla district of the Indian state of Andhra Pradesh. It is the headquarters of Bhattiprolu mandal in Repalle revenue division. The Buddhist stupa in the village is one of the centrally protected monuments of national importance.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Bapatla District', 'Bhattiprolu', '09:00 AM', '05:00 PM', 0, '', 'EASY', 4.5, 175, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Vodarevu Beach & Coastal Fishing Wharf', 'vodarevu-beach-coastal-fishing-wharf', 'Vodarevu Beach is a wide, sandy coastline near Chirala where local fisherfolk launch traditional wooden catamarans at sunrise and hold live fresh fish auctions directly on the shore.', 'Scenic & Cultural', 'Andhra Pradesh', 'Bapatla District', 'Chirala', '06:00 AM', '06:30 PM', 0, '/images/candidates/bapatla/2022033085.jpg', 'EASY', 4.2, 562, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Nizampatnam Fishing Harbour & Estuarine Lighthouse', 'nizampatnam-fishing-harbour-estuarine-lighthouse', 'The Lighthouse is about 4.5 Km away from Nizampatnam village and located in the Nizampatnam fishing harbor. Tucked away in the south of Krishna delta, Nizampatnam is an embayment adjoining the Krishna Delta and has a fishing harbour. A kerosene lamp was installed on old lighthouse tower which is maintained by the local authorities up to 2004.', 'Scenic & Cultural', 'Andhra Pradesh', 'Bapatla District', 'Nizampatnam', '05:00 AM', '06:00 PM', 0, '', 'EASY', 4.2, 25, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Vetapalem Cashew Processing & Heritage Libraries', 'vetapalem-cashew-processing-heritage-libraries', 'Vetapalem is a census town in Bapatla district of the Indian state of Andhra Pradesh. It is the mandal headquarters of Vetapalem mandal in Chirala revenue division. Vetapalem has one famous library "Saraswatha Library". Also Vetapalem is famous for its cashew processing industry.', 'Scenic & Cultural', 'Andhra Pradesh', 'Bapatla District', 'Vetapalem', '09:00 AM', '07:00 PM', 0, '', 'EASY', 4.8, 99, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Bapatla Historic Agricultural College Campus (1906)', 'bapatla-historic-agricultural-college-campus-1906', 'The Agricultural College, Bapatla was founded on 11 July 1945 by the Government of Composite Madras State India. It is the oldest of the eight Agricultural Colleges that make up Acharya N G Ranga Agricultural University, Andhra Pradesh.', 'Scenic & Cultural', 'Andhra Pradesh', 'Bapatla District', 'Bapatla', '09:30 AM', '05:00 PM', 0, '', 'EASY', 4.3, 435, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Motupalli Ancient Marco Polo Sea Port & Veerabhadra Temple', 'motupalli-ancient-marco-polo-sea-port-veerabhadra-temple', 'Motupalli has been ruled by various dynasties over the centuries, including the Imperial Cholas, the Kakatiyas, the Reddys, the Emperors of Vijayanagara and the Qutub Shahis. The village is mentioned as a bustling port in several historical texts, including the writings of Ptolemy, Pliny and Marco Polo.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Bapatla District', 'Chinaganjam', '06:00 AM', '06:00 PM', 0, '', 'EASY', 4.3, 130, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Chinaganjam Salt Pans & Coastal Wetland', 'chinaganjam-salt-pans-coastal-wetland', 'Location and boundaries Chinaganjam mandal is situated in the coastal region of Bapatla district, Andhra Pradesh, India, with its central coordinates at approximately 15°42′N 80°15′E. The terrain lies at an elevation of approximately 4 meters above sea level, characteristic of the low-lying eastern coastal plains.', 'Scenic & Cultural', 'Andhra Pradesh', 'Bapatla District', 'Chinaganjam', '08:00 AM', '06:00 PM', 0, '', 'EASY', 5, 2, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Karlapalem Rural Handloom & Fish Processing Corridor', 'karlapalem-rural-handloom-fish-processing-corridor', 'Karlapalem is a village in Bapatla district of the Indian state of Andhra Pradesh. It is the headquarters of Karlapalem mandal in Tenali revenue division.', 'Artisans & Culture', 'Andhra Pradesh', 'Bapatla District', 'Karlapalem', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.6, 24, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Nagarjunakonda Island Archaeological Museum', 'nagarjunakonda-island-archaeological-museum', 'Nagarjunakonda (ISO: Nāgārjunikoṇḍā, meaning Nagarjuna Hill) is a historical town, now an island located near Nagarjuna Sagar in Palnadu district of the Indian state of Andhra Pradesh. It is one of India''s historical Buddhist sites, and now lies almost entirely under the lake created by the Nagarjuna Sagar Dam.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Palnadu District', 'Macherla', '09:00 AM', '01:30 PM', 25, '/images/aptourism/nagarjunakonda.jpg', 'EASY', 4.3, 526, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Nagarjuna Sagar Dam & Crest Gates Viewpoints', 'nagarjuna-sagar-dam-crest-gates-viewpoints', 'Nagarjuna Sagar gates opened Nagarjuna Sagar Dam is a masonry dam across the Krishna River at Nagarjuna Sagar, which straddles the border between Nalgonda district in Telangana, and Palnadu district in Andhra Pradesh.', 'Scenic & Cultural', 'Andhra Pradesh', 'Palnadu District', 'Macherla', '08:00 AM', '06:00 PM', 0, '/images/telangana/nagarjuna_sagar.jpg', 'EASY', 4.6, 405, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ethipothala Waterfalls & Crocodile Breeding Lagoon', 'ethipothala-waterfalls-crocodile-breeding-lagoon', 'Ethipothala Waterfalls is a scenic 21-meter (70 feet) high multi-stream stepped mountain cascade plunging into an emerald lagoon formed by the confluence of Chandravanka, Nakkala, and Tummala streams near Nagarjuna Sagar in Palnadu District, Andhra Pradesh. Situated 11 km from Nagarjuna Sagar Dam, it features an active crocodile breeding center and cave temples.', 'Waterfalls & Gorges', 'Andhra Pradesh', 'Palnadu District', 'Macherla', '06:30 AM', '08:30 PM', 30, '/images/aptourism/ettipotala_waterfalls.jpg', 'EASY', 4.3, 3567, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kotappakonda Sri Trikoteswara Swamy Temple (Koti Lingala Shivalayam & 100-Foot Prabhalu)', 'kotappakonda-sri-trikoteswara-swamy-temple-koti-lingala-shivalayam-100-foot-prabhalu', 'Kotappakonda (Telugu: కొటప్పకొండ) is a sacred hill and major Hindu pilgrimage site located in Palnadu district, Andhra Pradesh, India. It lies about 62 km from Guntur city and 20 km from Narasaraopet. The hill is renowned for the ancient Sri Trikoteswara Swamy Temple, dedicated to Lord Shiva in the form of Trikoteswara (the Lord of the Three Peaks).', 'Heritage & Spiritual', 'Andhra Pradesh', 'Palnadu District', 'Narasaraopet', '06:00 AM', '08:30 PM', 0, '', 'EASY', 4.7, 14682, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Macherla Sri Chennakesava Swamy Temple', 'macherla-sri-chennakesava-swamy-temple', 'The Ethipothala Falls lies 8 km from Macherla, is a mountain stream cascading down the hills as Chandravanka and Suryavanka streams. The Suryavanka falls from a height of 21 meters into a lagoon and joins River Krishna. The Sri Lakshmi Chennakesava swami temple hosts a yearly local festival, Tirunalla.', 'Waterfalls & Gorges', 'Andhra Pradesh', 'Palnadu District', 'Macherla', '06:00 AM', '08:00 PM', 0, '', 'EASY', 4.7, 556, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Bellamkonda Hill Fort & Reddi Kings Citadel', 'bellamkonda-hill-fort-reddi-kings-citadel', 'Two major hill forts, Kondapalli, 20 km north west of Vijayawada and Kondavidu about 30 km west of Guntur stand testimony to the fort building skill of the Reddi kings. The forts of Bellamkonda, Vinukonda and Nagarjunakonda in the Palnadu region were also part of the Reddi Kingdom. The dynasty remained in power until the mid 15th century.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Palnadu District', 'Bellamkonda', '07:00 AM', '05:00 PM', 0, '', 'EASY', 4.1, 19, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Guthikonda Bilam (Uthikonda Caves & Dakshina Kashi Underground Shrine)', 'guthikonda-bilam-uthikonda-caves-dakshina-kashi-underground-shrine', 'Guttikonda Bilam, also known as Guthikonda Bilam, is a historic cave and a hill in Piduguralla Mandal, Palnadu District of Andhra Pradesh, India. Guttikonda or Guthikonda is the name of a nearby village, while "Bilam" is the Sanskrit word for "cave".', 'Heritage & Spiritual', 'Andhra Pradesh', 'Palnadu District', 'Piduguralla (Guthikonda Village)', '08:00 AM', '05:00 PM', 0, '', 'EASY', 4.5, 397, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kondaveedu Fort & Panoramic Hilltop Ghat Road', 'kondaveedu-fort-panoramic-hilltop-ghat-road', 'Kondaveedu Fort is a historically significant ancient hill fortress located in Kondaveedu, a village in the Chilakaluripet constituency of Palnadu district, Andhra Pradesh, India.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Palnadu District', 'Yadlapadu (Edlapadu)', '08:30 AM', '05:30 PM', 100, '', 'EASY', 4.3, 6214, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Durgi Stone Carving Artisan Guilds (GI Craft)', 'durgi-stone-carving-artisan-guilds-gi-craft', 'DURGI STONE CARVINGS A CULTURAL HERITAGE AND CRAFTS MANSHIP PALNADU DISTRICT, ANDHRA PRADESH HISTORY OF LIME STONE TO LIFE STONE: The exquisite stone carving from soft lime stone exhibited in Durgi village dates back to the early 15th century, distinctively characterizing the art and architecture that flourished in glorious Buddhist town at Nagarjuna Konda […]', 'Heritage & Spiritual', 'Andhra Pradesh', 'Palnadu District', 'Durgi', '08:30 AM', '06:00 PM', 0, '', 'EASY', 4.7, 244, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Karempudi Palnadu Battle Heroes Memorial (Veerula Gudi)', 'karempudi-palnadu-battle-heroes-memorial-veerula-gudi', 'Karempudi is a village in Palnadu district of the Indian state of Andhra Pradesh. It is the headquarters of Karempudi mandal in Gurazala revenue division. The village is historically significant as a ground for the Battle of Palnadu that happened in 12th century, often referred to as the "Andhra Kurukshetra".', 'Heritage & Spiritual', 'Andhra Pradesh', 'Palnadu District', 'Karempudi', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.8, 14, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Bugga Vagu Reservoir & Macherla Forest Range', 'bugga-vagu-reservoir-macherla-forest-range', 'Macherla Municipality is the civic body of the town and constituted in the year 1983. The municipality is classified as second grade and has a jurisdictional area of the municipality is present area of the corporation is 32.94 km2 (12.72 sq mi).', 'Lakes, Dams & Waterways', 'Andhra Pradesh', 'Palnadu District', 'Macherla', '08:00 AM', '05:00 PM', 0, '', 'EASY', 4.6, 14, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Vinukonda Hill Fort & Sri Raghunatha Swamy Temple', 'vinukonda-hill-fort-sri-raghunatha-swamy-temple', 'Vinukonda Fort, located in the scenic Vinukonda town of Guntur district, Andhra Pradesh, is an ancient fortress with deep historical, mythological, and architectural significance.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Palnadu District', 'Vinukonda', '06:30 AM', '06:00 PM', 0, '', 'EASY', 4.6, 37, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Cumbum Historic Lake & Asian Man-Made Dam', 'cumbum-historic-lake-asian-man-made-dam', 'Cumbum tank is the 2 nd largest man-made tank in Asia. It is the historical evidence of human interventions in the management of village water bodies for Agriculture and for drinking water through efficient construction of irrigation structures, systems and management.', 'Lakes, Dams & Waterways', 'Andhra Pradesh', 'Prakasam District', 'Cumbum', '06:00 AM', '06:30 PM', 0, '', 'EASY', 4.4, 733, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Bhairavakona 8th-Century Rock-Cut Cave Temples & Waterfall', 'bhairavakona-8th-century-rock-cut-cave-temples-waterfall', 'Bhairavakona (/ bhaɪrəvəˈkoʊnə /; BHy-ruh-vuh-kone-uh) is a holy place situated on the heart of Nallamala Hills in the Markapuram district of the Indian State of Andhra Pradesh. This place is notable for eight different forms of cave temples of Shiva dating to 7th or the 8th century CE.', 'Waterfalls & Gorges', 'Andhra Pradesh', 'Prakasam District', 'Pamur / Seetharampuram border', '07:30 AM', '06:00 PM', 20, '', 'EASY', 4.4, 4538, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Varaha Lakshmi Narasimha Swamy Temple (Singarayakonda)', 'sri-varaha-lakshmi-narasimha-swamy-temple-singarayakonda', 'Lakshmi Narasimha Swamy Temple Singarayakonda is one of the holy abodes of Lord Narasimha Swamy. It is also called by Dakshina Simhachalam. As per the Legends, This region was ruled by Demon Kharasura, who established a vast Kharati Dynasty. He was an ardent devotee of Lord Narasimha who used to visit this place daily for Lord Narasimha Darshan.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Prakasam District', 'Singarayakonda', '06:00 AM', '08:00 PM', 0, '', 'EASY', 4.7, 315, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kothapatnam Beach & Golden Coast Promenade', 'kothapatnam-beach-golden-coast-promenade', 'Kothapatnam is a small coastal village in Prakasam district of the Indian state of Andhra Pradesh. It is located in Kothapatnam mandal in Ongole revenue division.', 'Scenic & Cultural', 'Andhra Pradesh', 'Prakasam District', 'Kothapatnam', '06:00 AM', '07:00 PM', 0, '/images/aptourism/kothapatnam_beach.jpg', 'EASY', 4.3, 468, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Chimakurthy Star Galaxy Granite Belt & Craft Corridor', 'chimakurthy-star-galaxy-granite-belt-craft-corridor', 'Where Is Chimakurthy & Why It Matters Chimakurthy is a mandal located in the Prakasam district of Andhra Pradesh, part of a broader granite-rich belt that also includes the nearby Ongole region. The area''s geology has made it one of the primary sources of dark, speckled granite in India, with quarrying activity here dating back several decades.', 'Artisans & Culture', 'Andhra Pradesh', 'Prakasam District', 'Chimakurthy', '09:00 AM', '05:30 PM', 0, '', 'EASY', 4.9, 8, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ongole Cattle GI Breed Heritage Centers & Livestock Farms', 'ongole-cattle-gi-breed-heritage-centers-livestock-farms', 'Discover the rich history of Ongole — from ancient times, the famous Ongole cattle breed, to the modern city of Prakasam district, Andhra Pradesh.', 'Scenic & Cultural', 'Andhra Pradesh', 'Prakasam District', 'Santhanuthalapadu / Tangutur', '08:00 AM', '05:00 PM', 0, '', 'EASY', 4.1, 12, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Tripurantakam Sri Tripurantakeswara Temple (Eastern Gateway to Srisailam)', 'tripurantakam-sri-tripurantakeswara-temple-eastern-gateway-to-srisailam', 'Location Tripurantakam is located on the national highway from Guntur to Srisailam. Sri Bala Tripura Sundari Ammavari temple is located at a distance of 2 km from Tripurantakam village. Sri Tripurantakeswara Swamy is on the top of a hill. Goddess Sri Bala Tripura Sundari is located down the hill, in the midst of a tank.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Prakasam District', 'Yerragondapalem / Tripurantakam', '06:00 AM', '08:00 PM', 0, '', 'EASY', 4.7, 747, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kanigiri Hill Fort & Prehistoric Dolmens', 'kanigiri-hill-fort-prehistoric-dolmens', 'Durgam Fort, also known as Kanigiri Fort, is a historic hilltop fortress in Prakasam district, Andhra Pradesh, built during the Vijayanagara Empire and later ruled by several dynasties, including the Reddis and the Gajapatis.', 'Historical Forts & Monuments', 'Andhra Pradesh', 'Prakasam District', 'Kanigiri', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.3, 208, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ramayapatnam Sea Port & Historic Coastal Beach', 'ramayapatnam-sea-port-historic-coastal-beach', 'Ramayapatnam is a small village in Ulavapadu mandal of Prakasam district of Andhra Pradesh, India on the bank of the Bay of Bengal. It is located 4.5 km (2.8 mi) East of Tettu on NH-16.', 'Scenic & Cultural', 'Andhra Pradesh', 'Prakasam District', 'Ulavapadu', '06:00 AM', '06:30 PM', 0, '/images/aptourism/ramayapatnam.jpg', 'EASY', 4.3, 285, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Markapur Slate Manufacturing & Sri Chennakesava Temple', 'markapur-slate-manufacturing-sri-chennakesava-temple', 'Markapuram is a town and the headquarters of Markapuram district of the Indian state of Andhra Pradesh. It is a municipality and is the headquarters of Markapuram Municipality in Markapuram revenue division. Markapuram is notable for the Chennakesava Swamy Temple (2nd largest gopuram in Telugu States with 135 feet height), built by King Sri Krishnadevaraya.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Prakasam District', 'Markapur', '06:00 AM', '08:30 PM', 0, '', 'EASY', 4.6, 886, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Pakala Coastal Estuary & Waterfowl Wetland', 'pakala-coastal-estuary-waterfowl-wetland', 'The shoreline of Pakala Beach on the Bay of Bengal. Pakala is a coastal village in Prakasam district of the Indian state of Andhra Pradesh. It is located in Singarayakonda mandal.', 'Scenic & Cultural', 'Andhra Pradesh', 'Prakasam District', 'Singarayakonda border', '06:00 AM', '06:00 PM', 0, '', 'EASY', 4.3, 2109, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ulavapadu Saltwater Cashew & Famous Mango Groves', 'ulavapadu-saltwater-cashew-famous-mango-groves', 'Ulavapadu is a village in Ulavapadu mandal in Prakasam district of the Indian state of Andhra Pradesh. It is famous for variety of mangoes such as Banginapalli, Rasalu and also famous for a variety of Sapotas.', 'Scenic & Cultural', 'Andhra Pradesh', 'Prakasam District', 'Ulavapadu', '08:00 AM', '07:00 PM', 0, '', 'EASY', 4.8, 91, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Mypadu Beach & Casuarina Coastline', 'mypadu-beach-casuarina-coastline', 'Mypadu Beach, situated along the eastern coast of the Bay of Bengal, is located about 25 km (16 miles) from SPSR Nellore district in Andhra Pradesh. Managed by the Andhra Pradesh Tourism Development Corporation (APTDC), the beach serves as a vital hub for local fishermen while offering tourists a chance to enjoy boat cruises.', 'Scenic & Cultural', 'Andhra Pradesh', 'Sri Potti Sriramulu Nellore District', 'Indukurpet', '06:00 AM', '06:30 PM', 0, '/images/aptourism/mypadu_beach.jpg', 'EASY', 4.3, 1408, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Venkatagiri GI-Tagged Zari Handloom Saree Hub & Raja Palace', 'venkatagiri-gi-tagged-zari-handloom-saree-hub-raja-palace', 'Venkatagiri Handlooms — Authentic GI Certified Handwoven Sarees from Andhra Pradesh. Pure silk, cotton, ikat, and zari sarees.', 'Historical Forts & Monuments', 'Andhra Pradesh', 'Sri Potti Sriramulu Nellore District', 'Venkatagiri', '09:30 AM', '06:30 PM', 0, '', 'EASY', 5, 160, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Jonnawada Sri Mallikarjuna Kamakshi Temple', 'jonnawada-sri-mallikarjuna-kamakshi-temple', 'Sri Mallikarjuna Swamy Kamakshi Tayee Temple was built in the year 1150 A.D. and is located on the banks of Penna river. Once Kasyapa Prajapathi wanted to perform Yagna and started searching for the place in the southern part of India. meanwhile he reached Rajathagiri, which is located north to Penna river and decided to perform Yagna there.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Sri Potti Sriramulu Nellore District', 'Buchireddypalem', '05:30 AM', '09:00 PM', 0, '/images/candidates/spsnellore/2018081713.jpg', 'EASY', 4.7, 2323, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Udayagiri Hill Fort & 365 Historic Defense Bastions', 'udayagiri-hill-fort-365-historic-defense-bastions', 'The Udayagiri fort was constructed by Langula Gajapati, the chieftan to Gajapatis of Orissa, around 14th century. Later, it came under the rule of Krishnadevaraya of Vijayanagara.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Sri Potti Sriramulu Nellore District', 'Udayagiri', '07:00 AM', '05:00 PM', 0, '/images/aptourism/udayagiri.jpg', 'EASY', 4.3, 200, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Talpagiri Sri Ranganatha Swamy Temple', 'talpagiri-sri-ranganatha-swamy-temple', 'The Sri Ranganthaswami Temple in Nellore, Andhra Pradesh, India is a Hindu temple dedicated to Lord Ranganatha a resting form of Lord Vishnu. This temple, also called Talpagiri Ranganathaswami temple or Ranganayakulu is one of the oldest temples in Nellore.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Sri Potti Sriramulu Nellore District', 'Nellore Urban', '06:00 AM', '08:30 PM', 0, '/images/candidates/spsnellore/2018081751.jpg', 'EASY', 4.7, 2936, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Penchalakona Sri Penusila Lakshmi Narasimha Swamy Temple', 'penchalakona-sri-penusila-lakshmi-narasimha-swamy-temple', 'Nellore is best convinent to reach here. History of the Temple: Penchalakona temple is one of the Nava Narasimha temples which all are located with in Andhra and Telangana states. List is as follows, Lord Narasimha even after killing Hiranya Kasyapa, he could not control his anger and he came to the forest.', 'Waterfalls & Gorges', 'Andhra Pradesh', 'Sri Potti Sriramulu Nellore District', 'Rapur', '06:00 AM', '07:30 PM', 0, '/images/aptourism/penchalakona.jpg', 'EASY', 4.7, 2390, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Nellore Malagunta Chepala Pulusu Culinary Trail', 'nellore-malagunta-chepala-pulusu-culinary-trail', 'Land Acquisition- Prakasam District-Gudluru Mandal -Chevuru Village-For the purpose of the Establishment of Industrial Hub-Publication of Priliminary notification Gazette.', 'Scenic & Cultural', 'Andhra Pradesh', 'Sri Potti Sriramulu Nellore District', 'Nellore Urban', '11:30 AM', '10:30 PM', 400, '/images/candidates/nellore/nellore.jpg', 'EASY', 2.7, 373, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kandaleru Dam & Sri City Reservoir', 'kandaleru-dam-sri-city-reservoir', 'The Kandaleru Dam is an important irrigation project located on the Kandaleru River in Rapur Mandal, Nellore district, Andhra Pradesh. This project is a key component of the Telugu Ganga project, which facilitates the supply of drinking water to Chennai city from the Srisailam Reservoir on the Krishna River.', 'Lakes, Dams & Waterways', 'Andhra Pradesh', 'Sri Potti Sriramulu Nellore District', 'Rapur', '08:30 AM', '05:30 PM', 0, '', 'EASY', 4.4, 249, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Somasila Dam & Reservoir Eco-Park', 'somasila-dam-reservoir-eco-park', 'The Somasila Dam is a significant structure built across the Penna River, located near Somasila in Nellore district, Andhra Pradesh, India. The reservoir created by the dam spans a surface area of 212.28 km² (52,456 acres) and has a live storage capacity of 1.994 km³ (1,616,562 acre⋅ft), or 75 tmcft. The Somasila Reservoir receives water […]', 'Lakes, Dams & Waterways', 'Andhra Pradesh', 'Sri Potti Sriramulu Nellore District', 'Atmakur / Somasila', '08:00 AM', '06:00 PM', 20, '', 'EASY', 4.6, 80, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Bara Shaheed Dargah & Rotiya Utsavam (Nellore)', 'bara-shaheed-dargah-rotiya-utsavam-nellore', 'The Sandal celebrations at Bara Shaheed Dargah are called Rottela Panduga, also known as Rotiyon Ki Eid meaning Festival of Breads in Islamic terms. Many people having immense faith that wishes made during this festival at the dargah are fulfilled to their satisfaction.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Sri Potti Sriramulu Nellore District', 'Nellore Urban', '06:00 AM', '09:00 PM', 0, '', 'EASY', 4.6, 964, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Krishnapatnam Deep Sea Port & Coastal Waterfront', 'krishnapatnam-deep-sea-port-coastal-waterfront', 'Krishnapatnam Port popularly known as KPCL is a privately built and owned all weather, deep water port on the east coast of India, located in the Nellore District of Andhra Pradesh.', 'Scenic & Cultural', 'Andhra Pradesh', 'Sri Potti Sriramulu Nellore District', 'Muthukur', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.2, 116, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Nellore Maladevi Tank & Birdwatching Wetland', 'nellore-maladevi-tank-birdwatching-wetland', 'Nellore district formed part of the composite Madras State till 1st October, 1953. On 1st November 1956 when the states were reorganized on a linguistic basis, this district came under the Andhra Pradesh State. The name of Nellore district has been changed as Sri Potti Sriramulu Nellore District on 4th June, 2008.', 'Scenic & Cultural', 'Andhra Pradesh', 'Sri Potti Sriramulu Nellore District', 'Nellore Urban', '06:00 AM', '06:00 PM', 0, '', 'EASY', 4.5, 337, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Tirumala Sri Venkateswara Swamy Temple & Seshachalam Hills', 'tirumala-sri-venkateswara-swamy-temple-seshachalam-hills', 'of Tirumala Venkateswara Temple Venkateswara Temple is an important Vaishnavite temple situated in the hill town of Tirumala in Tirupati district of Andhra Pradesh, built by a Tamil king Tondaiman and later expanded and renovated under the Chola and Vijayanagara Empire.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Tirupati District', 'Tirumala', '03:00 AM', '11:30 PM', 0, '', 'EASY', 4.8, 155803, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Kalahasteeswara Swamy Temple (Vayu Lingam Kshetram)', 'sri-kalahasteeswara-swamy-temple-vayu-lingam-kshetram', 'The Srikalahasti Temple is located in the town of Srikalahasti in Tirupati district in the state of Andhra Pradesh, India. Siva in his aspect as Vayu is worshipped as Kalahasteeswara.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Tirupati District', 'Srikalahasti', '06:00 AM', '09:00 PM', 0, '', 'EASY', 4.7, 118258, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Chandragiri Fort & Raja-Rani Archaeological Palaces', 'chandragiri-fort-raja-rani-archaeological-palaces', 'Chandragiri Fort is a historical fort located in Tirupati in Andhra Pradesh, India. The fort, with its rectangular bastions and steep moat, was built around 1000AD during the reign of Immadi Narasimha Yadavaraya, who ruled from Narayanavanam.', 'Historical Forts & Monuments', 'Andhra Pradesh', 'Tirupati District', 'Chandragiri', '09:00 AM', '08:00 PM', 25, '/images/aptourism/chandragiri_fort.jpg', 'EASY', 4.2, 9855, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Padmavathi Ammavari Temple (Tiruchanur)', 'sri-padmavathi-ammavari-temple-tiruchanur', 'Padmavati Temple is a Hindu temple dedicated to the deity Padmavati (Alamelu Mangamma or Alarmel Mangai), the consort of Venkanna. The temple is situated in Tiruchanur (also known as Alamelu Mangapuram or Alarmel Mangaipuram area) of Tirupati city in Tirupati district of Andhra Pradesh, India.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Tirupati District', 'Tirupati Rural', '06:00 AM', '09:00 PM', 0, '', 'EASY', 4.7, 31737, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Govindaraja Swamy Temple & 7-Tier Gopuram', 'sri-govindaraja-swamy-temple-7-tier-gopuram', 'Sri Govindarajaswamy Temple is an ancient Hindu Vaishnavite temple situated in the heart of Tirupati city in Tirupati district of Andhra Pradesh in India.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Tirupati District', 'Tirupati Urban', '05:00 AM', '09:00 PM', 0, '', 'EASY', 4.7, 8754, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kapila Theertham Mountain Waterfall & Shiva Shrine', 'kapila-theertham-mountain-waterfall-shiva-shrine', 'Kapila Theertham is a small Shaivite temple and theertham, located at Tirupati in Andhra Pradesh, India. The idol of Shiva is believed to have been installed by Sage Kapila, so god Shiva here is referred to as Kapileswara.', 'Waterfalls & Gorges', 'Andhra Pradesh', 'Tirupati District', 'Tirupati Urban', '05:30 AM', '06:00 PM', 0, '', 'EASY', 4.7, 7280, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Silathoranam Rare Natural Geological Rock Arch', 'silathoranam-rare-natural-geological-rock-arch', 'The natural arch is located in Tirumala atop the Venkatadri hill in the Sapthagiri range in the Seshachalam Hills of the Eastern Ghats. Located about 860 m (2,820 ft) above sea level in the Tirupati district of Andhra Pradesh, it is near Chakra Theertham, about 1 km (0.62 mi) from the Venkateswara Temple in Tirumala.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Tirupati District', 'Tirumala', '06:00 AM', '06:30 PM', 0, '', 'EASY', 4.7, 1755, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Srikalahasti Hand-Painted Kalamkari GI Artisan Guilds', 'srikalahasti-hand-painted-kalamkari-gi-artisan-guilds', 'Srikalahasti Kalamkari is a style of Kalamkari work which involves dyed hand-painting of a fabric. It is produced in Srikalahasti of Tirupati district in the Indian state of Andhra Pradesh.', 'Artisans & Culture', 'Andhra Pradesh', 'Tirupati District', 'Srikalahasti', '09:00 AM', '06:30 PM', 0, '/images/aptourism/srikalahasti.jpg', 'EASY', 4.5, 172, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Satish Dhawan Space Centre (SDSC SHAR) Launch Viewpoints', 'satish-dhawan-space-centre-sdsc-shar-launch-viewpoints', 'Satish Dhawan Space Centre (SDSC-SHAR) is located in Sriharikota, a spindle-shaped barrier island, in Tirupati district, on the east coast of Andhra Pradesh. Features like a good launch azimuth corridor for various missions, nearness to the equator (benefiting eastward launches), and large uninhabited area for a safety zone make it an ideal spaceport.', 'Scenic & Cultural', 'Andhra Pradesh', 'Tirupati District', 'Sullurpeta', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.7, 3192, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Pulicat Bird Sanctuary & Flamingo Salt Lagoon', 'pulicat-bird-sanctuary-flamingo-salt-lagoon', 'Pulicat Lake Bird Sanctuary is a sanctuary for birds, 759 km2 (293 sq mi) in area, located in the Tirupati district of Andhra Pradesh and a protected area of the Thiruvallur District of Tamil Nadu, India.', 'Nature & Wildlife', 'Andhra Pradesh', 'Tirupati District', 'Sullurpeta / Tada', '06:00 AM', '05:30 PM', 0, '', 'EASY', 4.2, 1668, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Tada Falls (Ubbalamadugu Waterfalls Forest Trek)', 'tada-falls-ubbalamadugu-waterfalls-forest-trek', 'Cascade section of Tada Waterfalls — in the Eastern Ghats, southeast India. Ubbalamudugu Falls (also called Tada Falls) is a waterfall located near Oneness Temple and Sricity in the Tirupati district of India.', 'Waterfalls & Gorges', 'Andhra Pradesh', 'Tirupati District', 'Tada', '08:00 AM', '03:00 PM', 50, '', 'EASY', 4.4, 2544, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Venkateswara Zoological Park & Biodiversity Reserve', 'sri-venkateswara-zoological-park-biodiversity-reserve', 'The zoo had an exceptionally heavy leopard called ''Balaji'', which weighed 139-143 kg (306-315 lb) against the normal weight of 70 kg (150 lb) of its class. Balaji was captured at the age of 12 in 1996, when he alleggedley weighed 108-113 kg (238-249 lb). The leopard ate 4 kg (8.', 'Nature & Wildlife', 'Andhra Pradesh', 'Tirupati District', 'Tirupati Rural', '09:00 AM', '05:00 PM', 60, '', 'EASY', 4.2, 16723, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kailasakona Perennial Waterfalls & Cave Temple', 'kailasakona-perennial-waterfalls-cave-temple', 'Kaulesha Kona or Kailasa kona is a waterfall in Narayanavanam mandal, Tirupati district, Andhra Pradesh in India. A temple of Lord Shiva and Parvathi is located nearby. The waterfall has a height of around 40 feet.', 'Waterfalls & Gorges', 'Andhra Pradesh', 'Tirupati District', 'Narayanavanam', '06:00 AM', '06:00 PM', 20, '', 'EASY', 4.1, 7064, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Talakona Waterfalls (Highest Waterfall in Andhra Pradesh)', 'talakona-waterfalls-highest-waterfall-in-andhra-pradesh', 'Talakona is situated in Tirupati district of Andhra Pradesh, India. It is a resort with waterfalls, dense forests and wildlife. Talakona waterfall is in Sri Venkateswara National Park, Tirupati district of Andhra Pradesh. With a 270 feet (82 m) -fall, Talakona is the highest waterfall in Andhra Pradesh state.', 'Waterfalls & Gorges', 'Andhra Pradesh', 'Tirupati District', 'Yerravaripalem', '07:00 AM', '05:00 PM', 50, '', 'EASY', 4.5, 13018, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Varasiddhi Vinayaka Swamy Temple (Kanipakam)', 'sri-varasiddhi-vinayaka-swamy-temple-kanipakam', 'Sri Varasidhi Vinayaka Swamy Temple is a Hindu temple of Ganesha. It is located at Kanipakam in Chittoor district of Andhra Pradesh, India. The temple is about 11 km from Chittoor and 68 km from Tirupati.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Chittoor District', 'Irala', '05:00 AM', '09:30 PM', 0, '', 'EASY', 4.7, 44431, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Horsley Hills (Yenugu Mallamma Konda, 1,290m)', 'horsley-hills-yenugu-mallamma-konda-1-290m', 'Horsley Hills or Horsleykonda or Yenugulla Mallamma Konda is a series of hills in Andhra Pradesh in Madanapalle Taluka of Annamayya district and is about 9 miles from Madanapalle town. The local name of the hill was Yenugu Mallama Konda after a legend of a saintly old woman named Mallamma who lived at the top of the hill and was fed by elephants (yenugulu). W.D.', 'Nature & Wildlife', 'Andhra Pradesh', 'Chittoor District', 'B.Kothakota border / Madanapalle access', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.4, 786, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kaigal Waterfalls (Dumukurallu Cascades)', 'kaigal-waterfalls-dumukurallu-cascades', 'Kaigal Water Falls is a waterfall situated in the Chittoor district of Andhra Pradesh, India. The falls are surrounded by the Koundinya Wildlife Sanctuary. The falls are 40 feet tall. The falls are formed by the Kaigal stream, one of the two streams flowing through the Koundinya Wildlife Sanctuary, the other being Koudinya stream.', 'Waterfalls & Gorges', 'Andhra Pradesh', 'Chittoor District', 'Baireddipalle', '08:30 AM', '05:00 PM', 20, '', 'EASY', 4.1, 1365, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kaundinya Wildlife Sanctuary & Elephant Reserve', 'kaundinya-wildlife-sanctuary-elephant-reserve', 'Kaundinya Wildlife Sanctuary is a wildlife sanctuary and an elephant reserve situated in Andhra Pradesh, India. It is the only sanctuary in Andhra Pradesh with a population of Asian elephants, which migrated after 200 years from neighbouring regions.', 'Waterfalls & Gorges', 'Andhra Pradesh', 'Chittoor District', 'Palamaner', '07:00 AM', '05:00 PM', 50, '', 'EASY', 4.2, 587, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Mogileswara Swamy Temple (Mogili, Dakshina Kailasam)', 'sri-mogileswara-swamy-temple-mogili-dakshina-kailasam', 'This temple is popularly known as Dakshina Kailasam and has sculpture work. The presiding deity in this temple is of Lord Shiva that was founded by Mogilliappa and placed under Mogili tree.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Chittoor District', 'Bangarupalem', '06:00 AM', '08:00 PM', 0, '', 'EASY', 4.7, 136, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ardhagiri Sri Veeranjaneya Swamy Hill Temple', 'ardhagiri-sri-veeranjaneya-swamy-hill-temple', 'Veeranjaneya Temple is a temple on the hill of Ardhagiri, dedicated to Lord Hanuman. It is situated in Aragonda of Chittoor district in the Indian state of Andhra Pradesh.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Chittoor District', 'Aragonda', '06:00 AM', '08:00 PM', 0, '', 'EASY', 4.7, 4147, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Lakshmi Narayana Swamy Temple (Vepanjeri)', 'sri-lakshmi-narayana-swamy-temple-vepanjeri', 'Sri Lakshmi Narayana Swamy Temple Vepanjeri History. Temple Timings, Opening and Closing Hours, Darshan tickets, Dress Code, Contact number.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Chittoor District', 'Gangadhara Nellore', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.5, 69, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Gurramkonda 500-Foot Rock Hill Fort', 'gurramkonda-500-foot-rock-hill-fort', 'Gurramkonda fort is a hill fort in Annamayya district of the Indian state of Andhra Pradesh. It is located in the village Gurramkonda, the mandal headquarters. It is considered one of the oldest forts in the district. According to sources this fort was built during Vijayanagara Empire and later it came in control of Abdul Khan, the Nawab of Kadapa, in the year 1714 CE.', 'Historical Forts & Monuments', 'Andhra Pradesh', 'Chittoor District', 'Gurramkonda', '09:00 AM', '05:00 PM', 0, '', 'EASY', 4.3, 1881, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kalavagunta 9th-Century Chola Temples', 'kalavagunta-9th-century-chola-temples', 'Sri Mukkanteeswara Temple Kalavagunta History Kalavagunta Village is situated in the North-East direction to Chittoor at a distance of 8 km. Kalavagunta is a small village, located at the merging points of the rivers Aragonda and Ponnai. The Temples in this village were constructed by the rulers of Chola dynasty in 9th Century A.D.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Chittoor District', 'Penumuru', '06:30 AM', '07:00 PM', 0, '', 'EASY', 4.8, 61, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Nagari Hills & The Iconic Nagari Nose Cliff', 'nagari-hills-the-iconic-nagari-nose-cliff', 'Nagari Hills is a prominent granite hill range in Chittoor district, famous for the Nagari Nose vertical cliff used for centuries as a navigation landmark by sailors on the Bay of Bengal.', 'Waterfalls & Gorges', 'Andhra Pradesh', 'Chittoor District', 'Nagari', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.4, 8, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Palamaner Cashew & Jaggery Market', 'palamaner-cashew-jaggery-market', 'பலமனேர் பலமனேர் (Palamaner) இந்தியாவின் ஆந்திரப் பிரதேச மாநிலத்தின் சித்தூர் மாவட்டத்தில் இடம் பெற்றுள்ள ஒரு நகரமாகும்.', 'Scenic & Cultural', 'Andhra Pradesh', 'Chittoor District', 'Palamaner', '08:00 AM', '08:00 PM', 0, '', 'EASY', 4, 528, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kuppam Granite Corridor & South Rail Frontier', 'kuppam-granite-corridor-south-rail-frontier', 'The Area Kuppam (682.350 m MSL) region forms the south-western corner of Chittoor district and lies at the tri-junction of Tamil Nadu, Karnataka and Andhra Pradesh.', 'Scenic & Cultural', 'Andhra Pradesh', 'Chittoor District', 'Kuppam', '08:30 AM', '06:00 PM', 0, '', 'EASY', 5, 4, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Tallapaka Annamacharya Janmasthalam & 108-Foot Statue', 'tallapaka-annamacharya-janmasthalam-108-foot-statue', 'Annamacharya was born in Tallapaka village, near present-day Rajampet in Kadapa district, Andhra Pradesh, and his birth anniversary continues to be commemorated annually through devotional and cultural events..In the year Sarwadhari (22 May 1408) in Tallapaka, Near Rajampet Mandalam, a village in present-day Annamayya district of Andhra Pradesh, India.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Annamayya District', 'Rajampet', '06:00 AM', '08:30 PM', 0, '', 'EASY', 4.5, 742, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Nandalur Sri Soumyanatha Swamy Ancient Chola Temple', 'nandalur-sri-soumyanatha-swamy-ancient-chola-temple', 'The Sri Soumyanatha Swamy Temple has a history that is intertwined with local legends and the spiritual traditions of the region. The temple is believed to have been constructed during the reign of the Chola dynasty, known for its patronage of temple architecture.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Annamayya District', 'Nandalur', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.8, 3554, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Madanapalle Rabindranath Tagore ''Jana Gana Mana'' Hall', 'madanapalle-rabindranath-tagore-jana-gana-mana-hall', 'It is common knowledge that Rabindranath Tagore authored the national anthem ''Jana Gana Mana'' in 1911.', 'Historical Forts & Monuments', 'Andhra Pradesh', 'Annamayya District', 'Madanapalle', '09:30 AM', '05:00 PM', 0, '', 'EASY', 4.8, 103, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Rayachoti Sri Veerabhadra Swamy Temple', 'rayachoti-sri-veerabhadra-swamy-temple', 'This complete guide covers everything you need to plan your visit: the full history of Rayachoti Veerabhadra Swamy, temple timings, seva and archana details, accommodation options near the Rayachoti Veerabhadreshwara Devasthana, travel routes, and answers to the most commonly asked questions.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Annamayya District', 'Rayachoti', '05:30 AM', '08:30 PM', 0, '', 'EASY', 4.7, 2122, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Attirala Sri Parasurama Temple & Cheyyeru Sangamam', 'attirala-sri-parasurama-temple-cheyyeru-sangamam', 'The presence of Gadhadara and holy river Cheyyeru, Attirala is considered as sacred as Gaya Kshetram. Parasurama Kshetra, is worth seeing for its sculptural beauty and grand appearance. There is a Jyothistambha, higher up the temple of Thretheswara, on the top of a hill. Jyothi, lighted on festivals, is visible to distance of 30 Kms around.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Annamayya District', 'Rajampet', '06:00 AM', '07:00 PM', 0, '', 'EASY', 4.7, 49, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Punganur Dwarf Cattle Heritage Gaushala', 'punganur-dwarf-cattle-heritage-gaushala', 'The Punganur is an Indian breed of small zebuine cattle. It is found in the hilly area of Chitoor District, in Andhra Pradesh in southern India, and is among the smallest of all zebu breeds.: 275', 'Scenic & Cultural', 'Andhra Pradesh', 'Annamayya District', 'Punganur', '08:00 AM', '05:00 PM', 0, '', 'EASY', 5, 10, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Vempalli Papaghni River Gorge & Sand Formations', 'vempalli-papaghni-river-gorge-sand-formations', 'The Vempalli Gorge is a scenic natural canyon carved by the Papaghni River through ancient red quartzite and sandstone hills in Annamayya district, popular for scenic hiking trails and wide sandy riverbanks.', 'Waterfalls & Gorges', 'Andhra Pradesh', 'Annamayya District', 'Galiveedu border', '08:00 AM', '06:00 PM', 0, '', 'EASY', 3.9, 13, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kalikiri Defense Heritage Corridor', 'kalikiri-defense-heritage-corridor', 'Kalikiri is a village in Annamayya district of Andhra Pradesh state in India. It is the Mandal headquarters of Kalikiri Area.', 'Scenic & Cultural', 'Andhra Pradesh', 'Annamayya District', 'Kalikiri', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.5, 2500, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Somala Forest Range & Cascade Streams', 'somala-forest-range-cascade-streams', 'Somala is a village in Annamayya district of the Indian state of Andhra Pradesh. It is the mandal headquarters of Somala mandal.', 'Waterfalls & Gorges', 'Andhra Pradesh', 'Annamayya District', 'Somala', '07:30 AM', '05:00 PM', 0, '', 'EASY', 4.5, 24267, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Tamballapalle Granite Fort & Prehistoric Caves', 'tamballapalle-granite-fort-prehistoric-caves', 'Thamballapalle is a village and Mandal headquarters in Annamayya district of the Indian state of Andhra Pradesh. Horsey Hills is a famous hill station which is located in this mandal.', 'Historical Forts & Monuments', 'Andhra Pradesh', 'Annamayya District', 'Tamballapalle', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.4, 13592, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Gandikota Grand Canyon of India & Historic Fort', 'gandikota-grand-canyon-of-india-historic-fort', 'Gandikota is a village and historical fort on the right bank of the Penna river, 15 km from Jammalamadugu in Kadapa district, Andhra Pradesh, India. The fort was the centre of power for various dynasties, such as the Kalyani Chalukyas, Pemmasani Nayakas, and the Golconda Sultanate. Initially, a sand fort was constructed by Kaka Raja, a vassal of the Kalyani Chalukya rulers.', 'Waterfalls & Gorges', 'Andhra Pradesh', 'YSR Kadapa District', 'Jammalamadugu', '06:00 AM', '06:30 PM', 0, '/images/aptourism/gandikota.jpg', 'EASY', 4.6, 2925, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Vontimitta Sri Kodandarama Swamy Temple', 'vontimitta-sri-kodandarama-swamy-temple', 'The '' Kodandarama Temple'' at Vontimitta is one of the most prominent Sri Rama temples in Andhra Pradesh and serves as the official venue for the State-sponsored Sri Sita Rama Kalyanam celebrations during Sri Rama Navami.', 'Heritage & Spiritual', 'Andhra Pradesh', 'YSR Kadapa District', 'Vontimitta', '06:00 AM', '08:30 PM', 0, '', 'EASY', 4.8, 12285, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sidhout (Siddhavatam) Fort & Rameswaram Temple', 'sidhout-siddhavatam-fort-rameswaram-temple', 'Siddhavatam is a village in Kadapa district of the Indian state of Andhra Pradesh. It is located in Siddavatam mandal of Kadapa revenue division. This village was initially under the rule of Matli Kings. As the Muslim rulers ruled the South India, it was then brought under the control of the Nawab of Cuddapah. With the advent of British, it was ceded to them by the Nawab.', 'Heritage & Spiritual', 'Andhra Pradesh', 'YSR Kadapa District', 'Sidhout', '08:30 AM', '05:30 PM', 0, '', 'EASY', 4.3, 1157, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ameen Peer Dargah (Pedda Dargah)', 'ameen-peer-dargah-pedda-dargah', 'The document describes the Ameen Peer Dargah complex in Kadapa City, India. It details the history and origins of the shrine, founded in the 16th century by Khwaja Peerullah Hussaini. Today the shrine sees many pilgrims seeking blessings, with followers believing their wishes are fulfilled there.', 'Heritage & Spiritual', 'Andhra Pradesh', 'YSR Kadapa District', 'Kadapa Urban', '05:00 AM', '10:00 PM', 0, '', 'EASY', 4.6, 3755, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Devuni Kadapa Sri Lakshmi Venkateswara Swamy Temple', 'devuni-kadapa-sri-lakshmi-venkateswara-swamy-temple', 'Sri Lakshmi Venkateshwara Swamy Devasthanam temple sits in Devuni Kadapa, in the Indian state of Andhra Pradesh. The temple is dedicated to Lord Venkateswara and serves as a prelude for pilgrims en route to Tirumala Venkateswara Temple.', 'Heritage & Spiritual', 'Andhra Pradesh', 'YSR Kadapa District', 'Kadapa Urban', '06:00 AM', '08:30 PM', 0, '', 'EASY', 4.8, 889, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kadapa Famous Karam Dosa & Ragi Mudda Street Trail', 'kadapa-famous-karam-dosa-ragi-mudda-street-trail', 'The District is also considered to be one of the District endowed with rich History, Minerals Flora & Fauna. Sri Krishna Devaraya of Vijayanagara Empire, Pratap Rudra of Kakatiya dynastry, Sivaji of Maharashtra Emperor, Tipu Sultan and Haider Ali are some of the names associated with the history of this tract.', 'Scenic & Cultural', 'Andhra Pradesh', 'YSR Kadapa District', 'Kadapa Urban', '06:30 AM', '11:00 PM', 40, '', 'EASY', 4.8, 20, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Pushpagiri Sacred Temples & Penna River Confluence', 'pushpagiri-sacred-temples-penna-river-confluence', 'Pushpagiri Temple Complex is a temple complex located in Kadapa district in Andhra Pradesh, India. Founded around 7th Century CE, it houses some of the oldest temple congregations in the region.', 'Heritage & Spiritual', 'Andhra Pradesh', 'YSR Kadapa District', 'Vallur', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.7, 564, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Potuluri Veerabrahmendra Swamy Matham', 'sri-potuluri-veerabrahmendra-swamy-matham', 'Brahmamgari matam in Kadapa district is a pilgrimage center in Andhra Pradesh. Editor T Ganapati Sastri of the book BrahmaTatwa Prakasika of Sadasivendra Saraswati (Trivandrum Sanskrit Series No VII), published in 1909, makes passing mention of a Tamil work called Acharya-Darpana that supposedly details his deeds. Srimadvirat Veerabrahmendra Swami Charitra is a 1984 film his life.', 'Heritage & Spiritual', 'Andhra Pradesh', 'YSR Kadapa District', 'Brahmamgari Matham (Kandimallayapalle)', '06:00 AM', '08:30 PM', 0, '', 'EASY', 4.5, 972, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Gandi Sri Anjaneya Swamy Temple', 'gandi-sri-anjaneya-swamy-temple', 'Gandi Kshetram Sri Veeranjaneya Temple or Gandi Kshetram is a Hindu temple situated at Gandi, a village in Kadapa District of Andhra Pradesh in India. The temple is dedicated to the god Anjaneya (Hanuman) who is referred to as Veeranjaneya in this temple.', 'Waterfalls & Gorges', 'Andhra Pradesh', 'YSR Kadapa District', 'Chakrayapet', '06:00 AM', '08:00 PM', 0, '', 'EASY', 4.6, 6758, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Yerraguntla Limestone & Industrial Valley', 'yerraguntla-limestone-industrial-valley', 'The Limestone Belt of Kadapa The limestone belt stretches across parts of Kamalapuram, Jammalamadugu, and Yerraguntla. These areas are dotted with active mines and cement factories, where the limestone extracted is processed for multiple uses.', 'Scenic & Cultural', 'Andhra Pradesh', 'YSR Kadapa District', 'Yerraguntla', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.5, 2500, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Palakonda Forest Ghats & Red Sanders Sanctuary', 'palakonda-forest-ghats-red-sanders-sanctuary', 'The District is also considered to be one of the District endowed with rich History, Minerals Flora & Fauna. Sri Krishna Devaraya of Vijayanagara Empire, Pratap Rudra of Kakatiya dynastry, Sivaji of Maharashtra Emperor, Tipu Sultan and Haider Ali are some of the names associated with the history of this tract.', 'Nature & Wildlife', 'Andhra Pradesh', 'YSR Kadapa District', 'Kadapa Rural', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.3, 780, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Mylavaram Dam & Reservoir Eco-Park', 'mylavaram-dam-reservoir-eco-park', 'Mylavaram Dam Coordinates: 14°50′58″N 78°20′24″E Long view of Mylavaram reservoir Mylavaram Dam is a medium irrigation project in Andhra Pradesh, India. This barrage is situated over the Penna river in Kadapa district near Mylavaram.', 'Lakes, Dams & Waterways', 'Andhra Pradesh', 'YSR Kadapa District', 'Jammalamadugu', '08:30 AM', '06:00 PM', 20, '', 'EASY', 4, 335, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Srisailam Sri Bhramaramba Mallikarjuna Swamy Temple (Jyotirlinga & Shakti Peetham)', 'srisailam-sri-bhramaramba-mallikarjuna-swamy-temple-jyotirlinga-shakti-peetham', 'Mallikarjuna Swamy Temple or Srisailam Temple is a Hindu temple dedicated to the deities Shiva and Parvati, located at Srisailam, Nandyal district in the Indian state of Andhra Pradesh.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Nandyal District', 'Srisailam', '04:30 AM', '10:00 PM', 0, '', 'EASY', 4.8, 420, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Belum Caves (Underground Limestone Passages)', 'belum-caves-underground-karst-limestone-passages', 'Belum Caves are a limestone cave system located in Nandyal district of Andhra Pradesh, India. Extending over 3.23 km (2.01 mi), it is the second-largest cave network in the country.', 'Scenic & Cultural', 'Andhra Pradesh', 'Nandyal District', 'Kolimigundla', '10:00 AM', '05:00 PM', 70, '', 'EASY', 4.4, 13592, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Mahanandi Sri Mahanandiswara Swamy Temple & Mineral Springs', 'mahanandi-sri-mahanandiswara-swamy-temple-mineral-springs', 'Navanandi Schematic route map from Nandyal Mahanandi is a village located east of the Nallamala Hills of Nandyal District, Andhra Pradesh, India. It is surrounded by forests. Within 15 km of Mahanandi, there are nine Nandi shrines known as Nava nandulu. Mahanandi is one of the Nava Nandis. The Mahanandiswara Swamy Temple, an important shrine, is located here.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Nandyal District', 'Mahanandi', '05:30 AM', '06:00 PM', 0, '/images/aptourism/mahanandi.jpg', 'EASY', 4.7, 801, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ahobilam Nava Narasimha Kshetram (Upper & Lower Shrines)', 'ahobilam-nava-narasimha-kshetram-upper-lower-shrines', 'Ahobilam is a town and holy site in the Allagadda mandal of Nandyal district in the Indian state of Andhra Pradesh. It is surrounded by the Eastern Ghats with several mountain hills and gorges. It is the centre of worship of Narasimha, the lion-headed avatar of Vishnu, along with his consort Pratyangira, an avatar of Lakshmi.', 'Waterfalls & Gorges', 'Andhra Pradesh', 'Nandyal District', 'Allagadda', '06:00 AM', '04:00 PM', 0, '', 'EASY', 4.7, 4878, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Yaganti Sri Uma Maheshwara Temple & The Growing Nandi', 'yaganti-sri-uma-maheshwara-temple-the-growing-nandi', 'Yaganti Temple or Sri Yaganti Uma Maheswara Temple is a temple of Shiva in Nandyal district in the India state of Andhra Pradesh. It was built according to Vaishnavaite traditions. ', 'Heritage & Spiritual', 'Andhra Pradesh', 'Nandyal District', 'Banaganapalle', '06:00 AM', '08:00 PM', 0, '/images/candidates/nandyal/2024071657.jpg', 'EASY', 4.7, 19462, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Srisailam Dam & Krishna River Gorge Viewpoint', 'srisailam-dam-krishna-river-gorge-viewpoint', 'The Srisailam Dam is a gravity dam built on the confluence of Tungabhadra River and Krishna River. Its hydroelectric power station is India''s 2nd largest by capacity. It is located in the Nallamala Hills near the temple town Srisailam. The dam spans a deep gorge between the districts Nandyal (Andhra Pradesh) and Nagarkurnool (Telangana).', 'Scenic & Cultural', 'Andhra Pradesh', 'Nandyal District', 'Srisailam', '06:00 AM', '06:00 PM', 0, '', 'EASY', 4.6, 140, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Nagarjunasagar-Srisailam Tiger Reserve & Chenchu Trails', 'nagarjunasagar-srisailam-tiger-reserve-chenchu-trails', 'Nagarjunsagar-Srisailam Tiger Reserve is the largest tiger reserve in India encompassing an area of 3,728 km2 (1,439 sq mi) in two states as two parts: NagarjunaSagar-Srisailam Tiger Reserve in Nandyal, Prakasam, Palnadu, of Andhra Pradesh and as Amrabad Tiger Reserve in Nalgonda and Nagarkurnool districts of Telangana. Its core area is 1,200 km2 (460 sq mi).', 'Lakes, Dams & Waterways', 'Andhra Pradesh', 'Nandyal District', 'Atmakur / Srisailam', '06:00 AM', '06:00 AM', 350, '', 'EASY', 4.5, 66, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Banaganapalle Royal Nawab Palace & Citadel', 'banaganapalle-royal-nawab-palace-citadel', 'Banaganapalli is a town in the state of Andhra Pradesh, India. It lies in Nandyal district, 38 km west of the city of Nandyal. Banaganapalli is famous for its mangoes and has a cultivar, Banaganapalli, named after it. Between 1790 and 1948, Banaganapalli was the capital of the princely state of the same name, Banganapalle State. Banaganapalli Gram panchayat', 'Historical Forts & Monuments', 'Andhra Pradesh', 'Nandyal District', 'Banaganapalle', '09:00 AM', '05:00 PM', 0, '', 'EASY', 4.1, 474, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Owk Reservoir & Historic Limestone Waterfalls', 'owk-reservoir-historic-limestone-waterfalls', 'The Owk Reservoir, situated in Nandyal, Andhra Pradesh, serves as a crucial water resource, primarily for irrigation and local agriculture, while also supporting diverse ecosystems. Its engineering reflects advanced hydraulic principles, showcasing the integration of natural topography with human ingenuity.', 'Waterfalls & Gorges', 'Andhra Pradesh', 'Nandyal District', 'Owk', '08:00 AM', '05:30 PM', 0, '', 'EASY', 4.1, 381, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kolimigundla Limestone Karst Formations', 'kolimigundla-limestone-karst-formations', 'Kolimigundla mandal used to be a part of Kurnool district and was made a part of the newly formed Nandyal district on 4 April 2022 following the reorganization of districts in the state. The mandal is part of Banaganapalle revenue division from 31 Dec 2025.', 'Scenic & Cultural', 'Andhra Pradesh', 'Nandyal District', 'Kolimigundla', '08:00 AM', '06:00 PM', 0, '/images/candidates/nandyal/2024071697-1.jpg', 'EASY', 4.4, 13592, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sangameswaram Submerged Temple of 7 Rivers', 'sangameswaram-submerged-temple-of-7-rivers', 'Sangameswaram The Sangameswara temple is a Hindu temple in the Nandyal district, Andhra Pradesh, India. It is located near Muchumarri at the confluence of the Krishna and Bhavanasi rivers, in the foreshore of the Srisailam reservoir, where it is submerged for part of the time, surfacing when the water level recedes to a sufficient degree.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Nandyal District', 'Pagidyala / Nandikotkur', '08:00 AM', '06:00 PM', 50, '', 'EASY', 4.6, 1256, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Nava Nandi Pilgrimage Circuit of Nandyal', 'nava-nandi-pilgrimage-circuit-of-nandyal', 'Description of Nava Nandi Temples, the nine Shiva temples dedicated for Sri Nandikeshwara in and around Nandyal, Andhra Pradesh', 'Heritage & Spiritual', 'Andhra Pradesh', 'Nandyal District', 'Nandyal Rural', '06:00 AM', '08:30 PM', 0, '', 'EASY', 4.6, 167, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Mantralayam Sri Raghavendra Swamy Mutt & Brindavanam', 'mantralayam-sri-raghavendra-swamy-mutt-brindavanam', 'Sri Raghavendra Swami Mutt (the temple and monastery surrounding the burial site of Sri Raghavendra Teertha) is located on the bank of Tungabhadra River in Mantralayam in Adoni taluk of Kurnool district in Andhra Pradesh, India.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Kurnool District', 'Mantralayam', '06:00 AM', '09:00 PM', 0, '/images/candidates/kurnool/2018022874.jpg', 'EASY', 4.8, 32397, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Orvakal Natural Rock Garden & Canyon', 'orvakal-natural-rock-garden-canyon', 'Orvakal Rock Garden, or Oravakallu Rock Garden, is the 1000 acre Sculpture Garden park with natural cave and igneous rock formations between pools of water. It is located on NH-40 highway, near the village of Orvakal, about 20 kilometres (12 mi) from Kurnool, Andhra Pradesh, southern India.', 'Scenic & Cultural', 'Andhra Pradesh', 'Kurnool District', 'Orvakal', '08:00 AM', '06:00 PM', 25, '/images/candidates/kurnool/orvakallu-rock-garden-kurnool-andhra-pradesh-1-attr-popular.jpg', 'EASY', 4.1, 5171, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Konda Reddy Buruju & Kurnool Fort', 'konda-reddy-buruju-kurnool-fort', 'Konda Reddy Fort, also known as Kondareddy Buruju is a fort situated in the city of Kurnool in Andhra Pradesh, India. At a distance of 2 km from Kurnool Railway Station, 2.9 km from Kurnool New Bus Stand and 24 km from Alampur, Konda Reddy fort is an imposing structure situated in the heart of Kurnool City.', 'Historical Forts & Monuments', 'Andhra Pradesh', 'Kurnool District', 'Kurnool Urban', '08:30 AM', '06:30 PM', 20, '/images/aptourism/konda_reddy_buruju.jpg', 'EASY', 4.5, 29196, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Adoni Hill Fort & 12 Tiers of Perimeter Ramparts', 'adoni-hill-fort-12-tiers-of-perimeter-ramparts', 'Adoni Fort near Kurnool - discover Timings, History, Architecture, Best Time to Visit, trip duration, distance, near by places, location with route map & directions and photos.', 'Historical Forts & Monuments', 'Andhra Pradesh', 'Kurnool District', 'Adoni', '07:00 AM', '05:30 PM', 0, '/images/candidates/kurnool/2024110739.jpg', 'EASY', 4.2, 209, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Tungabhadra & Hundri River Confluence Promenade', 'tungabhadra-hundri-river-confluence-promenade', 'It also serves as the district headquarters of its Kurnool district. As of 2011 census, it is the fifth most populous city in the state with a population of 425,214. It is located on the banks of the Tungabhadra river.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Kurnool District', 'Kurnool Urban', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.4, 81, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kurnool Authentic Uggani Bajji Culinary Trail', 'kurnool-authentic-uggani-bajji-culinary-trail', 'Green Chilli Fritters (Mirchi Bajji) go well with UGGANI. People in Kurnool Anantapur in Andhra Pradesh, adjacent Gadwal district in Telangana relish this as a breakfast item and like it along with Chilli fritters. Uggani is such a simple recipe, it can be made in just 15 mins.', 'Scenic & Cultural', 'Andhra Pradesh', 'Kurnool District', 'Kurnool Urban', '06:30 AM', '09:30 PM', 30, '', 'EASY', 4.3, 8, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Jagannatha Gattu Sri Jagannatha Swamy Temple', 'jagannatha-gattu-sri-jagannatha-swamy-temple', 'Jagannatha Gattu Temple is also known as Rupala Sangameswara Temple located on Jagannatha Hill near B.Thandrapadu in Kurnool district. This temple is dedicated to Lord Siva. The shivalinga is of 6 feet height and 2 feet in width which is made up of granite stone.It has a notable history from the yugas.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Kurnool District', 'Kurnool Rural', '06:00 AM', '08:00 PM', 0, '', 'EASY', 4.8, 110, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Venkanna Bavi Ancient Heritage Stepwell', 'venkanna-bavi-ancient-heritage-stepwell', 'Venkanna Bavi Temple Kurnool - Nativeplanet list with Venkanna Bavi Temple Tourist Attractions details, Venkanna Bavi Temple Attraction photos, Venkanna Bavi Temple travel info etc. of places to visit or see in Kurnool.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Kurnool District', 'Kurnool Urban', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4, 5, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Yemmiganur Handloom Cotton Saree Weaving Guilds', 'yemmiganur-handloom-cotton-saree-weaving-guilds', 'Handicraft Yemmiganur famous for the handloom weaving: It is a great town for the handloom cloth production. The weavers are poor, and hard workers. In a house they worked the whole family on loom. 70 % percent of people depend on handloom weaving. Weaving is a one of the great arts. There they producing a good quality of sarees.', 'Artisans & Culture', 'Andhra Pradesh', 'Kurnool District', 'Yemmiganur', '09:00 AM', '06:30 PM', 0, '', 'EASY', 4.1, 27, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Rollapadu Wildlife Sanctuary (Great Indian Bustard Haven)', 'rollapadu-wildlife-sanctuary-great-indian-bustard-haven', 'Rollapadu Wildlife Sanctuary is in Nandyal district, Andhra Pradesh, India. It is primarily as a habitat of the great Indian bustard, the species has suffered a drastic fall in its numbers in the sanctuary in recent years.', 'Nature & Wildlife', 'Andhra Pradesh', 'Kurnool District', 'Nandikotkur', '07:00 AM', '05:30 PM', 30, '', 'EASY', 4.2, 880, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Alur Ancient Granite Inscriptions & Heritage Shrines', 'alur-ancient-granite-inscriptions-heritage-shrines', 'There are two well-known temples in Aluru. The Lord Navanepattayya Swamy Temple is famous for the modern-looking Lord Sai Baba of Shirdi Temple, located near National Highway 167 in the centre of the town. The temple provides financial resources to support the village''s many schools. The Anjaneya Swamy Temple is a forest temple located just outside Aluru.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Kurnool District', 'Alur', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.4, 34, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Nandavaram Sri Chowdeshwari Devi Temple', 'nandavaram-sri-chowdeshwari-devi-temple', 'Hundreds of years ago, it is said, that there was a kingdom called Nandavara on the banks of the river Tunga in Karnataka near Raichur district, or another namesake village Nandavaram located in the Banaganapalle Mandal of the Kurnool district of Andhra Pradesh. According to a legend the king of Nandavara was a Shakti Upasaka.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Kurnool District', 'Nandavaram', '06:00 AM', '08:30 PM', 0, '', 'EASY', 4.7, 2350, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Gooty Fort (Shell-Shaped Monolithic Hill Citadel)', 'gooty-fort-shell-shaped-monolithic-hill-citadel', 'The Gooty Fort, also known as Ravadurg and Gutti Kota, is a ruined fort located on a hill in the Gooty town of Andhra Pradesh, India. The town of Gooty (originally, "Gutti") is located in the Ananthapur district of Andhra Pradesh.', 'Historical Forts & Monuments', 'Andhra Pradesh', 'Ananthapuramu District', 'Gooty', '08:00 AM', '05:30 PM', 0, '', 'EASY', 4.3, 1090, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Tadipatri Sri Chintala Venkataramana & Bugga Ramalingeswara Temples', 'tadipatri-sri-chintala-venkataramana-bugga-ramalingeswara-temples', 'Bugga Ramalingeswara Swamy Temple (Telugu: బుగ్గరామలింగేశ్వర స్వామి ఆలయం) is a Shiva shrine situated on the southern bank of the Penna River in Tadipatri, Anantapur district of Andhra Pradesh, India.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Ananthapuramu District', 'Tadipatri', '06:00 AM', '08:30 PM', 0, '/images/aptourism/bugga_ramalingeswara_swamy_temple.jpg', 'EASY', 4.7, 3021, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Aluru Kona Sri Ranganatha Swamy Waterfall Temple', 'aluru-kona-sri-ranganatha-swamy-waterfall-temple', 'Sacred hilltop cave shrine of Lord Sri Ranganatha Swamy located amidst scenic hills and seasonal waterfalls near Tadipatri in Ananthapuramu district, featuring perennial freshwater springs.', 'Waterfalls & Gorges', 'Andhra Pradesh', 'Ananthapuramu District', 'Tadipatri Rural', '06:00 AM', '06:00 PM', 0, '/images/candidates/ananthapuramu/2019080725.jpg', 'EASY', 4.8, 120, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Vajrakarur Diamond Fields & Mining Grounds', 'vajrakarur-diamond-fields-mining-grounds', 'Vajrakarur is a village in Anantapur district of the Indian state of Andhra Pradesh. It is the mandal headquarters of Vajrakarur mandal in Anantapur revenue division.', 'Scenic & Cultural', 'Andhra Pradesh', 'Ananthapuramu District', 'Vajrakarur', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.1, 22, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ananthapuramu Historic Clock Tower & ISKCON Temple', 'ananthapuramu-historic-clock-tower-iskcon-temple', 'Clock Tower is a structure located at the centre of Anantapur in the Indian state of Andhra Pradesh. It was built in memory of martyrs of the Indian freedom movement.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Ananthapuramu District', 'Ananthapuramu Urban', '05:00 AM', '08:30 PM', 0, '/images/aptourism/iskcon_temple.jpg', 'EASY', 4.5, 9743, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Guntakal Major Railway Junction Heritage & Steam Locos', 'guntakal-major-railway-junction-heritage-steam-locos', 'Discover the history of Guntakal — from its 1872 railway junction origins to its role as a major rail hub and gateway to Rayalaseema, Andhra Pradesh.', 'Scenic & Cultural', 'Andhra Pradesh', 'Ananthapuramu District', 'Guntakal', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.2, 47620, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Yadiki Underground Limestone Caves', 'yadiki-underground-limestone-karst-caves', 'Yadiki Caves are among the most fascinating natural attractions in Anantapur district, Andhra Pradesh. Situated midway between Gooty and Tadipatri, these ancient limestone caves are renowned for their impressive stalactite and stalagmite formations, making them a popular destination for nature lovers, adventure enthusiasts, and geology enthusiasts.', 'Scenic & Cultural', 'Andhra Pradesh', 'Ananthapuramu District', 'Yadiki', '09:00 AM', '04:30 PM', 0, '', 'EASY', 4.5, 11, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Pennar Ahobilam Sri Lakshmi Narasimha Swamy Temple', 'pennar-ahobilam-sri-lakshmi-narasimha-swamy-temple', 'Penna Ahobilam is considered one of the Swayambhu (self‑manifested) Narasimha kshetras in Andhra Pradesh. According to district records, the temple was built in the year 1478 of the Salivahana era by Sri Krishna Devarayala (Sadashivaraya) on a hill near Uravakonda.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Ananthapuramu District', 'Ananthapuramu Rural', '06:00 AM', '07:30 PM', 0, '/images/aptourism/ahobilam.jpg', 'EASY', 4.5, 2050, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Singanamala Lake & Historic British Sluice', 'singanamala-lake-historic-british-sluice', 'Heritage Monuments, Temples, Forts and Historical Structures S.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Ananthapuramu District', 'Singanamala', '06:00 AM', '06:00 PM', 0, '', 'EASY', 4.5, 111, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Uravakonda Handloom & Cotton Ginning Hub', 'uravakonda-handloom-cotton-ginning-hub', 'Uravakonda is a census town in Anantapur district of the Indian state of Andhra Pradesh. It is the headquarters of Uravakonda mandal in Guntakal revenue division.', 'Artisans & Culture', 'Andhra Pradesh', 'Ananthapuramu District', 'Uravakonda', '09:00 AM', '07:00 PM', 0, '', 'EASY', 4.7, 26, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Veerabhadra Temple & The Hanging Pillar of Lepakshi', 'sri-veerabhadra-temple-the-hanging-pillar-of-lepakshi', 'Veerabhadra temple is a Hindu temple located in the Lepakshi, in the state of Andhra Pradesh, India. The temple is dedicated to Virabhadra, a fierce form of Shiva, a major deity in Hinduism. Built in the 16th century, the architectural features of the temple are in the Vijayanagara style with profusion of carvings and paintings at almost every exposed surface of the temple.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Sri Sathya Sai District', 'Lepakshi', '06:00 AM', '06:00 PM', 0, '/images/aptourism/lepakshi.jpg', 'EASY', 4.7, 15639, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('The Monolithic Basavanna (Colossal Nandi of Lepakshi)', 'the-monolithic-basavanna-colossal-nandi-of-lepakshi', 'Lepakshi Temple is a remarkable architectural and historical marvel located in the town of Lepakshi, in the Sri Sathya Sai district of Andhra Pradesh, India. It is renowned for its stunning Dravidian-style architecture, intricate stone carvings, and rich history dating back to the 16th century.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Sri Sathya Sai District', 'Lepakshi', '06:00 AM', '06:30 PM', 0, '', 'EASY', 4.6, 9516, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Prasanthi Nilayam Ashram & Chaitanya Jyothi Museum', 'prasanthi-nilayam-ashram-chaitanya-jyothi-museum', 'The Chaitanya Jyothi Museum at Prasanthi Nilayam was built to commemorate the 75th year of the Advent of the Sathya Sai Avatar and houses an exhibition on His Life and Mission. The building is a fusion of different architectural styles blending Oriental architecture with elements of traditional Indian temple design.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Sri Sathya Sai District', 'Puttaparthi', '05:00 AM', '07:00 PM', 0, '', 'EASY', 4.7, 13845, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Penukonda Fort & Gagan Mahal Royal Palace', 'penukonda-fort-gagan-mahal-royal-palace', 'The two famous attractions here are Gagan Mahal Palace and Babayya Darga. Gagan Mahal was constructed in 1575 AD and it throws light on the life style Vijayanagara Dynasty. Gagan Mahal got few additions during the Muslim rule of the region. Another important place is Babayya Darga within the fort.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Sri Sathya Sai District', 'Penukonda', '08:30 AM', '05:30 PM', 0, '/images/aptourism/penukonda_fort.jpg', 'EASY', 4.2, 649, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Dharmavaram GI-Tagged Handloom Silk Saree Capital', 'dharmavaram-gi-tagged-handloom-silk-saree-capital', 'Dharmavaram silk saris are textiles woven by hand with mulberry silk and zari. They are made in Dharmavaram of Sri Sathya Sai district in the Indian state of Andhra Pradesh.', 'Artisans & Culture', 'Andhra Pradesh', 'Sri Sathya Sai District', 'Dharmavaram', '09:30 AM', '09:00 PM', 0, '', 'EASY', 4.9, 739, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Lakshmi Narasimha Swamy Temple (Kadiri)', 'sri-lakshmi-narasimha-swamy-temple-kadiri', 'Irrespective of the religion, people celebrates the temple festivals. Devotees from Tamil Nadu, Karnataka used to this temple regularly. Sri Kadiri Lakshmi Narasimha Swamy Shrine''s Map Location and How to Go There MAP INSTRUCTIONS The big red marker represents the latitude & longitude values of this shrine on map.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Sri Sathya Sai District', 'Kadiri', '06:00 AM', '08:30 PM', 0, '', 'EASY', 4.7, 3172, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Thimmamma Marrimanu (World''s Largest Banyan Tree Canopy)', 'thimmamma-marrimanu-world-s-largest-banyan-tree-canopy', 'Thimmamma Marrimanu (Telugu: తిమ్మమ్మ మర్రిమాను, lit. ''Thimmamma''s Banyan Tree'') is a banyan tree in Anantapur, located about 25 kilometers from Kadiri, Andhra Pradesh, India. It is probably a specimen of Ficus benghalensis. In the Telugu language, " marri " denotes "banyan" and " manu " denotes "trunk". Its canopy covers 19,107 m2 (4.', 'Scenic & Cultural', 'Andhra Pradesh', 'Sri Sathya Sai District', 'Kadiri Rural', '06:00 AM', '06:00 PM', 20, '', 'EASY', 4.3, 2878, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Hemavathi Ancient Nolamba Temple Complex (Doddeswara)', 'hemavathi-ancient-nolamba-temple-complex-doddeswara', 'The historic village of Hemavathi is home to a remarkable group of temples built in the 8th-10th Centuries under the reign of the Nolamba Dynasty. Overview The historic village of Hemavathi is home to a remarkable group of temples built in the 8th-10th Centuries under the reign of the Nolamba Dynasty. It was known as Henjeri under the Pallavas.', 'Heritage & Spiritual', 'Andhra Pradesh', 'Sri Sathya Sai District', 'Amarapuram', '06:30 AM', '07:00 PM', 0, '', 'EASY', 4.7, 634, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Bukkapatnam Historic Reservoir & Krishnadevaraya Dam', 'bukkapatnam-historic-reservoir-krishnadevaraya-dam', 'Krishnadevaraya was the son of Tuluva Narasa Nayaka and his queen Nagamamba. Tuluva Narasa Nayaka was an army commander under Saluva Narasimha Deva Raya, who later took control to prevent the disintegration of the empire and established the Tuluva dynasty of the Vijayanagara Empire. He ascended the throne after the death of his half-brother Viranarasimha.', 'Lakes, Dams & Waterways', 'Andhra Pradesh', 'Sri Sathya Sai District', 'Bukkapatnam', '06:00 AM', '06:00 PM', 0, '', 'EASY', 4.4, 314, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Sathya Sai Space Theatre & Planetarium', 'sri-sathya-sai-space-theatre-planetarium', 'The Sri Sathya Sai Space Theatre is an educational public planetarium in Puttaparthi that presents astronomy and space science shows', 'Scenic & Cultural', 'Andhra Pradesh', 'Sri Sathya Sai District', 'Puttaparthi', '10:00 AM', '11:00 AM', 20, '', 'EASY', 4.6, 292, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Charminar & Laad Bazaar Lacquer Bangles', 'charminar-laad-bazaar-lacquer-bangles', 'The craft dates back to the Qutb Shahi dynasty (16th century) and flourished under the Nizams. The primary market is Laad Bazaar (also called Chudi Bazaar), located near the iconic Charminar. It is believed that Sultan Mohammad Quli Qutb Shah established the market to provide bridal trousseau for his daughter''s wedding.', 'Artisans & Culture', 'Telangana', 'Hyderabad District', 'Charminar', '09:30 AM', '11:00 PM', 0, '/images/candidates/hyderabad/charminar-hyderabad-telangana-1-city-homepage.jpeg', 'EASY', 4.3, 221, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Golconda Fort & Acoustic Portico Walk', 'golconda-fort-acoustic-portico-walk', 'Golconda is a fortified citadel and ruined city located on the western outskirts of Hyderabad, Telangana, India. The fort was built by Kakatiya ruler Pratāparudra in the 11th century out of mud walls.', 'Historical Forts & Monuments', 'Telangana', 'Hyderabad District', 'Golconda', '09:00 AM', '07:45 PM', 25, '/images/candidates/hyderabad/golconda-fort-hyderabad-telangana-1-attr-homepag.jpg', 'EASY', 3.8, 2491, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Salar Jung Museum (World''s Largest One-Man Art Collection)', 'salar-jung-museum-world-s-largest-one-man-art-collection', 'The Salar Jung Museum was established in the year 1951 and is located on the southern bank of the River Musi in Hyderabad, Telangana. The Salar Jung family is responsible for the collection of this rare and eclectic ensemble of art objects from India and the world.', 'Artisans & Culture', 'Telangana', 'Hyderabad District', 'Darulshifa', '10:00 AM', '05:00 PM', 50, '', 'EASY', 4.4, 78030, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Chowmahalla Palace & Royal Vintage Car Collection', 'chowmahalla-palace-royal-vintage-car-collection', 'Chowmahalla Palace or Chowmahallat is the palace of the Nizams of Hyderabad State located in Hyderabad, Telangana, India. It was the seat of power of the Asaf Jahi dynasty (1720-1948) and was the official residence of the Nizams during their reign.', 'Historical Forts & Monuments', 'Telangana', 'Hyderabad District', 'Khilwat (Near Charminar)', '10:00 AM', '05:00 PM', 100, '', 'EASY', 4.4, 53224, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Qutb Shahi Tombs Heritage Park', 'qutb-shahi-tombs-heritage-park', 'The Qutub Shahi tombs are a series of Islamic tombs and mosques built by the various kings of the Qutub Shahi dynasty, located in the Ibrahim Bagh (garden precinct), close to the famous Golconda Fort in Hyderabad, in the Hyderabad district of the state of Telangana, India.', 'Historical Forts & Monuments', 'Telangana', 'Hyderabad District', 'Ibrahim Bagh (Golconda)', '09:00 AM', '06:30 PM', 40, '', 'EASY', 4.4, 22554, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Birla Mandir & B.M. Birla Planetarium', 'birla-mandir-b-m-birla-planetarium', 'B. M. Birla Science Museum is an Indian science museum located in Hyderabad, India. Constructed by civil engineer P. A. Singaravelu, it comprises a planetarium, museum, science centre, art gallery as well as a dinosaurium.', 'Artisans & Culture', 'Telangana', 'Hyderabad District', 'Khairatabad (Naubat Pahad)', '07:00 AM', '06:30 PM', 0, '', 'EASY', 4.2, 2044, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Hussain Sagar Lake & 350-Ton Buddha Monolith', 'hussain-sagar-lake-350-ton-buddha-monolith', 'The Buddha Statue of Hyderabad is a monolith located in Hyderabad, Telangana, India. It is the world''s tallest monolith of Gautama Buddha, erected on Gibraltar Rock in the middle of Hussain Sagar lake.', 'Lakes, Dams & Waterways', 'Telangana', 'Hyderabad District', 'Khairatabad', '09:00 AM', '08:30 PM', 30, '', 'EASY', 4.3, 2979, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Nehru Zoological Park & Forest Safari', 'nehru-zoological-park-forest-safari', 'Nehru Zoological Park''s construction was started on 26 October 1959 and opened to the public on 6 October 1963. The Park is run by forest department, Government of Telangana, and is named after the first Prime Minister of India, Jawaharlal Nehru.', 'Nature & Wildlife', 'Telangana', 'Hyderabad District', 'Bahadurpura', '08:30 AM', '05:00 PM', 70, '/images/candidates/hyderabad/nehru-zoological-park-hyderabad-telangana-1-attr-popular.jpg', 'EASY', 4.2, 104277, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Paigah Tombs & Geometrical Stucco Craft', 'paigah-tombs-geometrical-stucco-craft', 'Paigah Tombs or Maqbara Shams al-Umara, are the tombs belonging to the nobility of Paigah family, who were fierce loyalists of the Nizams, served as statespeople, philanthropists and generals under and alongside them.', 'Historical Forts & Monuments', 'Telangana', 'Hyderabad District', 'Saidabad (Pisulbanda)', '10:00 AM', '05:00 PM', 0, '', 'EASY', 4.4, 810, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Shilparamam Arts & Crafts Cultural Village', 'shilparamam-arts-crafts-cultural-village', 'Shilparamam is an arts and crafts village located in Madhapur, Hyderabad, Telangana, India. The village was conceived with an idea to create an environment for the preservation of traditional Indian crafts.', 'Artisans & Culture', 'Telangana', 'Hyderabad District', 'Madhapur (Hitec City)', '10:30 AM', '08:30 PM', 60, '', 'EASY', 4.3, 104158, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Taramati Baradari & Ibrahim Bagh Cultural Complex', 'taramati-baradari-ibrahim-bagh-cultural-complex', 'Taramati Baradari is a historical sarai as part of Ibrahim Bagh, a Persian style garden built during the reign of Ibrahim Quli Qutub Shah, the fourth Sultan of Golconda.', 'Scenic & Cultural', 'Telangana', 'Hyderabad District', 'Golconda (Near Gandipet road)', '09:30 AM', '10:30 PM', 0, '', 'EASY', 4.2, 7500, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Durgam Cheruvu & Extradosed Cable-Stayed Bridge', 'durgam-cheruvu-extradosed-cable-stayed-bridge', 'The Durgam Cheruvu Cable Bridge is an extradosed bridge in Hyderabad, Telangana, India. The bridge is located near Inorbit Mall at Madhapur. The bridge connects Jubilee Hills with HITEC City and eases traffic congestion to Madhapur across Durgam Cheruvu.', 'Lakes, Dams & Waterways', 'Telangana', 'Hyderabad District', 'Madhapur / Jubilee Hills', '06:00 AM', '11:00 PM', 20, '/images/candidates/hyderabad/2019043075.jpg', 'EASY', 4.6, 920, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Nizam''s Silver Jubilee Museum (Purani Haveli)', 'nizam-s-silver-jubilee-museum-purani-haveli', 'The Nizam''s Museum also known as the Purani Haveli Museum or the Silver Jubilee Museum, Hyderabad, Telangana, India was created at the wish of the seventh/last Nizam of Hyderabad. His rule along with his father''s rule spanned roughly a century from the middle of the 19th to the middle of the 20th century. During these years, the State of Hyderabad saw great development.', 'Historical Forts & Monuments', 'Telangana', 'Hyderabad District', 'Pathar Gatti', '10:00 AM', '05:00 PM', 100, '', 'EASY', 4.2, 4990, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Hyderabadi Dum Biryani & Haleem Gastronomy Corridor', 'hyderabadi-dum-biryani-haleem-gastronomy-corridor', 'Hyderabadi biryani (also known as Hyderabadi dum biryani) is a style of biryani originating from Hyderabad, India made with basmati rice and meat (mostly goat meat).', 'Scenic & Cultural', 'Telangana', 'Hyderabad District', 'Khairatabad / Abids / Charminar', '11:30 AM', '11:30 PM', 250, '/images/telangana/hyderabad.jpg', 'EASY', 4, 90903, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ramoji Film City (World''s Largest Film Studio Complex)', 'ramoji-film-city-world-s-largest-film-studio-complex', 'Ramoji Film City is an integrated film studio facility located right outside of Hyderabad, India. Spread over 2,000 acres (810 ha), it was recognized as the world''s largest film studio complex by the Guinness World Records in 2005.', 'Scenic & Cultural', 'Telangana', 'Ranga Reddy District', 'Hayathnagar / Abdullapurmet', '09:00 AM', '05:30 PM', 1, '', 'EASY', 4.4, 50150, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Osman Sagar (Gandipet Lake) & Landscape Park', 'osman-sagar-gandipet-lake-landscape-park', 'Osman Sagar is a reservoir in the city of Hyderabad. The lake is around 46 km 2, and the reservoir is around 29 km 2, with total level of 545.592 metres and a capacity of 110,435.702 cubic metres.', 'Lakes, Dams & Waterways', 'Telangana', 'Ranga Reddy District', 'Gandipet', '09:00 AM', '07:00 PM', 50, '', 'EASY', 4.4, 647, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Himayat Sagar Lake & Eco-Boardwalk', 'himayat-sagar-lake-eco-boardwalk', 'Himayat Sagar is an artificial lake about 20 kilometres (12 mi) from Hyderabad in the Ranga Reddy district of Telangana, India. It lies parallel to a larger artificial lake called Osman Sagar.', 'Lakes, Dams & Waterways', 'Telangana', 'Ranga Reddy District', 'Rajendranagar', '06:00 AM', '06:30 PM', 0, '', 'EASY', 4.4, 114, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Chilkur Balaji Temple (''Visa God'' of Telangana)', 'chilkur-balaji-temple-visa-god-of-telangana', 'Gopuram at Chilkur Temple "Chilkur Balaji Temple is a Hindu temple dedicated to Lord Venkateswara, located near Osman Sagar in Telangana. It is regarded as one of the prominent pilgrimage centres in the Hyderabad region and is particularly known for its traditions associated with devotees seeking fulfilment of their wishes.".', 'Heritage & Spiritual', 'Telangana', 'Ranga Reddy District', 'Gandipet / Moinabad', '05:00 AM', '08:00 PM', 0, '', 'EASY', 4.7, 53944, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Statue of Equality (Sri Ramanujacharya 216-Foot Monument)', 'statue-of-equality-sri-ramanujacharya-216-foot-monument', 'The Statue of Equality is a statue of the 11th-century Indian philosopher Ramanuja, located on the premises of the Chinna Jeeyar Trust at Muchintal, Ranga Reddy district in the outskirts of Hyderabad. It is the second tallest sitting statue in the world. The project of building the statue was conceptualised by the trust to commemorate the 1,000th birth anniversary of Ramanuja.', 'Heritage & Spiritual', 'Telangana', 'Ranga Reddy District', 'Shamshabad (Muchintal)', '11:00 AM', '08:00 PM', 200, '', 'EASY', 4.6, 35599, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Maheshwaram Sri Shiva Ganga Temple & Historic Stepwell', 'maheshwaram-sri-shiva-ganga-temple-historic-stepwell', 'Sri Shivaganga Raja Rajeshwara Swamy Devasthanam, Maheshwaram, Telangana - temple timings, history, poojas & how to reach this Shiva shrine.', 'Heritage & Spiritual', 'Telangana', 'Ranga Reddy District', 'Maheshwaram', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.7, 990, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sanghi Temple on Paramanandagiri Hill', 'sanghi-temple-on-paramanandagiri-hill', 'Sanghi Temple, which is said to be the replica of Tirumala temple is located at Sanghi Nagar in Telangana in India, is about 35 km from Hyderabad city. The sacred Raja Gopuram, which is very tall, can be seen from several kilometers away. The temple is located on the top of Paramanand Giri hill, which attracts a number of devotees.', 'Heritage & Spiritual', 'Telangana', 'Ranga Reddy District', 'Hayathnagar', '08:30 AM', '08:00 PM', 0, '', 'EASY', 4.5, 21675, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ananthagiri Hills Gateway Corridor (Chevella Route)', 'ananthagiri-hills-gateway-corridor-chevella-route', 'One platform for the entire history of the Telugu people — Telangana and Andhra Pradesh. Interactive maps, timelines, dynasties, battles, heritage, AI exploration and exam challenges.', 'Scenic & Cultural', 'Telangana', 'Ranga Reddy District', 'Chevella', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.2, 9705, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Jalavihar Water Park & Family Recreational Complex', 'jalavihar-water-park-family-recreational-complex', 'Jalavihar is a waterpark located in Hyderabad, Telangana, (India) within an area of about 12.5 acres (5.1 ha). Located beside Sanjeevaiah Park and along the Hussain Sagar lake, the park was inaugurated on 20 May 2007.', 'Scenic & Cultural', 'Telangana', 'Ranga Reddy District', 'Khairatabad / Sanathnagar border', '11:00 AM', '07:00 PM', 450, '', 'EASY', 4, 39960, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Shadnagar Heritage & Farooqnagar Gateway', 'shadnagar-heritage-farooqnagar-gateway', 'Shadnagar is a town and assembly constituency in the Ranga Reddy district in Telangana, India. As part of the reorganisation of districts in Telangana, Shadnagar separated from Mahabubnagar district and merged into Ranga Reddy district Headquarters.', 'Scenic & Cultural', 'Telangana', 'Ranga Reddy District', 'Farooqnagar', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.5, 2500, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
