INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Shamirpet Lake & Deer Forest Sanctuary', 'shamirpet-lake-deer-forest-sanctuary', 'Shamirpet Lake also known as Pelle Cheruvu is an artificial lake near Hyderabad, India, it is about 24 kilometres (15 mi) north of Secunderabad.', 'Lakes, Dams & Waterways', 'Telangana', 'Medchal-Malkajgiri District', 'Shamirpet', '09:00 AM', '05:00 PM', 20, '/images/candidates/medchal-malkajgiri/2020032824.jpg', 'EASY', 3.6, 1557, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
