INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Bommalaramaram Historic Heritage Route', 'bommalaramaram-historic-heritage-route', 'Bommalaramaram (or B. Ramaram) is a village in Yadadri Bhuvanagiri district of the Indian state of Telangana. It is located in Bommalaramaram mandal of Bhongir division, and is also a part of Hyderabad Metropolitan Region. The RRR (Regional Ring Road) goes through this area, Yadagirigutta New Bypass 4 Lanes road also passes here.', 'Heritage & Spiritual', 'Telangana', 'Medchal-Malkajgiri District', 'Keesara border', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.7, 2939, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Medchal Historic Baolis & Stepwells', 'medchal-historic-baolis-stepwells', 'District History Who''s Who Medchal-Malkajgiri District Map Organisation Chart Public Representatives Administrative Setup', 'Scenic & Cultural', 'Telangana', 'Medchal-Malkajgiri District', 'Medchal', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.3, 4576, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Alwal Sri Venkateswara Swamy Temple', 'alwal-sri-venkateswara-swamy-temple', 'Alwal was a prime area under the British Cantonment. It is home to a historic Venkateswara temple, which is located near the Alwal municipal office and is more than 400 years old. Gundam Balaji Temple is also located in this temple premises, which is stated to be 850 years old. There is a temple in the style of the Lotus Temple, Delhi.', 'Heritage & Spiritual', 'Telangana', 'Medchal-Malkajgiri District', 'Alwal', '06:00 AM', '08:30 PM', 0, '', 'EASY', 4.8, 399, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Dhola-ri-Dhani Ethnic Cultural Resort', 'dhola-ri-dhani-ethnic-cultural-resort', 'Dhola ri Dhani Hyderabad (Entry Fee, Timings, Entry Ticket Cost, Price) Dhola ri Dhani Entry Fee 250 Above 5 yrs - Entry Fee with-out Lunch 700 Above 8 yrs - Entry Fee with Lunch 300 5 to 8 yrs - Entry Fee with Lunch 150 per hour for Swimming pool and Rain Dance Adventure Sports Tickets to be purchased from the Adventure Counter.', 'Scenic & Cultural', 'Telangana', 'Medchal-Malkajgiri District', 'Medchal (Kompally)', '11:00 AM', '10:30 PM', 700, '', 'EASY', 3.4, 1267, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Genome Valley International Biotechnology Corridor', 'genome-valley-international-biotechnology-corridor', 'Genome Valley is an Indian high-technology business district spread across 2,000-acre (8.1 km2) / (3.1 sq mi) in Hyderabad, India. It is located across the suburbs Turakapally, Shamirpet, Medchal, Uppal, Patancheru, Jeedimetla, Gachibowli and Keesara.', 'Scenic & Cultural', 'Telangana', 'Medchal-Malkajgiri District', 'Shamirpet', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.5, 244, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kandlakoya Oxygen Park & Treehouse Botanical Reserve', 'kandlakoya-oxygen-park-treehouse-botanical-reserve', 'Kandlakoya is a village in Medchal mandal of the Medchal-Malkajgiri district in Telangana, India, situated approximately 6 km from the town of Medchal and 62 km northeast of Hyderabad. As per the 2011 census, it had a population of 2,802.', 'Nature & Wildlife', 'Telangana', 'Medchal-Malkajgiri District', 'Medchal', '06:00 AM', '06:00 PM', 20, '', 'EASY', 4.2, 5600, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Jawahar Deer Park & Shamirpet Eco-Promenade', 'jawahar-deer-park-shamirpet-eco-promenade', 'Jawahar Deer Park, also Shamirpet Deer Park, is a deer park located in Shamirpet, Medchal-Malkajgiri district, Telangana, India. The Park is spread over 54 acres and has over 100 deer.', 'Nature & Wildlife', 'Telangana', 'Medchal-Malkajgiri District', 'Shamirpet', '09:00 AM', '05:30 PM', 20, '', 'EASY', 3.6, 1557, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ananthagiri Hills & Sri Bugga Ramalingeswara Swamy', 'ananthagiri-hills-sri-bugga-ramalingeswara-swamy', 'A major number of pilgrims visit this temple on this special occasion. At a distance of 7 km from Anantagiri Hills (Padmanabha Temple), 6 km from Vikarabad and 78 km from Hyderabad, The Bugga Ramalingeshwara Swamy temple is located in Bugga Rameshwaram Village. This place is the origin of River Musi.', 'Heritage & Spiritual', 'Telangana', 'Vikarabad District', 'Vikarabad', '06:00 AM', '08:00 PM', 0, '', 'EASY', 4.6, 492, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kotepally Reservoir Adventure & Kayaking Camp', 'kotepally-reservoir-adventure-kayaking-camp', 'Kotepally Reservoir is the serene escape you didn''t know you needed, with kayaking adventures that come with stunning sunsets and scenic views. Just beware, parking''s a real paddle struggle on weekends! Popular For Popular for kayaking and sunset views Must Try kayaking and bathing in the dam overflow Enjoy a boat ride on the reservoir.', 'Lakes, Dams & Waterways', 'Telangana', 'Vikarabad District', 'Kotepally', '09:00 AM', '05:30 PM', 150, '', 'EASY', 4.2, 844, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Tandur Blue Limestone Quarries & Craft Hub', 'tandur-blue-limestone-quarries-craft-hub', 'Prominent stonecraft and natural blue Shahabad limestone quarrying center in Tandur, famed across India for heritage floorings and architectural masonry.', 'Artisans & Culture', 'Telangana', 'Vikarabad District', 'Tandur', '08:30 AM', '06:00 PM', 0, '', 'EASY', 4.2, 151, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kerelli Grassland Valley & Sunset Viewpoint', 'kerelli-grassland-valley-sunset-viewpoint', 'Scenic undulating Deccan grassland valley and elevated sunset viewpoint near Vikarabad, renowned for open horizons, cool breezes, and tranquil panoramic vistas.', 'Scenic & Cultural', 'Telangana', 'Vikarabad District', 'Dharur', '06:00 AM', '06:30 PM', 0, '', 'EASY', 4.2, 9705, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Nagasamudram Lake & Forest Camping Zone', 'nagasamudram-lake-forest-camping-zone', 'The origins of Nagasamudram Lake can be traced back to the early medieval period, believed to have been constructed during the Kakatiya dynasty, which ruled from the 12th to the 14th centuries. Historical records indicate that it was initially designed for irrigation and to support agriculture in the arid regions surrounding Vikarabad.', 'Lakes, Dams & Waterways', 'Telangana', 'Vikarabad District', 'Dharur', '06:00 AM', '06:00 PM', 0, '', 'EASY', 4.5, 4, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Vikarabad Forest Eco-Trek Trails (Godamguda)', 'vikarabad-forest-eco-trek-trails-godamguda', 'Looking for the best hiking trails in Vikarabad? Whether you''re getting ready to hike, bike, trail run, or explore other outdoor activities, AllTrails has 4 scenic trails in the Vikarabad area. Enjoy hand-curated trail maps, along with reviews and photos from nature lovers like you.', 'Lakes, Dams & Waterways', 'Telangana', 'Vikarabad District', 'Vikarabad', '07:00 AM', '05:00 PM', 0, '', 'EASY', 4.5, 718, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Bugga Ramalingeswara Perennial Spring', 'sri-bugga-ramalingeswara-perennial-spring', 'The Bugga Rameshwaram Temple, also known as Sri Bugga Ramalingeshwara Swamy Temple, is a sacred Shiva shrine located in Bugga Rameshwaram village, about 6 km from Vikarabad and 7 km from Ananthagiri Hills, in the Vikarabad district of Telangana. It is one of the most ancient temples in the region, deeply revered for its spiritual significance and natural setting. Historical and Spiritual […]', 'Heritage & Spiritual', 'Telangana', 'Vikarabad District', 'Vikarabad', '06:00 AM', '06:00 PM', 0, '', 'EASY', 4.6, 492, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Manneguda Agricultural Corridor & Farm Markets', 'manneguda-agricultural-corridor-farm-markets', 'Vibrant agrarian road corridor on the Hyderabad-Vikarabad highway, famous for fresh farm stalls, seasonal fruits, organic produce, and popular weekend village dining pitstops.', 'Scenic & Cultural', 'Telangana', 'Vikarabad District', 'Pudur', '07:00 AM', '08:00 PM', 0, '', 'EASY', 4.2, 541, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Godamguda Grasslands & Deccan Safari Viewpoint', 'godamguda-grasslands-deccan-safari-viewpoint', 'Vikarabad District, located in the western part of Telangana, is historically part of the Deccan plateau and Manjira river basin. The region''s strategic position made it a crossroads for major South Indian dynasties.', 'Scenic & Cultural', 'Telangana', 'Vikarabad District', 'Vikarabad', '06:00 AM', '06:30 PM', 0, '', 'MODERATE', 4.7, 38, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
