INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kandi Sri Kalabhairava Swamy Temple', 'kandi-sri-kalabhairava-swamy-temple', 'Kandi is a Mandal in the Sangareddy district of Telangana, India consisting of 22 village panchayats. This mandal was formed as part of the reorganization of districts done by Telangana Government in 2016.', 'Heritage & Spiritual', 'Telangana', 'Sangareddy District', 'Kandi', '06:00 AM', '08:30 PM', 0, '', 'MODERATE', 4.8, 1134, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
