INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Thousand Pillar Temple (Sri Rudreshwara Swamy)', 'thousand-pillar-temple-sri-rudreshwara-swamy', 'The Thousand Pillar Temple or Rudreswara Swamy Temple is a historical Hindu temple located in the city of Hanamakonda, Telangana, India. It is dedicated to Shiva, Vishnu and Surya.', 'Heritage & Spiritual', 'Telangana', 'Hanumakonda District', 'Hanumakonda', '06:00 AM', '08:30 PM', 0, '', 'EASY', 4.5, 32427, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Bhadrakali Temple & Lake Promenade', 'bhadrakali-temple-lake-promenade', 'The temple is believed to be built in 625 CE by the King Pulakeshin II of Chalukya dynasty to commemorate his victory over Vengi region of Andhra Desham, as per the writings on the temple wall. Kakatiya kings later have adopted the temple and considered Goddess Bhadrakali as their kuladevata. A lake was also built by Ganapati-deva adjacent to the temple.', 'Heritage & Spiritual', 'Telangana', 'Hanumakonda District', 'Hanumakonda', '05:30 AM', '08:30 PM', 0, '', 'EASY', 4.8, 32272, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Padmakshi Temple & Jain Rock-Cut Reliefs', 'padmakshi-temple-jain-rock-cut-reliefs', 'Padmakshi Temple is one of the oldest temples in the Hanamakonda area of Telangana, India. It is dedicated to the Hindu goddess Padmakshi (Lakshmi), and also features Jain imagery.', 'Heritage & Spiritual', 'Telangana', 'Hanumakonda District', 'Hanumakonda', '06:00 AM', '06:00 PM', 0, '/images/candidates/hanumakonda/2018062320.jpg', 'EASY', 4.5, 1103, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kazipet Dargah (Hazrat Syed Shah Afzal Biabani)', 'kazipet-dargah-hazrat-syed-shah-afzal-biabani', 'Syed Shah Afzal Biabani (1795 - 1856 A.D / 1210 - 26 Safar, 1272 AH) was a Sufi from Warangal, Hyderabad State (now Kazipet 132 km from Hyderabad, India). He was appointed as Kazi of Warangal during the reign of Nizam Ali Khan (Asaf Jah II).', 'Heritage & Spiritual', 'Telangana', 'Hanumakonda District', 'Kazipet', '05:00 AM', '10:00 PM', 0, '', 'EASY', 4.8, 106, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Inavolu Mallanna Temple (Sri Mallikarjuna Swamy)', 'inavolu-mallanna-temple-sri-mallikarjuna-swamy', 'Mallikarjuna temple, Inavolu is a temple in located in Inavolu in Warangal district in the Indian state of Telangana.', 'Heritage & Spiritual', 'Telangana', 'Hanumakonda District', 'Inavolu', '06:00 AM', '08:00 PM', 0, '', 'EASY', 4.7, 4333, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Dharmasagar Lake & Eco-Tourism Reservoir', 'dharmasagar-lake-eco-tourism-reservoir', 'Dharmasagar is a Town and a mandal in Hanamkonda district in Telangana, India. Dharmasagar is well connected with towns like Kazipet, and Hanamakonda by road. It is 14.4 km far from its District Main Town Warangal and 122 km far from its State Capital Hyderabad.', 'Lakes, Dams & Waterways', 'Telangana', 'Hanumakonda District', 'Dharmasagar', '06:00 AM', '06:30 PM', 0, '', 'EASY', 4.1, 9, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Siddeshwara Temple (Kakatiya Rock Temple)', 'siddeshwara-temple-kakatiya-rock-temple', '& Documentation Methodology The Siddeshwara Temple dates back to the 9th century CE, attributed to the Kakatiya dynasty, which played a crucial role in the cultural and architectural evolution of the region. Historical texts and inscriptions, alongside archaeological surveys, indicate that the temple was constructed to honor Lord Shiva, specifically in his form as Siddeshwara.', 'Heritage & Spiritual', 'Telangana', 'Hanumakonda District', 'Hanumakonda', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.7, 565, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kakatiya Musical Garden & Rock Garden', 'kakatiya-musical-garden-rock-garden', 'Kakatiya Musical Garden is a musical garden located near the Bhadrakali temple in Warangal, Telangana. The garden was established in 1994 and it covers an area of 18 acres (73,000 m2). The main attraction of the garden is a musical water fountain with the perfect synchronization of colourful lights.', 'Waterfalls & Gorges', 'Telangana', 'Hanumakonda District', 'Hanumakonda', '04:00 PM', '08:30 PM', 20, '/images/candidates/hanumakonda/2018062386.jpg', 'EASY', 3.7, 1920, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Waddepally Lake & Boating Promenade', 'waddepally-lake-boating-promenade', 'The beautification work of the lake''s bund is being developed to aim at attracting tourists to the place. it is also a best spot for fishing. and it is located near a shiva temple. govt of Telangana recognised it and made it into a reservoir. now it pumps water for the city', 'Heritage & Spiritual', 'Telangana', 'Hanumakonda District', 'Hanumakonda', '06:00 AM', '06:30 PM', 0, '', 'EASY', 4.3, 360, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Hasanparthy Sri Venkateswara Swamy Gutta', 'hasanparthy-sri-venkateswara-swamy-gutta', 'Hasanparthy is a mandal in Hanumakonda district in the state of Telangana in India. It is governed by Greater Warangal Municipal Corporation.', 'Heritage & Spiritual', 'Telangana', 'Hanumakonda District', 'Hasanparthy', '06:00 AM', '08:00 PM', 0, '', 'MODERATE', 4.6, 20, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Warangal Fort & Kakatiya Kala Thoranam', 'warangal-fort-kakatiya-kala-thoranam', 'Kakatiya Kala Thoranam (also called Warangal Gate) is a historical arch in the Warangal district, of the Indian state of Telangana. The Warangal Fort has four ornamental gates which originally formed the gates to the ruins of the great Shiva temple which are known as Kakatiya Kala Thoranam or Warangal Gates.', 'Heritage & Spiritual', 'Telangana', 'Warangal District', 'Khila Warangal', '09:00 AM', '06:00 PM', 25, '/images/telangana/warangal.jpg', 'EASY', 4.5, 2500, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kush Mahal (Warangal Fort Inner Enclosure)', 'kush-mahal-warangal-fort-inner-enclosure', 'Warangal Fort is located in Warangal District, Telangana, India. It was the capital city of Kakatiya dynasty and the Musunuri Nayakas. The fort appears to have existed since at least the 12th century when it was the capital of the Kakatiyas.', 'Historical Forts & Monuments', 'Telangana', 'Warangal District', 'Khila Warangal', '09:00 AM', '06:00 PM', 20, '', 'EASY', 4.4, 1017, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ekashila Gutta (Single Rock Hill & Watchtower)', 'ekashila-gutta-single-rock-hill-watchtower', 'Ekashila Gutta literally means ''Single Stone Hill'' (Eka-One, Shila-Stone, Gutta-Hill) and is the massive monolithic rock on which the ancient city of Orugallu (the historical name for Warangal) was founded by the Kakatiya dynasty. The city and its fort derived their name from this prominent geologic al feature.', 'Heritage & Spiritual', 'Telangana', 'Warangal District', 'Khila Warangal', '06:00 AM', '05:30 PM', 0, '', 'EASY', 4.5, 263, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Pakhal Lake & Wildlife Sanctuary', 'pakhal-lake-wildlife-sanctuary', 'Pakhal lake It was established in the year 1952 and is located around 50 km away from the town of Warangal, in the state of Telangana.Pakhal Wildlife Sanctuary is named after the person who excavated the lake, Ganapati Deva, the Kakatiyan ruler. The lake was constructed in the first decade of the 13th century (1213 AD).', 'Lakes, Dams & Waterways', 'Telangana', 'Warangal District', 'Khanapur / Narsampet', '06:00 AM', '06:00 PM', 30, '/images/candidates/warangal/2020030573.jpg', 'EASY', 4.8, 16, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Svayambhu Shiva Temple Excavation Complex', 'svayambhu-shiva-temple-excavation-complex', 'Shrine''s History Built under the Kakatiyan dynasty the temple is dedicated to Lord Shiva. The Shiva Linga which still exists is of special significance as it is believed to have emerged out of the earth on its own. Hence it has been named the Swayambhu Shambu Lingeshwara Swamy temple. Swayambhu literally means to be self-incarnated.', 'Heritage & Spiritual', 'Telangana', 'Warangal District', 'Khila Warangal', '09:00 AM', '06:00 PM', 20, '', 'EASY', 4.8, 6, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ursu Gutta & Sri Venkateswara Swamy Temple', 'ursu-gutta-sri-venkateswara-swamy-temple', 'Hindu temple was the pivot round which the life in India in the past-revolved. Of all the constructional activities of the early medieval society in India, temple building was the foremost. The money, the energy, the skill and the art of the land were exhibited in this singular religious activity.', 'Heritage & Spiritual', 'Telangana', 'Warangal District', 'Warangal', '06:00 AM', '08:00 PM', 0, '', 'EASY', 4.6, 65, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kothwalguda Kakatiya Stepwell (Bavi)', 'kothwalguda-kakatiya-stepwell-bavi', 'The Kakatiya dynasty (IAST: Kākatīya) [a] was a Telugu dynasty that ruled most of eastern Deccan region in present-day India between 12th and 14th centuries. Their territory comprised much of the present day Telangana and Andhra Pradesh, parts of eastern Karnataka, northern Tamil Nadu, and southern Odisha. Their capital was Orugallu, now known as Warangal.', 'Scenic & Cultural', 'Telangana', 'Warangal District', 'Khila Warangal', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.2, 416, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Narsampet Weavers'' Cluster & Rayaparthy Village', 'narsampet-weavers-cluster-rayaparthy-village', 'Historical rural mandal in Warangal district featuring ancient Kakatiya-era stone temples, traditional village stepwells, and rich agrarian handloom culture.', 'Heritage & Spiritual', 'Telangana', 'Warangal District', 'Narsampet / Rayaparthy', '09:30 AM', '06:30 PM', 0, '', 'EASY', 4.5, 2500, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Rangashaipet Kakatiya Stepwell & Heritage Bavi', 'rangashaipet-kakatiya-stepwell-heritage-bavi', 'Historical Significance and Purpose: The Kakatiyan Stepped Well, also known as Anthasthula Bavi or Metla Bavi, is an 800-year-old three-storied architectural marvel built by the Kakatiya dynasty, known for its ingenious water conservation systems.', 'Scenic & Cultural', 'Telangana', 'Warangal District', 'Warangal', '08:00 AM', '05:30 PM', 0, '', 'EASY', 4.2, 416, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Inavolu North Gateway & Oggu Katha Cultural Arena', 'inavolu-north-gateway-oggu-katha-cultural-arena', 'The singers (oggu katha artists) and devotees visit the pilgrimage place Komaravelli Mallanna Temple every year which is located on a hill called Indrakeeladri in Komuravelli village, located in Warangal District, of Telangana state, India.', 'Heritage & Spiritual', 'Telangana', 'Warangal District', 'Wardhannapet', '07:00 AM', '07:00 PM', 0, '', 'EASY', 4.7, 4333, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ramappa Temple (Sri Rudreshwara Swamy — UNESCO World Heritage Site)', 'ramappa-temple-sri-rudreshwara-swamy-unesco-world-heritage-site', 'Kakatiya Rudreshwara (Ramappa) Temple, Telangana Rudreshwara, popularly known as Ramappa Temple, is located in the village of Palampet approximately 200km north-east of Hyderabad, in the State of Telangana. It is the main Shiva temple in a walled complex built during the Kakatiyan period (1123-1323 CE) under rulers Rudradeva and Recharla Rudra.', 'Heritage & Spiritual', 'Telangana', 'Mulugu District', 'Venkatapur (Palampet)', '06:00 AM', '06:00 PM', 25, '', 'EASY', 4.7, 11784, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Laknavaram Lake & Suspension Bridges', 'laknavaram-lake-suspension-bridges', 'Laknavaram Lake is a lake in Govindaraopet mandal in Mulugu district. It is 17 kilometres (11 mi) from Mulugu and 80 kilometres (50 mi) from Warangal, Telangana.', 'Waterfalls & Gorges', 'Telangana', 'Mulugu District', 'Govindaraopet', '08:00 AM', '06:00 PM', 20, '/images/telangana/laknavaram_lake.jpg', 'EASY', 4.5, 2773, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Medaram Sammakka Sarakka Gadde', 'medaram-sammakka-sarakka-gadde', 'The district is often called the "Tribal Capital of Telangana" due to its significant tribal population and the world-famous Medaram Jathara, a tribal festival dedicated to the goddesses Sammakka and Saralamma. The region has been proposed to be officially renamed as Sammakka-Saralamma district.', 'Heritage & Spiritual', 'Telangana', 'Mulugu District', 'Tadvai (Sammakka Saralamma)', '06:00 AM', '07:00 PM', 0, '', 'EASY', 4.7, 12018, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Bogatha Waterfalls (Cheekupally)', 'bogatha-waterfalls-cheekupally', 'Bogatha Waterfall is a waterfall located on the Cheekupally stream, Wazeedu Mandal, Mulugu district, Telangana. It is located 120 kilometers (75 mi) from Bhadrachalam, 90 kilometers (56 mi) from Mulugu and 140 kilometers (87 mi) from Warangal.', 'Waterfalls & Gorges', 'Telangana', 'Mulugu District', 'Wazeed', '09:00 AM', '05:00 PM', 30, '', 'EASY', 4.3, 10459, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ramappa Lake & Irrigation Headworks', 'ramappa-lake-irrigation-headworks', 'Ramappa Lake is a lake situated in Palampeta village, Venkatapur mandal, Mulugu district, Telangana, India. The lake is one of the prominent reservoirs built by Kakatiya rulers.', 'Lakes, Dams & Waterways', 'Telangana', 'Mulugu District', 'Venkatapur (Palampet)', '06:00 AM', '06:00 PM', 0, '', 'EASY', 4.5, 653, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Tadvai Forest Huts & Eturnagaram Wildlife Sanctuary', 'tadvai-forest-huts-eturnagaram-wildlife-sanctuary', 'Eturnagaram Wildlife Sanctuary is a wildlife sanctuary located in Eturnagaram village in Mulugu district in Telangana, India. It is located 100 km (62 mi) from Warangal and 250 km (160 mi) from Hyderabad.', 'Nature & Wildlife', 'Telangana', 'Mulugu District', 'Tadvai / Eturnagaram', '06:00 AM', '05:30 PM', 30, '/images/telangana/eturnagaram.jpg', 'EASY', 4.6, 67, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Mallur Sri Hemachala Lakshmi Narasimha Swamy', 'mallur-sri-hemachala-lakshmi-narasimha-swamy', 'Sri Hemachala Lakshmi Narasimha Swamy Devalayam in Mallur, Telangana, is an ancient and sacred Narasimha temple located amidst the dense forests of Mulugu district. Believed to be thousands of years old, the temple is famous for its Swayambhu idol of Lord Lakshmi Narasimha Swamy and the mysterious sandalwood-scented fluid believed to emerge from the deity''s navel.', 'Waterfalls & Gorges', 'Telangana', 'Mulugu District', 'Mangapet', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.7, 2117, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kongala Waterfalls', 'kongala-waterfalls', 'Kongala Waterfalls, locally known as Puli Madugu Jalapatham, is a pristine waterfall hidden in the dense forests of Kongala Village, Wazeedu Mandal, Mulugu District, Telangana. The waterfall is nicknamed the ''V‑fall'' because of its distinct V‑shaped formation.', 'Waterfalls & Gorges', 'Telangana', 'Mulugu District', 'Wazeed', '08:00 AM', '04:30 PM', 0, '', 'EASY', 4.5, 775, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Jampanna Vagu Holy Bathing Ghats & Sammakka Sacred Ford', 'jampanna-vagu-holy-bathing-ghats-sammakka-sacred-ford', 'Guide to the sacred bathing ritual in Jampanna Vagu at Medaram. Legend, significance, best timing (Day 3), ghat locations, safety tips for Sammakka Jatara.', 'Nature & Wildlife', 'Telangana', 'Mulugu District', 'Tadvai (Sammakka Saralamma)', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.5, 89, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kongala Valley Sandstone Natural Arch & Gorges', 'kongala-valley-sandstone-natural-arch-gorges', 'Name Origin & History: Mulugu district, also known as Sammakka Saralamma Mulugu district, is located in the eastern part of Telangana. The district was formed on 17 February 2019 by bifurcating the Jayashankar Bhupalpally district, which itself was previously part of Warangal district.', 'Waterfalls & Gorges', 'Telangana', 'Mulugu District', 'Wazeed', '08:00 AM', '04:30 PM', 0, '', 'MODERATE', 4.5, 775, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kaleshwaram Temple (Sri Kaleshwara Mukteshwara Swamy)', 'kaleshwaram-temple-sri-kaleshwara-mukteshwara-swamy', 'It is the site of a temple of the Hindu god Shiva. The temple is significant because of the two Shiva Lingas that are found on a single pedestal. These Linga are named Lord Shiva and Lord Yama. Collectively, they known as Kaleshwara Mukteeshwara Swamy. Kaleshwaram is one of three Shiva temples mentioned in Trilinga Desham, or "Land of Three Lingas."', 'Heritage & Spiritual', 'Telangana', 'Jayashankar Bhupalpally District', 'Mahadevpur', '04:00 AM', '09:00 PM', 0, '', 'EASY', 4.6, 3932, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kaleshwaram Lift Irrigation Project & Medigadda Barrage', 'kaleshwaram-lift-irrigation-project-medigadda-barrage', 'The Kaleshwaram Lift Irrigation Project (KLIP) is a multi-purpose irrigation project on the Godavari River in Kaleshwaram, Bhupalpally, Telangana, India. Currently the world''s largest multi-stage lift irrigation project, its farthest upstream influence is at the confluence of the Pranahita and Godavari rivers.', 'Lakes, Dams & Waterways', 'Telangana', 'Jayashankar Bhupalpally District', 'Mahadevpur', '09:00 AM', '05:00 PM', 0, '/images/telangana/kaleshwaram.jpg', 'EASY', 4.5, 2500, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Pandavula Gutta / Pandavula Guhalu (Prehistoric Rock Art)', 'pandavula-gutta-pandavula-guhalu-prehistoric-rock-art', 'Pandavula Gutta (also Pandavula Guttalu or Pandavula Guhalu) is an ancient geological site and cave located near Kothapally village in Regonda mandal of Jayashankar Bhupalpally district in the Indian state of Telangana. It was designated as the only geoheritage site of Telangana.', 'Nature & Wildlife', 'Telangana', 'Jayashankar Bhupalpally District', 'Regonda', '08:00 AM', '05:30 PM', 0, '', 'EASY', 4.4, 841, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kota Gullu (Ghanpur Group of Kakatiya Temples)', 'kota-gullu-ghanpur-group-of-kakatiya-temples', 'Ghanpur temples, popularly known as Kota Gullu, are a group of 12th-century stone temples that are located in Ghanpur near Warangal in Telangana, India. They are located 9 km northwest of the more famous Ramappa Temple in Palampet.', 'Heritage & Spiritual', 'Telangana', 'Jayashankar Bhupalpally District', 'Ghanpur (Mulug)', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.6, 585, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kotilingala (Ancient Satavahana Capital & Confluence)', 'kotilingala-ancient-satavahana-capital-confluence', 'Kotilingala is a Hindu pilgrimage site in Jagtial district of the Indian state of Telangana. It is situated in Velagatoor mandal of the district, on the Godavari River. It is located on the bank of the Godavari River, and has a traditional Shiva temple for Hindus, the Koteshwara Siddeshwara Temple.', 'Heritage & Spiritual', 'Telangana', 'Jayashankar Bhupalpally District', 'Velgatoor / bordering Bhupalpally & Jagtial', '06:00 AM', '06:30 PM', 0, '', 'EASY', 4.3, 442, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Nainpaka Sri Venkateswara Swamy Rock Temple', 'nainpaka-sri-venkateswara-swamy-rock-temple', 'Nainpaka temple, The temple that is believed to have built in the 15th or 16th century on a pink stone rock around 25 km to Jayashankar Bhupalpally, unique in style and touted as the one and only in southern India is in a state of shambles.', 'Heritage & Spiritual', 'Telangana', 'Jayashankar Bhupalpally District', 'Regonda', '06:30 AM', '07:30 PM', 0, '', 'EASY', 4.7, 57, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Singareni Open Cast Coal Mine Viewpoint (Bhupalpally)', 'singareni-open-cast-coal-mine-viewpoint-bhupalpally', 'IN RESPECT OF THE KAKATIYA KHANI OPENCAST - 2 PROJECT NEAR BHOOPALPALLI VILLAGE & MANDAL JAYASHANKAR BHUPALPALLY DISTRICT TELANGANA STATE DEPARTMENT OF ENVIRONMENT (QCI / NABET Accredited EIA Consultant Organization)', 'Scenic & Cultural', 'Telangana', 'Jayashankar Bhupalpally District', 'Bhupalpally', '10:00 AM', '04:30 PM', 0, '', 'EASY', 4.5, 45, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Mothe Eco-Tourism Reservoir & Teak Groves', 'mothe-eco-tourism-reservoir-teak-groves', 'Name Origin & History: Jayashankar Bhupalpally district was formed on 11 October 2016 and named after Prof. Kothapalli Jayashankar, the legendary Telangana ideologue whose intellectual foundation shaped the Telangana movement. The district was carved out of the erstwhile Warangal district, with the annexation of some parts of Karimnagar and Khammam.', 'Lakes, Dams & Waterways', 'Telangana', 'Jayashankar Bhupalpally District', 'Maha Mutharam', '07:00 AM', '05:30 PM', 0, '', 'EASY', 4.3, 10459, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Palampet - Ghanpur Forest Wildlife Buffer', 'palampet-ghanpur-forest-wildlife-buffer', 'Jayashankar Bhupalpally is linked with the dynasties of Great "Vishnukundins" and even prior to it also of the Buddhist and pre-Buddhist periods of indian History.During Eighth Century A.D.', 'Heritage & Spiritual', 'Telangana', 'Jayashankar Bhupalpally District', 'Ghanpur (Mulug)', '07:00 AM', '05:30 PM', 0, '', 'MODERATE', 4.6, 67, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Koyagudem Coal Reserves & Forest Eco-Trail', 'koyagudem-coal-reserves-forest-eco-trail', 'The district formed on 11-10-2016 and named after Telangana ideologue, Prof. K. Jayashankar sir. Jayashankar Bhupalpally is linked with the dynasties of Great Vishnukundins and even prior to it also of the Buddhist and pre-Buddhist periods of indian History. Jayashankar Bhupalpally District is an area of 2293 Square Kilometers.', 'Heritage & Spiritual', 'Telangana', 'Jayashankar Bhupalpally District', 'Tekumatla', '08:00 AM', '05:00 PM', 0, '', 'MODERATE', 4.5, 38, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kolanupaka Jain Temple (Sri Shwethambar Jain Mandir)', 'kolanupaka-jain-temple-sri-shwethambar-jain-mandir', 'Kulpakji, also known as Kolanupaka Temple is a 2,000-year-old Śvetāmbara Jain temple in the village of Kolanupaka in Aler City, Yadadri Bhuvanagiri district, Telangana, India. The temple houses three deities: one each of Lord Rishabhanatha, Lord Neminatha, and Lord Mahavira.', 'Heritage & Spiritual', 'Telangana', 'Jangaon District', 'Alair / bordering Jangaon', '06:00 AM', '06:30 PM', 0, '', 'EASY', 4.6, 5000, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kolanupaka Archaeological Museum & Someshwara Temple', 'kolanupaka-archaeological-museum-someshwara-temple', 'Sri Someswara Temple, Kolanupaka (Kulpak) is a historic Shaiva temple complex located in Kolanupaka village, Alair Mandal, Yadadri Bhuvanagiri district, Telangana. Dedicated to Lord Shiva as Someswara and associated with Goddess Chandikamba, the complex is popularly known as Veyi Lingala Gudi (Temple of a Thousand Lingas) because of its celebrated Sahasralinga shrine.', 'Heritage & Spiritual', 'Telangana', 'Jangaon District', 'Alair / Jangaon border', '10:30 AM', '05:00 PM', 10, '', 'EASY', 4.6, 545, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Pembarthi Metal Crafts Village', 'pembarthi-metal-crafts-village', 'Pembarthi, a village in Telangana, India, is renowned for its metal craft, particularly linked to the Kakatiya dynasty''s patronage of artisans known as Vishwakarmas. The craft has evolved from temple adornments to secular items, adapting to changing political and economic contexts while facing challenges such as rising material costs and youth migration.', 'Heritage & Spiritual', 'Telangana', 'Jangaon District', 'Jangaon', '09:00 AM', '07:00 PM', 0, '', 'EASY', 4.7, 319, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Palakurthi Someshwara & Narasimha Temple', 'palakurthi-someshwara-narasimha-temple', 'Sri Someshwara Laxmi Narasimha Swamy Temple (also known as Palakurthi Someshwara Temple) is a historic sacred site situated atop the Someswara Gutta, a hillock at a height of about 120 metres in Palakurthi Mandal, Jangaon District, Telangana.', 'Heritage & Spiritual', 'Telangana', 'Jangaon District', 'Palakurthi', '06:00 AM', '08:00 PM', 0, '', 'EASY', 4.7, 641, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Bammera Village (Potana Memorial & Temple)', 'bammera-village-potana-memorial-temple', 'Bammera Pothana (1450-1510) was an Indian Telugu poet best known for his translation of the Bhagavata Purana from Sanskrit to Telugu. He was a Telugu and Sanskrit Scholar.His work, Andhra Maha Bhagavatamu, is popularly called as Pothana Bhagavatam in Telugu. Pothana was born into a Niyogi Brahmin family at Bammera Village, in the Jangaon District of present Telangana state.', 'Heritage & Spiritual', 'Telangana', 'Jangaon District', 'Palakurthi', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.5, 8, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Zaffergadh Fort & Mountain Pass', 'zaffergadh-fort-mountain-pass', 'Zaffergadh Fort is a historic fortified settlement located in Zaffergadh village and mandal, Jangaon district, Telangana. The area was historically associated with the name Velpugonda. Later accounts connect the name Zaffergadh with Zaffarudhaula, a ruler associated with the area in the 18th century.', 'Historical Forts & Monuments', 'Telangana', 'Jangaon District', 'Zaffergadh', '06:00 AM', '05:30 PM', 0, '', 'EASY', 4.4, 750, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Chilpur Balaji Temple (Sri Venkateswara Gutta)', 'chilpur-balaji-temple-sri-venkateswara-gutta', 'Chilpur Balaji Temple is a popular hilltop pilgrimage shrine dedicated to Lord Venkateswara, situated atop a granite hillock near Chinapendyal in Jangaon district offering panoramic countryside views.', 'Heritage & Spiritual', 'Telangana', 'Jangaon District', 'Chilpur', '06:00 AM', '08:00 PM', 0, '', 'EASY', 4.8, 112, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Jeedikal Sri Rama Temple', 'jeedikal-sri-rama-temple', 'Jeedikal Sri Ramachandra Swamy Temple, also known as Sri Veerachala Ramachandra Swamy Devasthanam, is a Hindu shrine dedicated to Lord Sri Rama, located in Jeedikal village, Lingala Ghanpur Mandal, Jangaon District, Telangana. It is situated approximately 15-25 km from Jangaon, depending on the route, and roughly 100-110 km from Hyderabad.', 'Heritage & Spiritual', 'Telangana', 'Jangaon District', 'Lingalaghanpur', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.7, 382, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ghanpur (Station) Historic Stepwell & Railway Heritage', 'ghanpur-station-historic-stepwell-railway-heritage', 'Ghanpur is a Census town in Jangaon district of the Indian state of Telangana. It is located in Ghanpur mandal.', 'Scenic & Cultural', 'Telangana', 'Jangaon District', 'Ghanpur (Station)', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.2, 177, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kodakandla Rural Stone Weavers & Crafts Cluster', 'kodakandla-rural-stone-weavers-crafts-cluster', 'Kodakandla is a village and a mandal in Jangaon district in the state of Telangana in India. It was formerly part of Warangal district before the division of that entity.', 'Artisans & Culture', 'Telangana', 'Jangaon District', 'Kodakandla', '09:00 AM', '06:00 PM', 0, '', 'EASY', 4.5, 2500, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kuravi Veerabhadra Swamy Temple', 'kuravi-veerabhadra-swamy-temple', 'Historic Sri Veerabhadra Swamy temple is in the Kuravi mandal of the Mahabubabad district in Telangana State, India. This temple is dedicated to Lord Veerabhadra swamy,who is fierce looking Diety with three eyes and ten hands.', 'Heritage & Spiritual', 'Telangana', 'Mahabubabad District', 'Kuravi', '05:30 AM', '08:30 PM', 0, '', 'EASY', 4.7, 361, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Bayyaram Cheruvu & Kakatiya Inscription Stone', 'bayyaram-cheruvu-kakatiya-inscription-stone', 'A potential tourists'' paradise - Bayyaram Tank - built by Kakatiyas in 13th Century A.D., needs a push from Government.', 'Lakes, Dams & Waterways', 'Telangana', 'Mahabubabad District', 'Bayyaram', '06:00 AM', '06:00 PM', 0, '', 'EASY', 4.7, 12, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Dornakal Cathedral (Epiphany Cathedral)', 'dornakal-cathedral-epiphany-cathedral', '🌟 Cathedral Church of the Epiphany of Our Lord, popularly known as Dornakal Church, is a historic Anglican cathedral located in Dornakal town, Mahabubabad district, Telangana (earstwhile Warangal district).', 'Heritage & Spiritual', 'Telangana', 'Mahabubabad District', 'Dornakal', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.8, 30, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Bheemuni Paadam Waterfalls (Seethanagaram)', 'bheemuni-paadam-waterfalls-seethanagaram', 'Bheemuni Paadam Waterfalls is situated in Seethanagaram Village, GUDUR Mandal, Mahabubabad in Telangana State, INDIA.', 'Waterfalls & Gorges', 'Telangana', 'Mahabubabad District', 'Gudur / Gangaram', '07:00 AM', '05:30 PM', 30, '', 'EASY', 4.3, 2450, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Edulla Cheruvu & Mahabubabad Hillocks', 'edulla-cheruvu-mahabubabad-hillocks', 'Sprawling historical water body and surrounding rocky hillocks on the outskirts of Mahabubabad town, popular for evening walks and serene sunset views.', 'Lakes, Dams & Waterways', 'Telangana', 'Mahabubabad District', 'Mahabubabad', '06:00 AM', '06:30 PM', 0, '', 'EASY', 4.4, 48, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Gudur Forest Corridor & Tribal Belts', 'gudur-forest-corridor-tribal-belts', 'Dense forest reserve and scenic rural transit belt in Mahabubabad district, characterized by rolling hills, tribal culture, and seasonal forest streams.', 'Nature & Wildlife', 'Telangana', 'Mahabubabad District', 'Gudur', '07:00 AM', '05:00 PM', 0, '', 'EASY', 4.5, 2, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kambalapally Lake & Dam', 'kambalapally-lake-dam', 'Lake Overview: Kambalapalli Lake, also known as Kesari Thatakam, is a significant local water body and a prominent tourist attraction known for its tranquil and scenic beauty. It plays a crucial role in local irrigation and ecology, drawing visitors for its peaceful weather and the soothing sounds o f its water.', 'Lakes, Dams & Waterways', 'Telangana', 'Mahabubabad District', 'Mahabubabad', '06:00 AM', '06:00 PM', 0, '', 'EASY', 4.6, 37, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Garla Iron Ore Hills & Historic Mines', 'garla-iron-ore-hills-historic-mines', 'The iron ore mines are spread over 5,342 hectares in Bayyaram, Garla and Nelakondapally mandals in Mahabubabad, Khammam and Gudur mandal in Warangal. The Indian Bureau of Mines had estimated the value of ore at Rs. 16 lakh crore.', 'Scenic & Cultural', 'Telangana', 'Mahabubabad District', 'Garla', '08:00 AM', '05:00 PM', 0, '', 'EASY', 4.1, 76, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Inugurthy Ancient Kakatiya Stone Fort & Lake', 'inugurthy-ancient-kakatiya-stone-fort-lake', 'The Kakatiya dynasty (IAST: Kākatīya) [a] was a Telugu dynasty that ruled most of eastern Deccan region in present-day India between 12th and 14th centuries. Their territory comprised much of the present day Telangana and Andhra Pradesh, parts of eastern Karnataka, northern Tamil Nadu, and southern Odisha. Their capital was Orugallu, now known as Warangal.', 'Historical Forts & Monuments', 'Telangana', 'Mahabubabad District', 'Inugurthy', '07:00 AM', '05:30 PM', 0, '', 'MODERATE', 4.4, 23219, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kothaguda Tribal Heritage & Chenchu Forest Settlement', 'kothaguda-tribal-heritage-chenchu-forest-settlement', 'Kothaguda is an agency mandal (5th scheduled area) in Mulugu Constituency of Mahabubabad district of the Indian state of Telangana. [failed verification]', 'Nature & Wildlife', 'Telangana', 'Mahabubabad District', 'Kothaguda', '08:00 AM', '05:00 PM', 0, '', 'EASY', 4.5, 24267, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Bhadrachalam Sri Sita Ramachandra Swamy Temple', 'bhadrachalam-sri-sita-ramachandra-swamy-temple', 'The Sri Sita Ramachandraswamy Temple is a Hindu Temple dedicated to Rama, a prominent avatar of the god Vishnu. It is located on the banks of the Godavari River in the town of Bhadrachalam in east Telangana, India. Often simply referred to as Bhadrachalam or Bhadragiri, Bhadradri, the temple is considered one of the Divya Kshetrams of Godavari and is also revered as Dakshina Ayodhya.', 'Heritage & Spiritual', 'Telangana', 'Bhadradri Kothagudem District', 'Bhadrachalam', '04:30 AM', '09:00 PM', 0, '/images/telangana/bhadrachalam.jpg', 'EASY', 4.7, 16164, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Parnasala (Hermitage of Lord Rama)', 'parnasala-hermitage-of-lord-rama', 'Godavari River at Parnasala Parnasala is a village in the Dummugudem mandal in Bhadradri Kothagudem district of Telangana, India. The village is accessible by road and boats and is situated 32 km from the temple town of Bhadrachalam. Bhadrachalam area has several Hindu deities connected with Epic book Ramayana.', 'Heritage & Spiritual', 'Telangana', 'Bhadradri Kothagudem District', 'Dummugudem', '06:00 AM', '06:30 PM', 0, '', 'EASY', 4.3, 2935, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kinnerasani Wildlife Sanctuary & Dam', 'kinnerasani-wildlife-sanctuary-dam', 'Kinnerasani Wildlife Sanctuary is a forest located in Bhadradri Kothagudem district, Telangana, India. The wildlife sanctuary is spread over an area of 635.40 km2 (157,010 acres) with the scenic Kinnerasani Lake with densely forested islands in the middle of the sanctuary.', 'Lakes, Dams & Waterways', 'Telangana', 'Bhadradri Kothagudem District', 'Palwancha', '09:00 AM', '05:30 PM', 30, '/images/candidates/khammam/kinnerasani-wildlife-sanctuary-khammam-telangana-1-attr-popular.jpg', 'EASY', 4.4, 201, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Papikondalu Godavari River Cruise Departure Ghat', 'papikondalu-godavari-river-cruise-departure-ghat', 'Book the best Papikondalu river cruise tour in East Godavari. Experience Bhadradri temple darshan, Maredumilli waterfalls adventure, and Rampachodavaram tribal culture tours with expert guides.', 'Waterfalls & Gorges', 'Telangana', 'Bhadradri Kothagudem District', 'Burgampahad / Bhadrachalam Ghats', '07:30 AM', '08:00 AM', 1, '', 'EASY', 4.5, 493, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Singareni Collieries Coal Mining Hub (Kothagudem & Yellandu)', 'singareni-collieries-coal-mining-hub-kothagudem-yellandu', 'The Hyderabad (Deccan) Company Limited incorporated in England acquired mining rights in 1886 to exploit coal found in Yellandu area. The present Company was incorporated on 23rd December 1920 under the Hyderabad Companies Act as a public limited company with the name ''The Singareni Collieries Company Limited'' (SCCL).', 'Scenic & Cultural', 'Telangana', 'Bhadradri Kothagudem District', 'Kothagudem / Yellandu', '10:00 AM', '04:00 PM', 0, '', 'EASY', 4.3, 12, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Gundala Hot Springs & Sri Rama Padalu', 'gundala-hot-springs-sri-rama-padalu', 'Gundala is a mandal of Bhadradri Kothagudem District of Telangana state in India. It is located at and is near the town of Kothagudem. The headquarters of the sub-division are in the village of Gundala. The sub-division has 17 villages under its administration. Markode, Muthapuram and Lingagudem are the other populated regions in the mandal.', 'Scenic & Cultural', 'Telangana', 'Bhadradri Kothagudem District', 'Gundala', '06:00 AM', '06:00 PM', 0, '', 'EASY', 4.5, 613, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Dummugudem Anicut & British Lock Gates', 'dummugudem-anicut-british-lock-gates', 'Dummugudem is a historic Godavari river settlement in Bhadradri Kothagudem district, Telangana. The area is associated with the historic Dummugudem anicut/barrage and with the wider irrigation and navigation works developed along the Godavari during the colonial period. Dummugudem is approximately 25-30 km from Bhadrachalam, depending on the particular location and road route.', 'Waterfalls & Gorges', 'Telangana', 'Bhadradri Kothagudem District', 'Dummugudem', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.7, 6, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Cherla & Taliperu Reservoir', 'cherla-taliperu-reservoir', 'Taliperu Project (Telugu: తాలిపేరు ప్రాజెక్ట్) also known as Taliperu Reservoir is a medium irrigation project constructed across the Taliperu River, a tributary of Godavari River, located at Cherla Village and Mandal, Khammam District, Telangana.', 'Lakes, Dams & Waterways', 'Telangana', 'Bhadradri Kothagudem District', 'Cherla', '08:00 AM', '05:30 PM', 0, '', 'EASY', 4.5, 2500, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kunavaram Sabari & Godavari River Sangam Viewpoint', 'kunavaram-sabari-godavari-river-sangam-viewpoint', 'Prehistoric man probably roamed the areas of the lower Godavari valley in the surroundings of Bhadrachalam, Kothagudem, Pinapaka and Paloncha taluks in the district. In a rare discovery, historians uncovered rock art believed to have originated in the Paleolithic age at Nallamudi in Jagannadhapuram of Bhadradri-Kothagudem district.', 'Scenic & Cultural', 'Telangana', 'Bhadradri Kothagudem District', 'Kunavaram border / Bhadrachalam East', '06:00 AM', '06:00 PM', 0, '', 'MODERATE', 4.7, 18, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Yanambailu Forest Ghat & Dandakaranya Tribal Trail', 'yanambailu-forest-ghat-dandakaranya-tribal-trail', 'Bhadradri Kothagudem district''s history is a remarkable journey from the Paleolithic era to the present day. The region has been continuously inhabited for thousands of years, as evidenced by the rock art at Nallamudi and Palwancha, and the massive megalithic burial complex at Janampet — one of the largest prehistoric burial sites in India.', 'Nature & Wildlife', 'Telangana', 'Bhadradri Kothagudem District', 'Pinapaka', '07:00 AM', '05:30 PM', 0, '', 'MODERATE', 3.9, 74, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Khammam Fort (Stambhadri Rock Citadel)', 'khammam-fort-stambhadri-rock-citadel', 'Khammam Fort is a hill fort with a history of over a thousand years. History says that it was built during the Kakatiya period. This place, mentioned as "Khammamettu" in ancient inscriptions, is a historical center that combines spirituality, strategic importance, and architectural beauty. The foundation stone for the construction of this fort was laid in 950 CE.', 'Historical Forts & Monuments', 'Telangana', 'Khammam District', 'Khammam (Urban)', '06:00 AM', '06:30 PM', 0, '', 'EASY', 4.2, 3581, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Stambhadri Lakshmi Narasimha Swamy Temple', 'sri-stambhadri-lakshmi-narasimha-swamy-temple', 'బయటి లంకెలు స్తంభం ఆకారంలో ఉన్న నరసింహ స్వామి క్షేత్రం | Sri Lakshmi Narasimha Temple,Stambhadri gutta,Khammam., retrieved 2022-07-06', 'Heritage & Spiritual', 'Telangana', 'Khammam District', 'Khammam (Urban)', '06:00 AM', '08:30 PM', 0, '', 'EASY', 4.8, 490, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Nelakondapalli Buddhist Mahastupa & Archaeological Site', 'nelakondapalli-buddhist-mahastupa-archaeological-site', 'Nelakondapally, also referred to as Nelakondapalli or Nela Kondapalli, is a town and headquarters of a mandal in Khammam district, Telangana, India.', 'Heritage & Spiritual', 'Telangana', 'Khammam District', 'Nelakondapalli', '09:00 AM', '05:30 PM', 15, '', 'EASY', 4.3, 485, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Nelakondapalli Bhakta Ramadasu Birthplace & Dhyana Mandir', 'nelakondapalli-bhakta-ramadasu-birthplace-dhyana-mandir', 'The Nelakondapalli village is the birthplace of Bhakta Ramadasa who helped established the major Rama temple in Bhadrachalam, where textual records refer to Nelankondapally as Bhugiri. This information plaque describes a Buddhist Stupa excavated by Archeological Survey of India.', 'Heritage & Spiritual', 'Telangana', 'Khammam District', 'Nelakondapalli', '06:30 AM', '07:30 PM', 0, '', 'EASY', 4.6, 58, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Palair Reservoir & Lake Eco-Park', 'palair-reservoir-lake-eco-park', 'Geography Palair Reservoir is located at the Palair village in Kusumanchi mandal of the district and is about 30 kilometers away from the district headquarters of Khammam. The lake is a balancing reservoir for the Lal Bahadur Canal, a left bank canal of the Nagarjuna Sagar project.', 'Lakes, Dams & Waterways', 'Telangana', 'Khammam District', 'Kusumanchi', '08:00 AM', '06:00 PM', 20, '', 'EASY', 4.4, 178, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kusumanchi Kakatiya Temples (Ganapeshwaralayam & Mukkanteshwaralayam)', 'kusumanchi-kakatiya-temples-ganapeshwaralayam-mukkanteshwaralayam', 'Kusumanchi, in Telangana''s Khammam district, is home to two iconic 11th-century Shiva temples—Sri Ganapeshwaralayam and Mukkanteshwaralayam—constructed during the Kakatiya dynasty.', 'Heritage & Spiritual', 'Telangana', 'Khammam District', 'Kusumanchi', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.8, 192, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Wyra Dam & Green Heritage Park', 'wyra-dam-green-heritage-park', 'Wyra Reservoir is a medium irrigation project constructed across the Wyra River, a tributary of Krishna River. The reservoir is located next to the Wyra town, Khammam District, Telangana.', 'Lakes, Dams & Waterways', 'Telangana', 'Khammam District', 'Wyra', '08:00 AM', '06:30 PM', 15, '', 'EASY', 4.4, 79, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Jamalapuram Sri Venkateswara Swamy Temple', 'jamalapuram-sri-venkateswara-swamy-temple', 'Sri Venkateshwara Swamy Temple is located in Jamalapuram, near to Errupalem in Khammam district of Telangana, India. The presiding deity in this temple is Lord Balaji and is said to be a swayambhu Lord, who self-manifested in this place.', 'Heritage & Spiritual', 'Telangana', 'Khammam District', 'Yerrupalem', '06:00 AM', '08:30 PM', 0, '/images/candidates/khammam/2024081739.jpg', 'EASY', 4.7, 3534, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kallur Sri Sanjeeva Anjaneya Swamy Temple & Koneru', 'kallur-sri-sanjeeva-anjaneya-swamy-temple-koneru', 'Sri Anjaneya Swamy Temple is located at Kallur, Kalluru Mandal in Kurnool District, Andhra Pradesh. This Temple is dedicated to Anjaneya Swamy.', 'Heritage & Spiritual', 'Telangana', 'Khammam District', 'Kallur', '06:00 AM', '08:00 PM', 0, '', 'EASY', 5, 1, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Thirumalayapalem Kakatiya Shiva Temple', 'thirumalayapalem-kakatiya-shiva-temple', 'Tirumalayapalem is a mandal in the Khammam district of Telangana, India, serving as an administrative subdivision that encompasses 25 villages across an area of 236.5 square kilometers. As per the 201', 'Heritage & Spiritual', 'Telangana', 'Khammam District', 'Tirumalayapalem', '06:30 AM', '07:30 PM', 0, '', 'EASY', 5, 3, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kuntala Waterfalls (Highest Waterfall in Telangana)', 'kuntala-waterfalls-highest-waterfall-in-telangana', 'Kuntala Waterfall is a waterfall of Telangana state in India, located on Kadam river in Neradigonda mandal of Adilabad district. It is the highest waterfall in the state with a height of 150 feet.', 'Waterfalls & Gorges', 'Telangana', 'Adilabad District', 'Neradigonda', '08:30 AM', '04:30 PM', 30, '', 'EASY', 4.3, 6616, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Pochera Waterfalls & Deep Rock Canyon', 'pochera-waterfalls-deep-rock-canyon', 'Pochera Waterfalls: A Scenic Gem in Adilabad, Telangana Located in the verdant landscape of Adilabad in Telangana, India, the Pochera Waterfalls has been a striking destination for nature lovers and adventure seekers for many years.', 'Waterfalls & Gorges', 'Telangana', 'Adilabad District', 'Bazarhathnoor', '08:30 AM', '05:00 PM', 20, '/images/candidates/adilabad/2018052528.jpg', 'EASY', 4.3, 2731, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Jainath Sri Lakshmi Narayana Swamy Temple', 'jainath-sri-lakshmi-narayana-swamy-temple', 'Sri Narayan Swamy Temple, also known as Jainath Temple - an ancient temple at Jainath village, Adilabad district, Telangana. Government tourism sources associate the temple with Pallava chiefs and describe its architecture as reflecting Jain-style influences. The principal deity is Lord Lakshmi Narayana, represented by a 6-foot-tall standing black-stone idol.', 'Heritage & Spiritual', 'Telangana', 'Adilabad District', 'Jainath', '06:00 AM', '08:00 PM', 0, '/images/candidates/adilabad/2018052594.jpg', 'EASY', 4.7, 209, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Mavala Eco-Park & Lake Promenade', 'mavala-eco-park-lake-promenade', 'Mavala Lake & Park in Adilabad, Telangana, India, is a carefully preserved ecological and cultural site, characterized by its diverse flora and fauna, and its significance in local spirituality and heritage. The site encompasses a unique blend of natural beauty and historical narratives, making it a vital point of interest for researchers and cultural enthusiasts alike.', 'Lakes, Dams & Waterways', 'Telangana', 'Adilabad District', 'Mavala', '09:00 AM', '06:30 PM', 20, '', 'EASY', 4, 604, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Penganga River & Chanakha-Korata Barrage', 'penganga-river-chanakha-korata-barrage', 'The barrage is 23 gates is located in Penganga at Chanaka village in Jainath mandal and Korata in Maharashtra. The barrage will irrigate 13,500 acres (5,500 ha) and 51,000 houses in 81 villages in Adilabad district. The construction of the barrage, pump house, pipelines are built onsite, and canals were taken up simultaneously, working day and night shifts.', 'Lakes, Dams & Waterways', 'Telangana', 'Adilabad District', 'Tamsi / Bela border', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.3, 6, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kawal Tiger Reserve Buffer Zone & Utnoor Teak Forests', 'kawal-tiger-reserve-buffer-zone-utnoor-teak-forests', 'Kawal Wildlife Sanctuary is a wildlife sanctuary in Jannaram mandal of Mancherial District in the Telangana state of India. The Government of India declared it as a tiger reserve in 2012.', 'Nature & Wildlife', 'Telangana', 'Adilabad District', 'Utnoor', '06:00 AM', '05:30 PM', 30, '', 'EASY', 4.3, 2254, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Indervelli Martyr''s Memorial & Gond Culture Center', 'indervelli-martyr-s-memorial-gond-culture-center', 'The Indervelli Memorial stands in memory of local tribal farmers and marks an important landmark in the socio-cultural history of the Gond community in Adilabad, featuring cultural exhibitions of tribal art and musical traditions.', 'Nature & Wildlife', 'Telangana', 'Adilabad District', 'Indervelli', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.1, 21, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Satnala Dam & Forest Reservoir', 'satnala-dam-forest-reservoir', 'The Sathnala Dam, situated in Adilabad, Telangana, serves as a critical water conservation and irrigation structure, enhancing agricultural productivity in the region. Constructed with local materials and engineering techniques, this dam exemplifies sustainable infrastructure development while supporting biodiversity in its surrounding ecosystems.', 'Lakes, Dams & Waterways', 'Telangana', 'Adilabad District', 'Jainath', '07:00 AM', '06:00 PM', 0, '', 'EASY', 3.5, 24, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Bheemaram Rock Formations & Natural Stream Pools', 'bheemaram-rock-formations-natural-stream-pools', 'Relationships and Distribution Lower contact The Bheemaram Formation conformably overlies or an interfingering relationship with the Yerrapalli Fm.', 'Scenic & Cultural', 'Telangana', 'Adilabad District', 'Ichoda', '07:00 AM', '05:30 PM', 0, '', 'MODERATE', 4.3, 2731, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Talamadugu Border Forests & Penganga Viewpoint', 'talamadugu-border-forests-penganga-viewpoint', 'Talamadugu is a village located in Adilabad district in the state of Telangana in India. Talamadugu railway station is located on Adilabad line.', 'Scenic & Cultural', 'Telangana', 'Adilabad District', 'Talamadugu', '07:00 AM', '06:00 PM', 0, '', 'MODERATE', 4.3, 6616, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Basar Sri Gnana Saraswathi Temple', 'basar-sri-gnana-saraswathi-temple', 'Gnana Saraswati Temple (Telugu: శ్రీ జ్ఞాన సరస్వతి దేవస్థానము) is a Hindu temple of Goddess Saraswati located on the banks of Godavari River at Basara, Telangana, India. It is one of the two famous Saraswati temples in the Indian subcontinent, the other being Sharada Peeth.', 'Heritage & Spiritual', 'Telangana', 'Nirmal District', 'Basar', '04:00 AM', '09:30 PM', 0, '', 'EASY', 4.6, 22616, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Nirmal Toys & Paintings Artisan Village', 'nirmal-toys-paintings-artisan-village', 'Nirmal district in Telangana was once famous as a production centre of as diverse things as cannons and toys. While the foundry supplied heavy artillery to the army of the Nizam of Hyderabad, the Naqqash craftsmen and artists brought out exquisite wooden toys and duco paintings under the name of Nirmal Art.', 'Artisans & Culture', 'Telangana', 'Nirmal District', 'Nirmal Urban', '09:30 AM', '08:00 PM', 0, '', 'EASY', 4.4, 495, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kadam Dam & Reservoir (Sri Rama Sagar Balancing Project)', 'kadam-dam-reservoir-sri-rama-sagar-balancing-project', 'The Kadem Project is a reservoir on the river Kadem, a tributary river of Godavari near Kademm Mandal, Nirmal District, Telangana. This project covers localised ayacut under Nirmal and Mancherial Districts. The Project has been integrated with Sriram Sagar Project.', 'Lakes, Dams & Waterways', 'Telangana', 'Nirmal District', 'Kadam (Peddur)', '07:00 AM', '06:00 PM', 20, '', 'EASY', 4.5, 756, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Nirmal Fort (Shamgarh & Battisgarh Fortresses)', 'nirmal-fort-shamgarh-battisgarh-fortresses', 'The historic twin-fort complex of Shamgarh and Battisgarh in Nirmal, engineered by French General Raymond and Nizam commanders in the 18th century, commanding the Godavari basin, famous for its 400-year toy craft heritage.', 'Historical Forts & Monuments', 'Telangana', 'Nirmal District', 'Nirmal Urban', '06:00 AM', '06:00 PM', 0, '', 'EASY', 4, 382, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Badankurthi Island & Sri Venkateswara Swamy Temple', 'badankurthi-island-sri-venkateswara-swamy-temple', ': settled in this island in the middle of the Badhan kurthi is an island village in the Godavari river. It is sais that, the 120-year-old district of Nirmal. It is situated in the middle of the sage Bavari learned a greatness of Godavari River. The island village is 41km.from the Buddha who was 40 years younger to him in district headquarters of Nirmal, and 3km.', 'Heritage & Spiritual', 'Telangana', 'Nirmal District', 'Khanapur', '07:00 AM', '05:30 PM', 0, '', 'EASY', 4.6, 12796, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Soan Godavari Bridge & Riverside Promenade', 'soan-godavari-bridge-riverside-promenade', 'The Soan Godavari Bridge is a historic stone masonry road bridge constructed in the 1930s across the Godavari River near Nirmal, offering sweeping river viewpoints and a peaceful waterside promenade.', 'Scenic & Cultural', 'Telangana', 'Nirmal District', 'Nirmal Rural (Soan)', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.3, 12, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Chincholi Eco-Tourism Park & Forest Lake', 'chincholi-eco-tourism-park-forest-lake', 'Why South India waited until 2011 to protect a dry forest, what lives in the 134.88 sq km at Chincholi, and how to actually get inside it.', 'Lakes, Dams & Waterways', 'Telangana', 'Nirmal District', 'Sarangapur', '09:00 AM', '05:30 PM', 20, '', 'EASY', 4.3, 115, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Lakshmi Narasimha Swamy Temple, Koratikal', 'sri-lakshmi-narasimha-swamy-temple-koratikal', 'KORATIKALLU Brief History Of The Kshethra (Sthala Mahime) Basically this is a temple for Lakshmi Narayana Swamy. People of neighboring village had brought Lakshmi Narasimha Swamy idols to this temple as they were unable to do pooja there. From then, Lakshmi Narasimha Swamy is worshiped as utsava murthy. Moolavar And Goddess Name: Moola murthy: Sri Lakshmi Narayana Swamy.', 'Heritage & Spiritual', 'Telangana', 'Nirmal District', 'Mamda', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.5, 2, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sarangapur Sri Venkateswara Swamy Temple & Gutta', 'sarangapur-sri-venkateswara-swamy-temple-gutta', 'Sarangapur (సారంగపూర్) village located in Kaddam Peddur mandal, Nirmal district. The Pinocde of Sarangapur village is 504202 Check population, census data, map, nearby villages and full details.', 'Heritage & Spiritual', 'Telangana', 'Nirmal District', 'Sarangapur', '06:00 AM', '08:00 PM', 0, '', 'MODERATE', 4.7, 1415, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Dilawarpur & Mudhole Rural Crafts Belt', 'dilawarpur-mudhole-rural-crafts-belt', 'Dilawarpur is a village, a Gram Panchayat, and the administrative headquarters of the Dilawarpur mandal in the Nirmal district of the Indian state of Telangana. Located approximately 14 kilometres (8.7 mi) northwest of the district headquarters at Nirmal, the village serves as a major agricultural and rural administrative center for northern Telangana.', 'Artisans & Culture', 'Telangana', 'Nirmal District', 'Dilawarpur', '09:00 AM', '06:00 PM', 0, '', 'EASY', 4.5, 2500, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Jodeghat Kumuram Bheem Martyr''s Memorial & Tribal Museum', 'jodeghat-kumuram-bheem-martyr-s-memorial-tribal-museum', 'The museum stands out as one of the most historically significant locations in terms of Asifabad''s tribal culture and Heritage. On September 1, 1940, Adivasi fighter Kumuram Bheem and his companions were martyred at Jodeghat, and the location developed a reputation for bravery and courage.', 'Heritage & Spiritual', 'Telangana', 'Kumuram Bheem Asifabad District', 'Kerameri / Jodeghat', '09:00 AM', '05:30 PM', 20, '', 'EASY', 4.2, 63, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kerameri Ghats & Panoramic Deccan Viewpoint', 'kerameri-ghats-panoramic-deccan-viewpoint', 'The Utnoor-Asifabad route, 6 km long Kerameri ghat road near Kerameri mandal of which the Kerameri ghats are a part, is one of the oldest in the district passing through its tribal heartland. The Kerameri hills, as seen from the popular Kerameri ghat road, Offer a panoramic view as the landscape is changing colours layer by layer.', 'Scenic & Cultural', 'Telangana', 'Kumuram Bheem Asifabad District', 'Kerameri', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.2, 63, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sirpur Fort & Historical Gond Dynasty Capital', 'sirpur-fort-historical-gond-dynasty-capital', 'Kumuram Bheem Asifabad District carries a layered history: from the Kakatiya grant associated with 1199 CE and the Gond traditions of Sirpur, through the Sirpur-Chanda Gond dynasty, the Bhonsles, Mughals and Asaf Jahis, to the making of Adilabad district and the 2016 creation of Kumuram Bheem Asifabad District.', 'Historical Forts & Monuments', 'Telangana', 'Kumuram Bheem Asifabad District', 'Sirpur (T)', '07:00 AM', '05:30 PM', 0, '', 'EASY', 4.7, 7, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Mitta Waterfalls (Gundala / Chitrakot of Asifabad)', 'mitta-waterfalls-gundala-chitrakot-of-asifabad', 'The waterfall, which is 100 km away from Asifabad, is located between tall hills on one side and dense forests on the other, the Saptagundala waterfalls also known as Mitta waterfalls is tucked far away from civilisation.There are no proper roads to reach the nature''s beauty.', 'Waterfalls & Gorges', 'Telangana', 'Kumuram Bheem Asifabad District', 'Tiryani', '08:00 AM', '04:30 PM', 20, '', 'EASY', 4.6, 482, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Shivaram Wildlife Sanctuary & Marsh Crocodile Pools', 'shivaram-wildlife-sanctuary-marsh-crocodile-pools', 'Shivaram Wildlife Sanctuary is a wildlife preserve in India located in Mancherial district of Telangana and is located 10 km from Manthani, 40 km from Peddapalli, 80 km from Karimnagar and 30 km from Godavarikhani. This riverine forest mixed with teak and terminalia is spread over 36.29 square kilometres (14.01 sq mi) and is home to marsh crocodiles from the river Godavari.', 'Nature & Wildlife', 'Telangana', 'Kumuram Bheem Asifabad District', 'Manthani / bordering Asifabad & Mancherial', '07:00 AM', '05:00 PM', 30, '', 'EASY', 4.2, 317, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Komaram Bheem Project & Reservoir (Ada Dam)', 'komaram-bheem-project-reservoir-ada-dam', 'The Sri Komaram Bheem Project (Telugu: కొమరం భీం ప్రాజెక్ట్) is a Medium Reservoir that has been built across Peddavagu River, a tributary of the Pranahita River. It is located at Ada village, Asifabad Mandal, Komaram Bheem district, Telangana.', 'Lakes, Dams & Waterways', 'Telangana', 'Kumuram Bheem Asifabad District', 'Asifabad', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.2, 41, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Babajhari Waterfalls & Sacred Gond Natural Spring', 'babajhari-waterfalls-sacred-gond-natural-spring', 'Babejhari Valley is a forested valley in the Kerameri Ghats of Kumuram Bheem Asifabad district, Telangana. The valley and the surrounding Babejhari-Jodeghat landscape are associated with the Gond tribal heritage of the region and the history of Komaram Bheem.', 'Waterfalls & Gorges', 'Telangana', 'Kumuram Bheem Asifabad District', 'Kerameri', '08:00 AM', '05:00 PM', 0, '', 'EASY', 4.4, 65, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Gangapur Archaeological Temple & Chalukyan Inscriptions', 'gangapur-archaeological-temple-chalukyan-inscriptions', 'The ancient Sri Balaji Venkateshwara Swamy Devasthanam of Gangapur village in Rebbana mandal is being spruced up for the three-day-long annual Jathara in every year. 13th century temple The Balaji temple is one of the major pilgrim centres of this district and it is believed to have been built on the scenic shores of a rivulet and on outskirts of Gangapur in the 13th century.', 'Heritage & Spiritual', 'Telangana', 'Kumuram Bheem Asifabad District', 'Rebbena', '07:00 AM', '05:30 PM', 0, '', 'EASY', 4.6, 181, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Penchikalpet Pranahita Riverbank & Vulture Conservation Zone', 'penchikalpet-pranahita-riverbank-vulture-conservation-zone', 'Palarapu Guttalu Vulture Reserve (also spelled Palarapugutta or Palarapu Cliff) is a vulture conservation site in Kumuram Bheem Asifabad district, Telangana. It is located near Nandigaon village in Penchikalpet mandal, at the confluence of the Peddavagu stream and the Pranahita River.', 'Scenic & Cultural', 'Telangana', 'Kumuram Bheem Asifabad District', 'Penchikalpet', '06:30 AM', '05:00 PM', 0, '', 'EASY', 4.1, 25, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Wankidi Forest Pass & Historic Border Checkposts', 'wankidi-forest-pass-historic-border-checkposts', 'Dense deciduous forest pass and winding scenic transit corridor through the northern hills of Kumuram Bheem Asifabad district near the Maharashtra border.', 'Nature & Wildlife', 'Telangana', 'Kumuram Bheem Asifabad District', 'Wankidi', '08:00 AM', '06:00 PM', 0, '', 'MODERATE', 4.4, 65, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Gudem Gutta Sri Satyanarayana Swamy Temple', 'gudem-gutta-sri-satyanarayana-swamy-temple', 'The Gudem Gutta Shree Satyanarayana Swamy Temple is a Hindu temple, located on a hill (gutta) in Gudem Village, part of Dandepalle, Mancherial district, on the banks of the holy river Godavari. It is dedicated to Lord Vishnu, "God of truth" (Shree Satyanarayana Swamy).', 'Heritage & Spiritual', 'Telangana', 'Mancherial District', 'Dandepalle', '06:00 AM', '08:30 PM', 0, '', 'EASY', 4.6, 647, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Pranahita Wildlife Sanctuary', 'pranahita-wildlife-sanctuary', 'Pranahita wildlife sanctuary is a protected area located in Mancherial district (Old Adilabad District) of Telangana State, India. It lies along the Pranahita River, and forms a contiguous ecological landscape with the Pranhita Wildlife Sanctuary in the neighbouring Maharashtra.', 'Nature & Wildlife', 'Telangana', 'Mancherial District', 'Kotapally / Chennur', '06:00 AM', '05:30 PM', 30, '', 'EASY', 4.1, 25, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Jannaram Forest Gateway & Kawal Tiger Reserve Core', 'jannaram-forest-gateway-kawal-tiger-reserve-core', 'Kawal Wildlife Sanctuary is a wildlife sanctuary in Jannaram mandal of Mancherial District in the Telangana state of India. The Government of India declared it as a tiger reserve in 2012.', 'Nature & Wildlife', 'Telangana', 'Mancherial District', 'Jannaram', '06:30 AM', '06:00 PM', 1, '', 'EASY', 4.3, 2254, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Chennur Sri Agasthyeshwara Swamy Temple', 'chennur-sri-agasthyeshwara-swamy-temple', '🏞️ Chennur Agastheeswara Swamy Temple (Chennur Shivalyam / Agastheeswara Alayam) - an ancient Shiva temple located in Chennur village, Mancherial district, Telangana, on the sacred banks of the Godavari River, approximately 30 km from Mancherial town.', 'Heritage & Spiritual', 'Telangana', 'Mancherial District', 'Chennur', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.5, 38, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Singareni Open Cast Coal Mining Museum & Bellampalli Belts', 'singareni-open-cast-coal-mining-museum-bellampalli-belts', 'Bellampalli, located in Mancherial district, carries a rich and ancient history. The town grew with the rise of coal mining and is often called the land of black gold.', 'Artisans & Culture', 'Telangana', 'Mancherial District', 'Bellampalli / Mandamarri', '10:00 AM', '04:30 PM', 0, '', 'EASY', 4.5, 45, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Gadhpur Historic Stepwell & Mallikarjuna Temple', 'gadhpur-historic-stepwell-mallikarjuna-temple', 'A pencil-sketch reader''s archive for Mancherial city''s history, origin, verified notes, and community-submitted personal stories.', 'Heritage & Spiritual', 'Telangana', 'Mancherial District', 'Hajipur', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.5, 300, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Rallavagu Reservoir & Eco-Park', 'rallavagu-reservoir-eco-park', '"rallavagu-project" One year since foundation, work on Rallavagu bridge yet to start in Telangana''s Mancherial A cause-way built across the stream was constructed in 2005 spending Rs 80 lakh. It was caved in due to floods in 2020, necessitating the bridge', 'Lakes, Dams & Waterways', 'Telangana', 'Mancherial District', 'Mancherial Rural', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.5, 211, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Luxettipet Historic Ghats & Temples', 'luxettipet-historic-ghats-temples', 'Luxettipet or Lakshettipet is a municipality and census town in Mancherial district of the Indian state of Telangana. Located on the north bank of Godavari River.', 'Heritage & Spiritual', 'Telangana', 'Mancherial District', 'Luxettipet', '06:00 AM', '07:00 PM', 0, '', 'EASY', 4.4, 22, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Bheemaram Wild Flora Reserve & Forest Lake', 'bheemaram-wild-flora-reserve-forest-lake', 'Bheemaram is a village and mandal of the Mancherial District of Telangana State. It is previously under the jaipur Mandal, but after new district formation in Telangana State, this was declared as a new mandal for the Mancherial District.', 'Lakes, Dams & Waterways', 'Telangana', 'Mancherial District', 'Bheemaram', '07:00 AM', '05:30 PM', 0, '', 'EASY', 4.3, 2254, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kotapally Ancient Shiva Shrines & Godavari Sand Ghats', 'kotapally-ancient-shiva-shrines-godavari-sand-ghats', 'Explore ancient Shiva shrines along the Godavari River, from the Trimbakeshwar Jyotirlinga to the Kotipalli temple at the river''s confluence. A spiritual travel guide.', 'Heritage & Spiritual', 'Telangana', 'Mancherial District', 'Kotapally', '06:00 AM', '06:00 PM', 0, '', 'MODERATE', 5, 16, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Nizamabad Fort & Quilla Ramalayam', 'nizamabad-fort-quilla-ramalayam', 'Nizamabad Fort, also known as Nizamabad Quilla, is a fort in Nizamabad in the Indian state of Telangana. It was built in 10th century by Rashtrakuta Kings and is situated in the southwest of the city, which is 2 kilometers from Gandhi Chowk.', 'Heritage & Spiritual', 'Telangana', 'Nizamabad District', 'Nizamabad North', '06:00 AM', '06:30 PM', 0, '/images/telangana/nizamabad.jpg', 'EASY', 4.3, 1145, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Dichpally Ramalayam (The Khajuraho of Telangana)', 'dichpally-ramalayam-the-khajuraho-of-telangana', 'Dichpally Ramalayam is a Lord Rama temple located in Dichpally Village of Nizamabad, Telangana built in 14th century by Kakatiya kings. As the temple has a lot of resemblance in its style and structure, it is also called the Indhoor Khajuraho or the Khajuraho of Nizamabad.', 'Heritage & Spiritual', 'Telangana', 'Nizamabad District', 'Dichpally', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.7, 783, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Alisagar Deer Park & Reservoir', 'alisagar-deer-park-reservoir', 'Alisagar is a park, tourist attraction and an irrigation project which is 13 km (6.2 mi) from Nizamabad and 2 km (1.2 mi) off the Nizamabad-Bodhan road. The park was opened by the Nizam of Hyderabad in 1928. The park contains forested areas, a summer house, well laid out gardens, a reservoir and island, and a hilltop guest house all of which make it a favored getaway location.', 'Lakes, Dams & Waterways', 'Telangana', 'Nizamabad District', 'Yedapalle', '09:00 AM', '06:00 PM', 20, '', 'EASY', 4, 693, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ashok Sagar & Rock Garden', 'ashok-sagar-rock-garden', 'Ashok Sagar is located at janakampet village,yedpally mandal at a distance of about 7 k.m from Nizamabad and 26 k.m from Basara.This is situated on the route to the Famous saraswathi temple at basar from Hyderabad. It is a huge reservoir comprising of a beautiful Rock garden, octagonal Shaped restaurant, swinging bridge, boating facilities and […]', 'Heritage & Spiritual', 'Telangana', 'Nizamabad District', 'Jankampet / Nizamabad Rural', '09:30 AM', '06:30 PM', 20, '/images/candidates/nizamabad/2018032490.jpg', 'EASY', 4, 171, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Armoor Navanath Siddheshwara Rock Formations', 'armoor-navanath-siddheshwara-rock-formations', '🪨 Armoor (also known as Armur) - a town in Nizamabad District, Telangana, situated on NH‑44 (Hyderabad-Nagpur) and NH‑16 (Nizamabad-Jagdalpur). The town is famous for its 1.45‑billion‑year‑old granite rock formations - spectacular boulder hillocks shaped by billions of years of weathering.', 'Heritage & Spiritual', 'Telangana', 'Nizamabad District', 'Armoor', '06:00 AM', '06:00 PM', 0, '', 'EASY', 4.4, 26, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Neela Kanteshwara Swamy Temple', 'sri-neela-kanteshwara-swamy-temple', 'Sri Neelakanteshwara Temple near Nizamabad - discover Timings, Festivals, History, Darshan, Pooja Timings, trip duration, distance, near by places, location with route map & directions and photos.', 'Heritage & Spiritual', 'Telangana', 'Nizamabad District', 'Nizamabad South', '05:30 AM', '08:30 PM', 0, '', 'EASY', 4.7, 2059, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Mallaram Forest & Prehistoric Mushroom Rocks', 'mallaram-forest-prehistoric-mushroom-rocks', 'Mallaram Forest is a pristine eco‑tourism destination located about 8 km south‑west of Nizamabad town in Nizamabad district, Telangana, approximately 180 km from Hyderabad. Known for its dense woodlands, fresh air, and chirping birds, the forest has been developed as an eco‑tourism site with forest huts on a small hillock, a viewpoint tower, a pagoda, and trekking trails.', 'Heritage & Spiritual', 'Telangana', 'Nizamabad District', 'Nizamabad Rural', '08:30 AM', '05:30 PM', 20, '/images/candidates/nizamabad/2018052549.jpg', 'EASY', 4.2, 136, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Bodhan Historical Town & Chakreshwara Temple', 'bodhan-historical-town-chakreshwara-temple', 'Bodhan is a historic town and municipal city in the Nizamabad district of Telangana, India. Located about 27 km west of Nizamabad city, Bodhan Town is known for its rich ancient and medieval history. The town, once called Podana or Podanapura, was an important center during the Satavahana dynasty and later served as a regional capital under the Rashtrakutas.', 'Heritage & Spiritual', 'Telangana', 'Nizamabad District', 'Bodhan', '06:00 AM', '06:30 PM', 0, '', 'EASY', 4.8, 5, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Renjal Historic Dargah & River Crossing', 'renjal-historic-dargah-river-crossing', 'Renjal is a village in Nizamabad district in the state of Telangana in India.', 'Heritage & Spiritual', 'Telangana', 'Nizamabad District', 'Renjal', '06:00 AM', '07:00 PM', 0, '', 'EASY', 4.6, 36, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Varni Historic Rice Mills & Manjira Canal Headworks', 'varni-historic-rice-mills-manjira-canal-headworks', 'Nizamabad - A popular princely district in Telangana situated at a distance of about 175 kms from North-west of Hyderabad. The District derived its name as Nizamabad (Nizam-a-abadi) from the Nizam of Hyderabad Asaf Jahi, VI who had ruled Deccan during the 18th Century A.D. Originally the district called was INDUR known to have originated […]', 'Scenic & Cultural', 'Telangana', 'Nizamabad District', 'Varni', '07:00 AM', '06:00 PM', 0, '', 'MODERATE', 4.6, 29, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Domakonda Fort & Kamineni Gadi Palace', 'domakonda-fort-kamineni-gadi-palace', 'Domakonda Fort Domakonda Fort, until India''s independence, was the seat of the Rajas of the Kamineni family who governed the Domakonda Samasthan consisting of over a hundred villages in eighteen paraganas or subdivisions, in the present day Kamareddy district of Telangana state.', 'Heritage & Spiritual', 'Telangana', 'Kamareddy District', 'Domakonda', '09:00 AM', '05:30 PM', 50, '', 'EASY', 4.3, 2307, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Koulas Fort (12th-Century Military Citadel)', 'koulas-fort-12th-century-military-citadel', 'Kaulas Fort (Kowlas Fort) is a historic fort in western Telangana in India. It was constructed by Rashtrakutas in the 9th century CE. It later came under the rule of Chalukyas of Badami, the Kakatiyas, Musunuri Nayaks, Bahmani Sultanate, Qutub Shahis, Marathas, Mughals and, finally, the Asaf Jahi rulers of the Hyderabad State.', 'Historical Forts & Monuments', 'Telangana', 'Kamareddy District', 'Jukkal', '06:00 AM', '05:30 PM', 0, '', 'EASY', 4.5, 150, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Nizam Sagar Dam & Reservoir', 'nizam-sagar-dam-reservoir', 'Nizam Sagar Dam is an Indian dam named after the Nizam of Hyderabad. It is a reservoir constructed across the Manjira River, a tributary of the Godavari River, between Achampet and BanjePally villages of the Kamareddy district in Telangana, India.', 'Lakes, Dams & Waterways', 'Telangana', 'Kamareddy District', 'Nizamsagar', '07:00 AM', '06:30 PM', 20, '/images/candidates/kamareddy/2019021990.jpg', 'EASY', 4.5, 2500, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Biknoor Sri Siddha Rameshwara Swamy Temple', 'biknoor-sri-siddha-rameshwara-swamy-temple', 'Sidharameshwara Temple, Bhiknoor is an ancient Shiva shrine in Kamareddy district known for its rare south-facing lingam. History, timings, and travel info.', 'Heritage & Spiritual', 'Telangana', 'Kamareddy District', 'Biknoor', '06:00 AM', '08:30 PM', 0, '', 'EASY', 4.7, 567, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Pocharam Wildlife Sanctuary & Lake (Kamareddy Section)', 'pocharam-wildlife-sanctuary-lake-kamareddy-section', 'Pocharam Wildlife Sanctuary is a forest and wildlife sanctuary located 15 km (9.3 mi) from Medak and 115 km (71 mi) from Hyderabad, Telangana, India.', 'Lakes, Dams & Waterways', 'Telangana', 'Kamareddy District', 'Nagireddypet / bordering Medak', '08:00 AM', '05:30 PM', 30, '', 'EASY', 4.1, 209, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Gandhari Khilla (Ancient Forest Citadel)', 'gandhari-khilla-ancient-forest-citadel', 'Gandhari khilla is a hill fort located near Bokkalagutta, in Mandamarri Mandal in Mancherial district in the Indian state of Telangana. It is located on the sand rock hills.', 'Historical Forts & Monuments', 'Telangana', 'Kamareddy District', 'Gandhari', '07:00 AM', '05:00 PM', 0, '', 'EASY', 4.5, 300, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Koulas Nala Dam & Forest Eco-Trail', 'koulas-nala-dam-forest-eco-trail', 'Kaulas Fort (Kowlas Fort) is a historic fort in western Telangana in India. It was constructed by Rashtrakutas in the 9th century CE. It later came under the rule of Chalukyas of Badami, the Kakatiyas, Musunuri Nayaks, Bahmani Sultanate, Qutub Shahis, Marathas, Mughals and, finally, the Asaf Jahi rulers of the Hyderabad State.', 'Historical Forts & Monuments', 'Telangana', 'Kamareddy District', 'Pitlam', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.4, 73, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Raja Rajeshwara Swamy Temple, Lingampet', 'sri-raja-rajeshwara-swamy-temple-lingampet', 'Sri Raja Rajeshwara Swamy Temple Located in Banda Rameshwarpalle Village, Machareddy mandal of Kamareddy District, This Temple also well known as Sri Mallikarjuna Swamy Temple and Banda Rameshwara Swamy Temple. The main presiding deity here is also fondly called as Sri Raja Rajeshwara Swayambhu Kshetram.', 'Heritage & Spiritual', 'Telangana', 'Kamareddy District', 'Lingampet', '06:00 AM', '07:30 PM', 0, '/images/telangana/vemulawada.jpg', 'EASY', 4.6, 33261, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Machareddy Forest Valley & Hill Ridge Trek', 'machareddy-forest-valley-hill-ridge-trek', 'While Kamareddy district itself was not a core territory of the Ikshvakus, the dynasty likely exercised influence over the region through trade networks, political alliances, or as a peripheral area. The presence of Ikshvaku coins in the Nizamabad museum confirms their currency was in use in the area.', 'Heritage & Spiritual', 'Telangana', 'Kamareddy District', 'Machareddy', '07:00 AM', '05:00 PM', 0, '', 'MODERATE', 4.2, 22, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Nasrullabad & Nizamsagar Feeder Canal Viewpoint', 'nasrullabad-nizamsagar-feeder-canal-viewpoint', 'Coins: The District Archaeological Museum in Nizamabad houses coins from the Ikshvaku dynasty, indicating their currency circulated in the wider Kamareddy region. Inscriptions: The most notable Ikshvaku inscription in Telangana is a ten-line inscription issued by King Kshantamula at Phanigiri in Suryapet district.', 'Scenic & Cultural', 'Telangana', 'Kamareddy District', 'Nasrullabad', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.5, 2500, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Dharmapuri Sri Lakshmi Narasimha Swamy Temple', 'dharmapuri-sri-lakshmi-narasimha-swamy-temple', 'Lakshmi Narasimha Temple is located in Dharmapuri town, Jagitial district, in Telangana, India. It is the abode of Narsimha Swamy, the fourth avatar of Vishnu, and his consort Devi Lakshmi. The place has garnered considerable crowd over the years. The temple was built during the reign of the Chalukyas, and later expanded by the Kakatiyas.', 'Heritage & Spiritual', 'Telangana', 'Jagtial District', 'Dharmapuri', '05:00 AM', '08:30 PM', 0, '/images/telangana/dharmapuri.jpg', 'EASY', 4.7, 2772, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kondagattu Sri Anjaneya Swamy Temple', 'kondagattu-sri-anjaneya-swamy-temple', 'Kondagattu Anjaneya Swamy Temple (Telugu: కొండగట్టు ఆంజనేయస్వామి ఆలయం) is a prominent Hindu temple dedicated to Lord Hanuman (Anjaneya), situated on a hill near Muthyumpeta village in Mallial mandal of Jagitial district, Telangana, India.', 'Heritage & Spiritual', 'Telangana', 'Jagtial District', 'Malyal / Kodimial', '04:30 AM', '09:00 PM', 0, '/images/telangana/kondagattu.jpg', 'EASY', 4.6, 17526, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Jagtial Fort (French Star-Shaped Fortress)', 'jagtial-fort-french-star-shaped-fortress', 'Jagtial Fort (also Jagityal Fort) is a historic star-shaped fort located in Jagtial town, Jagitial District, Telangana, approximately 190 km from Hyderabad. The fort is officially described by the Jagtial district administration as the only star-shaped fort in Telangana and is surrounded by a water-filled moat.', 'Historical Forts & Monuments', 'Telangana', 'Jagtial District', 'Jagtial', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.3, 406, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Polasa Sri Paulastyeshwara Temple', 'polasa-sri-paulastyeshwara-temple', 'Pyata Srilatha Research Scholar, School of History, Culture and Archaeology, Potti Sree Ramulu Telugu University, Srishailam, India Keywords: Architecture of temples, chalukyan triple shrine, polavasadesa or polasa, pulastyeshwara temple, viragal Abstract This paper represents an overview of Temples at polasa in jagityal district - A study. Downloads', 'Heritage & Spiritual', 'Telangana', 'Jagtial District', 'Jagtial Rural (Polasa)', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.7, 213, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kotilingala Godavari Confluence & Satavahana Site', 'kotilingala-godavari-confluence-satavahana-site', 'Kotilingala is a Hindu pilgrimage site in Jagtial district of the Indian state of Telangana. It is situated in Velagatoor mandal of the district, on the Godavari River. It is located on the bank of the Godavari River, and has a traditional Shiva temple for Hindus, the Koteshwara Siddeshwara Temple.', 'Heritage & Spiritual', 'Telangana', 'Jagtial District', 'Velgatoor', '06:00 AM', '06:30 PM', 0, '', 'EASY', 4.5, 22, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Koritla & Metpalli Handloom & Silk Weavers'' Belt', 'koritla-metpalli-handloom-silk-weavers-belt', 'District & neighbours Jagtial meets Nirmal, Mancherial, Peddapalli, Karimnagar, Rajanna Sircilla, Nizamabad, and neighbours — Korutla sits on the web between Hyderabad, Karimnagar, Nizamabad, and the Godavari belt (Dharmapuri, Kotilingala). Metpally and Jagtial are usual hubs for services and bulk trade.', 'Artisans & Culture', 'Telangana', 'Jagtial District', 'Koritla / Metpalli', '09:30 AM', '07:00 PM', 0, '', 'EASY', 4.5, 13, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Kasi Visweswara Swamy Temple, Buggaram', 'sri-kasi-visweswara-swamy-temple-buggaram', 'Kasi Visweswara Temple near Tirupati - discover Timings, Festivals, History, Darshan, Pooja Timings, trip duration, distance, near by places, location with route map & directions and photos.', 'Heritage & Spiritual', 'Telangana', 'Jagtial District', 'Buggaram', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.7, 3, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Raikal Keshavanatha Swamy Temple', 'raikal-keshavanatha-swamy-temple', 'Raikal is a town and headquarters of raikal mandal located in the Jagtial district, Telangana, India It is known for being the home place of the ancient temple of Keshavanathaswamy, which was built in 1304 A.D. by Kakatiya King Prataparudra and is called as Kota Gudi, due to the mud fort that surrounds the temple.', 'Heritage & Spiritual', 'Telangana', 'Jagtial District', 'Raikal', '06:30 AM', '07:30 PM', 0, '', 'EASY', 4.8, 148, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ibrahimpatnam Rural Mango Orchards & Lake Viewpoint', 'ibrahimpatnam-rural-mango-orchards-lake-viewpoint', 'Explore history of Ibrahimpatnam from 1550-1580 under Sultan Ibrahim Qutb Shah, the visionary fourth ruler of Golconda. Learn the iconic Ibrahimpatnam Lake.', 'Scenic & Cultural', 'Telangana', 'Jagtial District', 'Ibrahimpatnam', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.5, 62, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Gollapalle Ancient Veeragallu (Hero Stones) & Kakatiya Wells', 'gollapalle-ancient-veeragallu-hero-stones-kakatiya-wells', 'A hero stone with Old Kannada inscription of 1286 CE during the rule of Yadava King Ramachandra in the Kedareshvara Temple, Balligavi in Shimoga district, Karnataka A hero stone (vīragallu in Kannada, naṭukal in Tamil) is a memorial commemorating the honorable death of a hero in battle.', 'Heritage & Spiritual', 'Telangana', 'Jagtial District', 'Gollapalle', '07:00 AM', '05:30 PM', 0, '', 'EASY', 4.4, 23219, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Vemulawada Sri Raja Rajeshwara Swamy Temple (Dakshina Kasi)', 'vemulawada-sri-raja-rajeshwara-swamy-temple-dakshina-kasi', 'Sri Raja Rajeshwara Temple is one of the most famous Hindu temples in Telangana, India, dedicated to Lord Shiva. It is located in the town of Vemulawada, Telangana, India. Historically the region was the capital of the Vemulawada Chalukyas who ruled from 750 to 973 CE.', 'Heritage & Spiritual', 'Telangana', 'Rajanna Sircilla District', 'Vemulawada', '04:00 AM', '09:30 PM', 0, '', 'EASY', 4.6, 33261, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sircilla Textile Town & Master Weavers'' Hub', 'sircilla-textile-town-master-weavers-hub', 'Siricilla (also spelled as Sircilla or Sirsilla) is a town and the district headquarters of Rajanna Siricilla district in the Indian state of Telangana. It is located on the banks of Manair river in the Siricilla mandal of Siricilla revenue division. It is popularly known as Textile Town due to the presence of large number of power looms, textile processing and dyeing units.', 'Artisans & Culture', 'Telangana', 'Rajanna Sircilla District', 'Sircilla', '09:30 AM', '07:30 PM', 0, '', 'EASY', 4.5, 8, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Mid-Manair Dam (Sri Raja Rajeshwara Reservoir)', 'mid-manair-dam-sri-raja-rajeshwara-reservoir', 'Mid Manair Dam is a major irrigation project across the Manair River, at Manwada Village, Boinpalli Mandal, Rajanna Sircilla district, Telangana. It has a capacity of 25.87 tmcft with 25 radial gates.', 'Lakes, Dams & Waterways', 'Telangana', 'Rajanna Sircilla District', 'Boinpalle', '07:00 AM', '06:30 PM', 0, '', 'EASY', 4.5, 1306, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Upper Manair Dam (Narmala Dam)', 'upper-manair-dam-narmala-dam', 'The Upper Manair Dam (Urdu: اوپر مانیر ڈیم) is a dam on the Manair River, at Narmal Village, Gambhiraopet mandal, Rajanna Sircilla district, Telangana by Nizam. Situated at narmala village, rajanna sircilla district. Foundation stone laid in 1943 by Nizam of Hyderabad State presented by Janab Shaikhaan Sahab.', 'Lakes, Dams & Waterways', 'Telangana', 'Rajanna Sircilla District', 'Gambhiraopet', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.5, 2500, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Baddi Pochamma Temple, Vemulawada', 'baddi-pochamma-temple-vemulawada', 'Baddi Pochamma Temple near Vemulawada - discover Timings, Festivals, History, Darshan, Pooja Timings, trip duration, distance, near by places, location with route map & directions and photos.', 'Heritage & Spiritual', 'Telangana', 'Rajanna Sircilla District', 'Vemulawada', '06:00 AM', '08:30 PM', 0, '', 'EASY', 4.6, 2835, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ananthagiri Hills & Annapurna Reservoir', 'ananthagiri-hills-annapurna-reservoir', 'A district named after a god, built on a lost dynasty''s capital, and run today by the hum of forty thousand power looms — this is everything you should know Rajanna Sircilla, Telangana.', 'Historical Forts & Monuments', 'Telangana', 'Rajanna Sircilla District', 'Illanthakunta', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.6, 94, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Rama Temple, Illanthakunta', 'sri-rama-temple-illanthakunta', 'A sacred Ramayana-era temple known as the "Second Bhadrachalam of Telangana," Sri Sita Rama Chandra Swamy Devasthanam at Ellanthakunta is revered for its association with Lord Rama''s exile, unique west-facing sanctum, and grand Sri Rama Navami celebrations.', 'Heritage & Spiritual', 'Telangana', 'Rajanna Sircilla District', 'Illanthakunta', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.5, 38, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Konaraopet Forest Viewpoint & Granite Hills', 'konaraopet-forest-viewpoint-granite-hills', 'Scenic hillock viewpoint surrounded by granite ridges and natural forest tracks in Rajanna Sircilla district, offering expansive views across rural countryside.', 'Scenic & Cultural', 'Telangana', 'Rajanna Sircilla District', 'Konaraopet', '07:00 AM', '05:30 PM', 0, '', 'EASY', 4.5, 2500, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Thangallapalle Apparel Park & Modern Weaving Looms', 'thangallapalle-apparel-park-modern-weaving-looms', 'Major textile weaving and apparel manufacturing cluster near Sircilla, showcasing modern powerlooms and celebrated regional textile craftsmanship.', 'Artisans & Culture', 'Telangana', 'Rajanna Sircilla District', 'Thangallapalle', '09:30 AM', '06:30 PM', 0, '', 'EASY', 4.3, 37, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Mustabad Historic Stepwells & Grain Mandis', 'mustabad-historic-stepwells-grain-mandis', 'Mustabad is a village and mandal headquarters of Mustabad mandal, located in Rajanna Sircilla district of Telangana, India.', 'Heritage & Spiritual', 'Telangana', 'Rajanna Sircilla District', 'Mustabad', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.3, 80, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Elgandal Fort (Historic Hill Citadel)', 'elgandal-fort-historic-hill-citadel', 'Elgandal Fort is situated amidst palm groves on the banks of the Manair River (a tributary of the Godavari River), approximately 10 kilometres (6.2 mi) from Karimnagar on the Sircilla Road in the Indian state of Telangana.', 'Heritage & Spiritual', 'Telangana', 'Karimnagar District', 'Karimnagar Rural (Elgandal)', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.3, 1824, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Karimnagar Silver Filigree (Tarkashi) Artisan Guilds', 'karimnagar-silver-filigree-tarkashi-artisan-guilds', 'Silver Filigree of Karimnagar Karimnagar Silver Filigree is a silver filigree made in Karimnagar, India. It is an ancient art of Karimnagar.', 'Artisans & Culture', 'Telangana', 'Karimnagar District', 'Karimnagar Urban', '10:00 AM', '07:30 PM', 0, '', 'EASY', 4.5, 54, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Lower Manair Dam (LMD) & Deer Park', 'lower-manair-dam-lmd-deer-park', 'Lower Manair Dam also known as LMD was constructed across the Manair River, at Alugunur village, Thimmapur mandal, Karimnagar District, in the Indian state of Telangana during 1974 to 1985.', 'Lakes, Dams & Waterways', 'Telangana', 'Karimnagar District', 'Thimmapur / Karimnagar South', '08:00 AM', '06:30 PM', 20, '', 'EASY', 4.5, 1941, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Karimnagar Cable Bridge & Riverfront Promenade', 'karimnagar-cable-bridge-riverfront-promenade', 'The bridge is situated to provide connectivity between Karimnagar and surrounding suburbs, as well as regional highways leading toward Warangal, Siddipet, and Hyderabad. It has helped to reduce congestion on older bridges and inner-city roads, thereby decreasing travel times and enhancing road safety.', 'Scenic & Cultural', 'Telangana', 'Karimnagar District', 'Karimnagar Urban', '07:00 PM', '10:00 PM', 0, '/images/telangana/karimnagar.jpg', 'EASY', 3.7, 26, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Nagunur Group of Kakatiya Temples', 'nagunur-group-of-kakatiya-temples', 'Nagunur Fort was a fort built by the Kakatiya dynasty. It is around 8 km north of Karimnagar. The fort is testimony to the imperial powers of the Kakatiyas. It was one of the most important forts of the emerging Kakatiya dynasty and contains ruins of a cluster of Western Chalukya and Kakatiya temples.', 'Heritage & Spiritual', 'Telangana', 'Karimnagar District', 'Karimnagar Rural (Nagunur)', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.7, 34, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ujwala Park & Rajiv Deer Park', 'ujwala-park-rajiv-deer-park', 'Rajeev Gandhi Deer Park located near Ujwala Park, is known for its teeming deer population. Located along River Godavari, Shivaram wildlife Sanctuary in Karimnagar district is a beautiful wildlife sanctuary spread over 36.29 sq.km approximately.', 'Nature & Wildlife', 'Telangana', 'Karimnagar District', 'Karimnagar Urban', '09:00 AM', '07:00 PM', 20, '', 'EASY', 4, 2361, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Chinthakunta Prehistoric Rock Art Site', 'chinthakunta-prehistoric-rock-art-site', 'Chinthakunta is one of South India''s largest prehistoric rock art sites, featuring dozens of red and white pigment paintings on natural granite overhangs depicting ancient animals, hunting scenes, and geometric symbols.', 'Nature & Wildlife', 'Telangana', 'Karimnagar District', 'Kothapally', '08:00 AM', '05:00 PM', 0, '', 'EASY', 4.3, 121, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Tower Circle & Heritage Clock Tower', 'tower-circle-heritage-clock-tower', 'The constant stream of traffic, shoppers, and residents makes the Tower Circle a perpetual hive of activity and the city''s most vibrant social and economic hub. It is a place where old and new Karimnagar intersect, with the old clock tower standing symbol to the city''s evolution amidst the modern commercial chaos.', 'Scenic & Cultural', 'Telangana', 'Karimnagar District', 'Karimnagar Urban', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.6, 50, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Manakondur Lake & Rural Heritage Trail', 'manakondur-lake-rural-heritage-trail', 'Manakondur is a village in Manakondur mandal of Karimnagar district of the Indian state of Telangana.', 'Lakes, Dams & Waterways', 'Telangana', 'Karimnagar District', 'Manakondur', '07:00 AM', '06:30 PM', 0, '', 'EASY', 4.1, 136, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Choppadandi Historic Stepwells & Chalukyan Inscriptions', 'choppadandi-historic-stepwells-chalukyan-inscriptions', 'The history of Warangal region from its inscriptions is known from the rise of the K&katlyas in the middle of twelfth century A. D., whereas Karimnagar region by virtue of its proximity to the river Godavari, has yielded greater results of antiquarian importance.', 'Scenic & Cultural', 'Telangana', 'Karimnagar District', 'Choppadandi', '07:00 AM', '05:30 PM', 0, '', 'EASY', 4.5, 2500, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('NTPC Ramagundam & India''s Largest Floating Solar Plant', 'ntpc-ramagundam-india-s-largest-floating-solar-plant', 'The 100 MW plant is built on the balancing reservoir of the NTPC Ramagundam and reached full operational capacity on July 1, 2022. Spanning 500 acres and built by Bharat Heavy Electricals Limited at a cost of ₹423 crore (equivalent to ₹489 crore or US$51 million in 2026), the floating plant consists of 40 blocks, each capable of producing 2.5 MW.', 'Lakes, Dams & Waterways', 'Telangana', 'Peddapalli District', 'Ramagundam', '10:00 AM', '04:30 PM', 0, '', 'EASY', 3.8, 5, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Dhulikatta Buddhist Stupa & Satavahana Archaeological Site', 'dhulikatta-buddhist-stupa-satavahana-archaeological-site', 'Dhulikatta (also known as Pedda Bankur) is a village in Eligaid mandal, Peddapalli district, Telangana, about 25 km from Karimnagar city. The name Dhulikatta derives from Dhulikota - "a fort made of mud". The site is one of the thirty walled cities mentioned by the Greek ambassador Megasthenes (c. 300 BCE) in his Indica.', 'Heritage & Spiritual', 'Telangana', 'Peddapalli District', 'Eligedu', '09:00 AM', '05:30 PM', 0, '', 'EASY', 4.6, 28, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sabitham Waterfalls & Kakatiya Rock Cave Temple (Gauri Gundam)', 'sabitham-waterfalls-kakatiya-rock-cave-temple-gauri-gundam', 'The waterfall in Sabitham village in Peddapalli is drawing hundreds of people everyday Located in a thick forest and surrounded by hillocks, the waterfall in the Sabhitam village in Peddapalli mandal is drawing huge crowds this monsoon season, but crying for attention from the district authorities.', 'Waterfalls & Gorges', 'Telangana', 'Peddapalli District', 'Peddapalli Rural', '07:00 AM', '05:30 PM', 0, '', 'EASY', 4.3, 335, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Manthani Historic Vedic Town & Gautameshwara Temple', 'manthani-historic-vedic-town-gautameshwara-temple', 'The surviving Shiva temple, its Kakatiya-period architectural character, the wider cluster of historic shrines and the town''s long association with Vedic learning make Manthani a significant religious and archaeological destination.', 'Heritage & Spiritual', 'Telangana', 'Peddapalli District', 'Manthani', '06:00 AM', '08:00 PM', 0, '', 'EASY', 4.6, 14, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sundilla (Parvathi) Barrage & Kaleshwaram Headworks', 'sundilla-parvathi-barrage-kaleshwaram-headworks', 'The Parvati Barrage, also known as the Sundilla Barrage, is an irrigation project located at Kasipeta Village, Manthani Mandal, Peddapalli district in Telangana State, India. [failed verification] This is one of the three barrages proposed in Kaleshwaram Project which envisages construction of three barrages between Yellampalli (Ramagundam) and Medigadda. Proposed Sundilla Barrage details:', 'Lakes, Dams & Waterways', 'Telangana', 'Peddapalli District', 'Manthani / Ramagundam border', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.3, 538, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ramagiri Khilla (Hilltop Forest Fortress)', 'ramagiri-khilla-hilltop-forest-fortress', 'The Ramagiri Fort, also known as Ramagiri Khilla, located over a mountain top, is in the Peddapalli district of the Indian state of Telangana. in ramagiri khilla the Hanuman statue was constructed by Gaddam Bapu from mancherial district. The family member will visit every year and make pray and worship for lord Hanuman.', 'Heritage & Spiritual', 'Telangana', 'Peddapalli District', 'Ramagiri / Kamanpur', '06:30 AM', '05:00 PM', 0, '', 'EASY', 4.4, 265, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Odela Sri Mallikarjuna Swamy Temple', 'odela-sri-mallikarjuna-swamy-temple', 'Odela Sri Mallikarjuna Swamy Temple is an ancient Shaiva shrine located about 2 km from Odela village in Odela Mandal, Peddapalli district, Telangana. The area was formerly part of Karimnagar district before the reorganization of Telangana''s districts. The temple is dedicated to Sri Mallikarjuna Swamy (Shiva) with Sri Bramarambha Devi.', 'Heritage & Spiritual', 'Telangana', 'Peddapalli District', 'Odela', '06:00 AM', '08:00 PM', 0, '/images/aptourism/mallikarjuna_swamy_temple_srisailam.jpg', 'EASY', 4.6, 755, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Gumpula Sri Lakshmi Narasimha Swamy Temple', 'gumpula-sri-lakshmi-narasimha-swamy-temple', 'Ancient hilltop cave temple in Peddapalli district dedicated to Lord Sri Yogananda Lakshmi Narasimha Swamy, featuring natural rock boulders, panoramic countryside views, and sacred rock-cut sanctum.', 'Heritage & Spiritual', 'Telangana', 'Peddapalli District', 'Odela', '06:30 AM', '07:30 PM', 0, '', 'EASY', 4.6, 755, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kamanpur Historic Kakatiya Stepwell & Shiva Temple', 'kamanpur-historic-kakatiya-stepwell-shiva-temple', 'The Kakatiya dynasty (IAST: Kākatīya) [a] was a Telugu dynasty that ruled most of eastern Deccan region in present-day India between 12th and 14th centuries. Their territory comprised much of the present day Telangana and Andhra Pradesh, parts of eastern Karnataka, northern Tamil Nadu, and southern Odisha. Their capital was Orugallu, now known as Warangal.', 'Heritage & Spiritual', 'Telangana', 'Peddapalli District', 'Kamanpur', '06:30 AM', '07:30 PM', 0, '', 'EASY', 4.7, 515, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sultanabad Historic Grain Market & Chalukyan Reliefs', 'sultanabad-historic-grain-market-chalukyan-reliefs', 'The Chalukya dynasty (Kannada: [tʃaːlukjɐ]) was a Classical Indian dynasty that ruled large parts of southern and central India between the 6th and the 12th centuries. During this period, they ruled as three related yet individual dynasties. The earliest dynasty, known as the "Badami Chalukyas", ruled from Vatapi (modern Badami) from the middle of the 6th century.', 'Scenic & Cultural', 'Telangana', 'Peddapalli District', 'Sultanabad', '07:00 AM', '07:00 PM', 0, '', 'EASY', 4.5, 2500, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Nagarjuna Sagar Dam & Crest Gates Spray', 'nagarjuna-sagar-dam-crest-gates-spray', 'Nagarjuna Sagar gates opened Nagarjuna Sagar Dam is a masonry dam across the Krishna River at Nagarjuna Sagar, which straddles the border between Nalgonda district in Telangana, and Palnadu district in Andhra Pradesh.', 'Lakes, Dams & Waterways', 'Telangana', 'Nalgonda District', 'Vijayapuri North', '08:00 AM', '06:00 PM', 20, '', 'EASY', 4.5, 318, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Chaya Someswara Temple (Optical Physics Shadow Mystery)', 'chaya-someswara-temple-optical-physics-shadow-mystery', 'Chaya Someshwara Temple is a Shaivite Hindu temple located in Panagal, Nalgonda district of Telangana, India. It was built around the mid-11th century during the rule of the Kunduru Chodas (a branch of Telugu Cholas), supported and embellished further by later Hindu dynasties of Telangana. Some date it to late 11th to early 12th-century.', 'Waterfalls & Gorges', 'Telangana', 'Nalgonda District', 'Panagal', '06:00 AM', '08:00 PM', 0, '', 'EASY', 4.7, 3484, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Pachala Someswara Temple & Sculptural Gallery', 'pachala-someswara-temple-sculptural-gallery', 'Pachala Someswara Temple is a Shaivite Hindu temple located in Panagal, Nalgonda district, Telangana, India. It is a popular pilgrimage site particularly during Maha Shivaratri. The idol of the deity at the temple is carved out of green onyx, which is the source of the temple''s name— Pacha meaning "green" in Telugu.', 'Heritage & Spiritual', 'Telangana', 'Nalgonda District', 'Panagal', '06:00 AM', '07:30 PM', 0, '/images/candidates/nalgonda/2018070318.jpg', 'EASY', 4.8, 431, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Devarakonda Hill Fortress', 'devarakonda-hill-fortress', 'At a distance of 1.3 km from Devarakonda Bus Station, 60 km from Nalgonda and 111 km from Hyderabad, Devarakonda Fort is located in Devarakonda town in Nalgonda District of Telangana. This is one of the important historical sites to visit around Nalgonda & Hyderabad.', 'Historical Forts & Monuments', 'Telangana', 'Nalgonda District', 'Devarakonda', '08:00 AM', '05:30 PM', 0, '', 'EASY', 4.5, 783, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Phanigiri Buddhist Monastic Complex', 'phanigiri-buddhist-monastic-complex', 'Abstract: Numerous historical traces of ancient civilization can be found across the Indian subcontinent. ''Phanigiri'' located in the present-day Suryapet district (formerly part of the undivided Nalgonda district) in Telangana, India, is recognized as a significant ancient Buddhist archaeological site.', 'Heritage & Spiritual', 'Telangana', 'Nalgonda District', 'Thirumalagiri / Nalgonda border', '09:00 AM', '05:00 PM', 0, '', 'EASY', 4.6, 195, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Dindi Reservoir & Eco-Tourism Camp', 'dindi-reservoir-eco-tourism-camp', 'R. Vidyasagar Rao Dindi Lift Irrigation Scheme is a lift irrigation project in Nalgonda, Telangana, India. It serves Nalgonda, Mahbubnagar and Khammam areas. It was named after R. Vidyasagar Rao, an irrigation expert in Telangana.', 'Lakes, Dams & Waterways', 'Telangana', 'Nalgonda District', 'Dindi', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.6, 816, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Mellacheruvu Sri Swayambhu Sambhulingeswara Temple', 'mellacheruvu-sri-swayambhu-sambhulingeswara-temple', 'Renowned Shaiva temple Mellacheruvu Sri Shambhu Lingeswara Swamy is situated in the former Nalgonda district. The Yadava monarchs built the temple during the Kakatiya period in the eleventh century, and it is dedicated to the goddess Ishwaryeswari and Shambhu Lingeswara Swamy. The temple was later expanded by Kakatiya dynasty king Prataparudra.', 'Heritage & Spiritual', 'Telangana', 'Nalgonda District', 'Mellacheruvu', '06:00 AM', '08:30 PM', 0, '', 'EASY', 4.7, 397, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Latif Saheb Dargah & Nalgonda Khilla Hillock', 'latif-saheb-dargah-nalgonda-khilla-hillock', 'Lateef Saheb Dargah Lateef Ullah Shah Quadri Darga or Lateef Saheb Dargah is a Sufi shrine located in the Nalgonda District of Telangana, India. It is situated on a hillock. Pilgrims and tourists trek the hammock to succeed in the shrine and supply their prayers.', 'Heritage & Spiritual', 'Telangana', 'Nalgonda District', 'Nalgonda', '06:00 AM', '06:00 PM', 0, '/images/telangana/nalgonda.jpg', 'EASY', 4.8, 58, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Munugode Handloom Cotton & Wool Guilds', 'munugode-handloom-cotton-wool-guilds', 'Nalgonda district in Telangana has a rich historical background from prehistoric times to modern political movements, with its name reflecting the black hills of the region. It has been influenced by various dynasties, including the Mauryas, Satavahanas, Kakatiyas, and the Nizams, each contributing to its cultural and architectural heritage.', 'Artisans & Culture', 'Telangana', 'Nalgonda District', 'Munugode', '09:30 AM', '06:30 PM', 0, '', 'EASY', 4.5, 2500, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Cheruvugattu Sri Parvathi Jadala Ramalingeshwara Temple', 'cheruvugattu-sri-parvathi-jadala-ramalingeshwara-temple', 'Sri Parvathi Jadala Ramalingeswara Swamy Devasthanam is situated on the hillock at Cheruvugattu and it is ancient and historical temple.', 'Heritage & Spiritual', 'Telangana', 'Nalgonda District', 'Narketpally', '05:30 AM', '08:30 PM', 0, '/images/candidates/anantapur/bagga-ramalingeshwara-swamy-temple-anantpur-1-andhra-pradesh-attr-popular.jpg', 'MODERATE', 4.6, 2553, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Undrugonda Fort & Sri Lakshmi Narasimha Temple', 'undrugonda-fort-sri-lakshmi-narasimha-temple', 'It is a magnificent archaeological and spiritual pilgrimage center hosting different temples of which Sri Undrugonda Laxmi Narasimha Swamy is best worshiped adored by local public. Many fortifications, hillocks, valleys, lakes and greenery of the forest also make a very beautiful eco-tourist destination.', 'Heritage & Spiritual', 'Telangana', 'Suryapet District', 'Chivvemla', '07:00 AM', '06:00 PM', 0, '/images/candidates/suryapet/2022090973.jpg', 'EASY', 4.8, 96, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Mattapalli Sri Yoga Ananda Lakshmi Narasimha Swamy', 'mattapalli-sri-yoga-ananda-lakshmi-narasimha-swamy', 'The Yogananda Lakshmi Narasimha Swamy Temple, also known as Mattapalli Narasimha Temple, is a Hindu temple dedicated to Narasimha, the half-man half-lion avatar of Vishnu, and his consort Lakshmi. It is located in Mattampally (also known as Mattapalli), a village in the Mattampally mandal of Suryapet district in the Indian state of Telangana.', 'Heritage & Spiritual', 'Telangana', 'Suryapet District', 'Mattampally', '05:00 AM', '08:30 PM', 0, '/images/candidates/suryapet/2022090950.jpg', 'EASY', 4.7, 1440, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Pillalamarri Sri Chennakesava & Nameswara Temples', 'pillalamarri-sri-chennakesava-nameswara-temples', 'Nameswara Temple, also known as Parvati Mahadeva Nameswara temple, is a Saivite Hindu temple located in Pillalamarri, Suryapet district of Telangana, India. It is a double temple, with the Trikuteswara Temple aligned in parallel to it on the immediate north.', 'Heritage & Spiritual', 'Telangana', 'Suryapet District', 'Suryapet Rural', '06:30 AM', '07:30 PM', 0, '/images/candidates/suryapet/2019013138.jpg', 'EASY', 4.7, 21, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Suryapet Highway Food Hub & Hi-Tech Dhabas', 'suryapet-highway-food-hub-hi-tech-dhabas', 'Suryapet town is a major road junction. It lies on the National Highway 65 and is located exactly between Hyderabad, the capital of Telangana and Vijayawada, the capital city of Andhra Pradesh. TSRTC operates buses from Suryapet to many major cities, towns and villages.', 'Scenic & Cultural', 'Telangana', 'Suryapet District', 'Suryapet Urban', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.4, 48511, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Arvapally Sri Ramalingeshwara Temple', 'arvapally-sri-ramalingeshwara-temple', 'The festival is protected by police and assisted by volunteers during 3-day period. It is located in Durajpally village [Suburb in Suryapet Municipality], Suryapet District, Telangana state. Sri Undrugonda Laxmi Narasimha Swami Devasthanam Undrugonda is situated in Vallabhapuram village of Chivvemla Mandal, Nalgonda dist, Telangana state, India.', 'Heritage & Spiritual', 'Telangana', 'Suryapet District', 'Arvapally', '06:00 AM', '07:30 PM', 0, '/images/candidates/suryapet/2022090955.jpg', 'EASY', 4.6, 118, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Musi River Balancing Reservoir & Anicut', 'musi-river-balancing-reservoir-anicut', 'The Musi Project is constructed in the year 1963 across the Musi River near Solipet (V) in Nalgonda (Dt.). The Project is designed with a live storage of 4.60 TMC to extend irrigation facility to 41,800 Acers through L.F and R.F Canal covering 42 villages in six mandals of Nalgonda District.', 'Lakes, Dams & Waterways', 'Telangana', 'Suryapet District', 'Penpahad', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.2, 19, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Huzurnagar Historic Temples & Grain Market', 'huzurnagar-historic-temples-grain-market', 'Huzurnagar is the third largest town in the Suryapet district of the Indian state of Telangana. Huzurnagar is a Municipality and the Mandal Headquarters of Huzurnagar Mandal in Huzurnagar Revenue Division.', 'Heritage & Spiritual', 'Telangana', 'Suryapet District', 'Huzurnagar', '07:00 AM', '07:00 PM', 0, '', 'EASY', 4.5, 75, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Thungathurthi & Kakatiya Tank Network', 'thungathurthi-kakatiya-tank-network', 'Thungathurthy is a village in Suryapet district of the Indian state of Telangana. It is located in Thungathurthy mandal of Suryapet Revenue Division. It is about 42 km from the district headquarters Suryapet. Historically, Thungathurty has a significance of being the earliest region to ascend to the Indian Union.', 'Scenic & Cultural', 'Telangana', 'Suryapet District', 'Thungathurthi', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.5, 2500, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kodad Historic Granary & Krishna Canal Regulators', 'kodad-historic-granary-krishna-canal-regulators', 'The district having a vast expanse of river Krishna basin, witnesses a quite widespread agriculture while Nagarjuna Sagar left canal is its chief source of irrigation.', 'Scenic & Cultural', 'Telangana', 'Suryapet District', 'Kodad', '07:00 AM', '07:00 PM', 0, '', 'EASY', 4.5, 2500, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Garidepally Lotus Pond & Ancient Stepwell', 'garidepally-lotus-pond-ancient-stepwell', 'Garidepally is a census town in the Suryapet district of Telangana, India. It is the headquarters of the Garidepally mandal of the Suryapet revenue division.', 'Scenic & Cultural', 'Telangana', 'Suryapet District', 'Garidepally', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.4, 5, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Yadadri Sri Lakshmi Narasimha Swamy Mahakshetram', 'yadadri-sri-lakshmi-narasimha-swamy-mahakshetram', 'The Sri Lakshmi Narasimha Swamy Temple or Yadadri or Yadagiri Gutta Devasthanam (YGD), or Pancha Narasimha Kshetram or Rishi Aradhana Kshetram is a Hindu Temple situated on a hillock in the small town of Yadagirigutta in the Yadadri Bhuvanagiri district of the Indian state of Telangana.', 'Heritage & Spiritual', 'Telangana', 'Yadadri Bhuvanagiri District', 'Yadagirigutta', '04:00 AM', '09:30 PM', 0, '', 'EASY', 4.6, 49466, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Bhongir Fort (Bhuvanagiri Monolithic Citadel)', 'bhongir-fort-bhuvanagiri-monolithic-citadel', 'Bhongir Fort, also known as Bhuvanagiri Fort, is a fort located in the heart of Bhongir a town in Yadadri Bhuvanagiri district, Telangana, India. It is located on a huge rock at a commanding height. 47 km from Hyderabad.', 'Historical Forts & Monuments', 'Telangana', 'Yadadri Bhuvanagiri District', 'Bhuvanagiri', '09:00 AM', '05:30 PM', 25, '', 'EASY', 4.4, 6739, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Pochampally Handloom Weaving Village (UNWTO Best Tourism Village)', 'pochampally-handloom-weaving-village-unwto-best-tourism-village', 'The village of Pochampally has many attractions, including the world famous traditionally hand-woven IKAT products, or the various attractions of pilgrimage, ecotourism, local cultural heritage, performing arts, handicrafts, and other indigenous products that showcase unique techniques.', 'Artisans & Culture', 'Telangana', 'Yadadri Bhuvanagiri District', 'Bhoodan Pochampally', '09:00 AM', '06:30 PM', 0, '', 'EASY', 4.2, 461, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Surendrapuri Mythological Theme Park (Kunda Satyanarayana Kaladhamam)', 'surendrapuri-mythological-theme-park-kunda-satyanarayana-kaladhamam', 'Surendrapuri is a religious tourism destination located near Hyderabad, Telangana, India in the Yadadri Bhuvanagiri district.', 'Heritage & Spiritual', 'Telangana', 'Yadadri Bhuvanagiri District', 'Yadagirigutta', '09:00 AM', '07:00 PM', 350, '', 'EASY', 4.6, 100, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sri Matsya Narasimha Swamy Temple, Vemulakonda', 'sri-matsya-narasimha-swamy-temple-vemulakonda', 'The temple is located amidst the cascading waterfalls in the lap of cold nature. Devotees worship Lord Lakshminarasimha on Matsya Giri Hill in the village of Venkatapuram,Valigonda Mandal. Formerly known as Vyomulu, the sages climbed the Matsya Giri hill in search of a quiet place away from traffic Began penance.', 'Waterfalls & Gorges', 'Telangana', 'Yadadri Bhuvanagiri District', 'Valigonda', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.7, 1730, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kolanupaka Historical Border & Someshwara Shrine', 'kolanupaka-historical-border-someshwara-shrine', 'Kulpakji, also known as Kolanupaka Temple is a 2,000-year-old Śvetāmbara Jain temple in the village of Kolanupaka in Aler City, Yadadri Bhuvanagiri district, Telangana, India. The temple houses three deities: one each of Lord Rishabhanatha, Lord Neminatha, and Lord Mahavira.', 'Heritage & Spiritual', 'Telangana', 'Yadadri Bhuvanagiri District', 'Alair', '06:00 AM', '06:00 PM', 0, '', 'EASY', 4.6, 545, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Turkapally Rural Pottery & Terracotta Hub', 'turkapally-rural-pottery-terracotta-hub', 'M.Turkapally (or Mannevari Turkapalle) is a village in yadadri bhuvanagiri district of the Indian state of Telangana. It is located in Turkapally mandal of Bhongir division.', 'Artisans & Culture', 'Telangana', 'Yadadri Bhuvanagiri District', 'Turkapally', '09:00 AM', '06:00 PM', 0, '', 'EASY', 4.5, 2500, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Baswapur Reservoir & Kaleshwaram Canal Network', 'baswapur-reservoir-kaleshwaram-canal-network', 'The Kaleshwaram Lift Irrigation Project (KLIP) is a multi-purpose irrigation project on the Godavari River in Kaleshwaram, Bhupalpally, Telangana, India. Currently the world''s largest multi-stage lift irrigation project, its farthest upstream influence is at the confluence of the Pranahita and Godavari rivers.', 'Lakes, Dams & Waterways', 'Telangana', 'Yadadri Bhuvanagiri District', 'Bhuvanagiri', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.1, 144, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Rajapet Fort & Kakatiya Brick Ramparts', 'rajapet-fort-kakatiya-brick-ramparts', 'Rajapeta is a historic location, popularly known as Samsthan Rajapeta, which has forts of Indian state of Telangana located in Yadadri Bhuvanagiri district. Rajapeta Sansthan was one of the 14 princely states of Hyderabad during the Nizam''s rule.', 'Historical Forts & Monuments', 'Telangana', 'Yadadri Bhuvanagiri District', 'Rajapet', '07:00 AM', '05:30 PM', 0, '', 'MODERATE', 4.3, 64, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Choutuppal Historic Weaving & Dyeing Units', 'choutuppal-historic-weaving-dyeing-units', 'Choutuppal is a census town in Yadadri Bhuvanagiri district of the Indian state of Telangana. It is located in Choutuppal mandal of Choutuppal division. Its part of Hyderabad Metropolitan Development Authority. 49 km from Hyderabad. A local bus that commutes between Dilsukhnagar and Choutuppal', 'Artisans & Culture', 'Telangana', 'Yadadri Bhuvanagiri District', 'Choutuppal', '09:00 AM', '06:30 PM', 0, '', 'EASY', 4.7, 54, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Pillalamarri 800-Year-Old Giant Banyan Tree', 'pillalamarri-800-year-old-giant-banyan-tree', 'Pillalamarri (Children''s Banyan) or Peerlamarri (Saints Banyan) is an 800-year-old banyan tree located in Mahbubnagar, Telangana, India. The tree is spread over 4 acres. It is a major tourist attraction located 4 kilometers from Mahbubnagar. Pillalamarri Banyan Tree is an 800 year old Banyan tree located in Mahabubnagar, Telangana, India.', 'Historical Forts & Monuments', 'Telangana', 'Mahabubnagar District', 'Mahabubnagar Rural', '09:00 AM', '06:00 PM', 20, '', 'EASY', 4.1, 2971, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Manyamkonda Sri Venkateswara Swamy Temple (Palamoor Tirupati)', 'manyamkonda-sri-venkateswara-swamy-temple-palamoor-tirupati', 'In Telangana, there are many spiritual temples which has a soulful history. One among the great temples is the Manyamkonda Venkateshwara Temple of Manyamkonda village in Mahabubnagar District. Very rarely we can find Lord Venkateshwara as a "Swayambhumurthi" which means self manifested.', 'Heritage & Spiritual', 'Telangana', 'Mahabubnagar District', 'Chinna Chintakunta', '05:00 AM', '08:30 PM', 0, '', 'EASY', 4.6, 2272, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Koilkonda Fort & Ramaswamy Temple', 'koilkonda-fort-ramaswamy-temple', 'Sri Ramakonda Temple, Koilkonda Srirama Konda is located about 23 Kms from the District Head Quarters of MahabubNagar in the Mandal Head Quarters of Koilkonda and is one of the reputed Historical monuments of the district. History: Lord Srirama put his leg in Thretayuga along with his wife Sita and brother Lakshmana when he is […]', 'Waterfalls & Gorges', 'Telangana', 'Mahabubnagar District', 'Koilkonda', '07:00 AM', '05:30 PM', 0, '', 'EASY', 4.3, 239, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Mayuri Central Eco-Park (Haritha Kanam)', 'mayuri-central-eco-park-haritha-kanam', 'The main objective of the exercise is to expand the urban lung space by improving greenery and building recreation centres. Mayuri Central Nursery, located between Mahbubnagar and Jadcherla highway, is an ideal location for developing the eco-tourism project in the district.', 'Nature & Wildlife', 'Telangana', 'Mahabubnagar District', 'Mahabubnagar Urban', '05:30 AM', '07:30 PM', 20, '', 'EASY', 4.1, 1884, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Jurala Dam (Priyadarshini Jurala Project)', 'jurala-dam-priyadarshini-jurala-project', 'The Priyadarshini Jurala Project (PJP) or Jurala Project, is a dam on the Krishna River situated about 15 km from Gadwal, Jogulamba Gadwal district, Jurala Project is a dam on the Krishna River situated about 16 km from Atmakur, Wanaparthy district, Telangana, India.', 'Lakes, Dams & Waterways', 'Telangana', 'Mahabubnagar District', 'Gadwal / Mahabubnagar border', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.4, 430, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Pedda Cheruvu Mini Tank Bund & Promenade', 'pedda-cheruvu-mini-tank-bund-promenade', 'Pedda Cheruvu is an urban lakefront park in Mahabubnagar featuring paved walking promenades, illuminated evening fountains, boating facilities, and family recreation zones.', 'Lakes, Dams & Waterways', 'Telangana', 'Mahabubnagar District', 'Mahabubnagar Urban', '06:00 PM', '10:00 PM', 0, '', 'EASY', 4.5, 2500, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kurumurthy Sri Venkateswara Swamy Temple', 'kurumurthy-sri-venkateswara-swamy-temple', 'Kurumurthy Temple is a 12th-century hill shrine built inside a natural rock cavern atop the hills of Mahabubnagar, dedicated to Sri Venkateswara Swamy and reached via 365 stone steps.', 'Heritage & Spiritual', 'Telangana', 'Mahabubnagar District', 'Chinna Chintakunta', '06:00 AM', '08:00 PM', 0, '', 'EASY', 4.6, 1575, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Macharam Forest Eco-Trail & Deer Habitat', 'macharam-forest-eco-trail-deer-habitat', 'District History: Telangana forms the core of the Satavahana Dynasty (221BC-218 AD), Part of Chalukyan Dynasty in South India (between 5th and 11th century AD) and in the recent history, it formed the core of the Golconda State and Hyderabad State, ruled by Qutub Shahi Dynasty (1520-1687) and Dynasty (Asaf Jahi Dynasty) (1724-1948) until it was taken over by New Delhi in 1948.', 'Nature & Wildlife', 'Telangana', 'Mahabubnagar District', 'Jadcherla', '07:00 AM', '05:30 PM', 20, '', 'EASY', 4.2, 689, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Jadcherla Historic Badami Chalukyan Chennakesava Temple', 'jadcherla-historic-badami-chalukyan-chennakesava-temple', 'This temple is a true example of Chalukyan aesthetics and religious devotion, showcasing their mastery in stone carving and temple design.', 'Heritage & Spiritual', 'Telangana', 'Mahabubnagar District', 'Jadcherla', '06:30 AM', '07:30 PM', 0, '', 'EASY', 4.7, 24, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Balanagar Forest Eco-Park & Deer Nursery', 'balanagar-forest-eco-park-deer-nursery', 'District History: Telangana forms the core of the Satavahana Dynasty (221BC-218 AD), Part of Chalukyan Dynasty in South India (between 5th and 11th century AD) and in the recent history, it formed the core of the Golconda State and Hyderabad State, ruled by Qutub Shahi Dynasty (1520-1687) and Dynasty (Asaf Jahi Dynasty) (1724-1948) until it was taken over by New Delhi in 1948.', 'Nature & Wildlife', 'Telangana', 'Mahabubnagar District', 'Balanagar', '08:00 AM', '05:30 PM', 20, '', 'EASY', 4.1, 1884, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Amrabad Tiger Reserve & Farahabad Forest Viewpoint', 'amrabad-tiger-reserve-farahabad-forest-viewpoint', 'Farahabad View Point lies deep inside the Amrabad Tiger Reserve, near Mannanur, Nagarkurnool district, Telangana. Once a hunting retreat of the Nizams of Hyderabad, the name "Farahabad" literally means "Mount Pleasant".', 'Scenic & Cultural', 'Telangana', 'Nagarkurnool District', 'Amrabad', '06:00 AM', '04:30 PM', 50, '', 'EASY', 4.2, 689, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Mallela Theertham Waterfalls (Nallamala Canyon Cascade)', 'mallela-theertham-waterfalls-nallamala-canyon-cascade', 'Mallela Theertham is a waterfall located in the Nallamala Forest in Nagarkurnool, Telangana, India. The River Krishna flows through this forest. It is located around 58 km from Srisailam and 185 km from Hyderabad.', 'Waterfalls & Gorges', 'Telangana', 'Nagarkurnool District', 'Amrabad', '08:00 AM', '05:00 PM', 30, '', 'EASY', 4.4, 6055, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Octopus Viewpoint & Krishna River Gorge Overlook', 'octopus-viewpoint-krishna-river-gorge-overlook', 'Octopus View Point is one of the most scenic and recently developed eco-tourism attractions within the Amrabad Tiger Reserve in the Nallamala Forest Range, Nagarkurnool district, Telangana.', 'Scenic & Cultural', 'Telangana', 'Nagarkurnool District', 'Amrabad', '08:30 AM', '05:30 PM', 25, '', 'EASY', 4.7, 232, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Uma Maheshwaram Temple (Northern Gateway to Srisailam)', 'uma-maheshwaram-temple-northern-gateway-to-srisailam', 'Uma Maheshwaram is an ancient Shiva cave temple in the Nallamala hills, revered as the historic northern gateway to Srisailam with a perennial natural spring. Surrounded by thick forests, rocky paths, and natural springs, the temple is often referred to as the hidden gateway to Srisailam Jyotirlinga.', 'Heritage & Spiritual', 'Telangana', 'Nagarkurnool District', 'Achampet', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.7, 3330, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Saleshwaram Lingayya Swamy Cave Temple & Waterfall', 'saleshwaram-lingayya-swamy-cave-temple-waterfall', 'Saleshwaram Temple, also known as Sarveswaran, is a sacred cave shrine dedicated to Lord Shiva, located deep within the Nallamala Forest in Telangana''s Nagarkurnool district. The temple is open to devotees only once a year, during the auspicious occasion of Chaitra Purnima, which falls between 11th and 13th April 2025 (dates tentative).', 'Waterfalls & Gorges', 'Telangana', 'Nagarkurnool District', 'Amrabad (Deep Forest Core)', '08:00 AM', '06:00 PM', 50, '', 'EASY', 4.5, 78, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kollapur Royal Palace & Madhava Swamy Temple', 'kollapur-royal-palace-madhava-swamy-temple', 'Madhava Swamy Temple at Kollapur - a beautiful 16th‑century Vaishnava shrine originally located at Manchalakatta village on the left bank of the River Krishna. It was built by King Sri Surabhi Madhava Rayalu of the Jetprole Rajas (Jetprole dynasty) during the 16th century CE.', 'Heritage & Spiritual', 'Telangana', 'Nagarkurnool District', 'Kollapur', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.7, 83, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Somasila Krishna River Confluence & Island Eco-Cottages', 'somasila-krishna-river-confluence-island-eco-cottages', 'In 2018, the then Tourism Minister Jupally Krishna Rao announced to develop Somasila in Kollapur to be an ecotourism destination together with Jataprolu and Singotam and explained their future project of constructing 10 cottages by August 2018 and to lease out the hotel Haritha to private parties.', 'Heritage & Spiritual', 'Telangana', 'Nagarkurnool District', 'Kollapur', '07:00 AM', '06:30 PM', 20, '', 'EASY', 4.3, 84, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kalwakurthy Historic Stepwells & Countryside', 'kalwakurthy-historic-stepwells-countryside', 'Kalwakurthy is a town and revenue division in Telangana state, India. It is the largest town in Nagarkurnool district geographically by area. And also it is one of the major cities in combined Mahabubnagar district. The name of the city is derived from the word "Kavula Keerti" which means " The Pride of Poets".', 'Heritage & Spiritual', 'Telangana', 'Nagarkurnool District', 'Kalwakurthy', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.3, 4576, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Bijinapalle Historic Stepwell & Narasimha Temple', 'bijinapalle-historic-stepwell-narasimha-temple', 'Allipur Bijinepally Gangaram Gouraram Gudlanarva Kanapur Karkonda Lattupally Lingasanipally Mahadevpet Manganoor Mommaipally Palem Polepally Salkarpet Shainpally Vasanthapur Vaddemaan (Nandi Vaddemaan) Vattem Velgonda', 'Heritage & Spiritual', 'Telangana', 'Nagarkurnool District', 'Bijinapalle', '06:30 AM', '07:30 PM', 0, '', 'EASY', 4.8, 419, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Pentlavelli Krishna Riverbank Groves & Fruit Orchards', 'pentlavelli-krishna-riverbank-groves-fruit-orchards', 'Nagarkurnool History dates back to Asmaka Janapada. In olden times used to be part of Vardhamaanapuram current Nandi Vaddeman. According to Mahabharata literature, Maharshi Agastya Maharshi, established a shiva temple named "Agastheeswara Temple" on the banks of river Krishna (traceable to present day Kollapur division of the district)', 'Heritage & Spiritual', 'Telangana', 'Nagarkurnool District', 'Pentlavelli', '07:00 AM', '06:00 PM', 0, '/images/candidates/nagarkurnool/17905956928156.png', 'EASY', 4.5, 56, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Wanaparthy Royal Palace (Raj Mahal)', 'wanaparthy-royal-palace-raj-mahal', 'Wanaparthy Samsthanam or Raja of Wanaparthy was a semi-sovereign dynasty coming from the times of Kakatiyas, who were also vassal of the Nizam of Hyderabad. He controlled the feudatory of Wanaparthy. It was one of the three important Samsthanams in Telangana, the other two being Gadwal Samsthanam and Jatprole Samsthanam.', 'Historical Forts & Monuments', 'Telangana', 'Wanaparthy District', 'Wanaparthy', '09:30 AM', '05:30 PM', 0, '', 'EASY', 4.3, 324, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Sarala Sagar Dam & Unique Automated Siphon Spillway', 'sarala-sagar-dam-unique-automated-siphon-spillway', 'Sarala Sagar Project is the second biggest dam in Asia with siphon technology. It is the oldest project in India after independence Raja of Wanaparthy Raja Rameshwara Rao founded by the Sarala Sagar Dam Project that has incorporated siphon technology from California, United States. 1949 project was inaugurated by the military former Governor of Hyderabad General J.N Chowdary.', 'Lakes, Dams & Waterways', 'Telangana', 'Wanaparthy District', 'Madanapur', '07:00 AM', '06:30 PM', 0, '', 'EASY', 4.5, 153, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Srirangapur Sri Ranganayaka Swamy Temple', 'srirangapur-sri-ranganayaka-swamy-temple', 'Sri Ranganayaka Swamy Temple, also known as the Shri Rangapur Temple, was constructed in the 18th century AD by Raja Baheri Gopal Rao of Wanaparthy Samasthanam It is located in Shri Rangapur Village, Pebbair, Wanaparthy District, Telangana.', 'Heritage & Spiritual', 'Telangana', 'Wanaparthy District', 'Srirangapur', '06:00 AM', '08:30 PM', 0, '', 'EASY', 4.8, 1488, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Beechupally Sri Anjaneya Swamy Temple & Krishna Ghats', 'beechupally-sri-anjaneya-swamy-temple-krishna-ghats', 'Beechupally in Jogulamba Gadwal district, Telangana, India, is a shrine of the Hindu god Hanuman (Anjaneya Swamy). It is located on the banks of the Krishna River (where obsequies to the dead take place according to Hindu custom) about 30 kilometers downstream from the Jurala Project.', 'Heritage & Spiritual', 'Telangana', 'Wanaparthy District', 'Pebbair (Beechupally)', '05:30 AM', '08:30 PM', 0, '', 'EASY', 4.7, 2141, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kothakota Handloom & Silk Weavers'' Cluster', 'kothakota-handloom-silk-weavers-cluster', 'The handloom sector, particularly in rural Telangana, is not only a source of pride but also a critical economic driver. The production of Kothakota sarees supports approximately 500 families in the Wanaparthy district alone, with the ripple effects extending to nearby villages.', 'Artisans & Culture', 'Telangana', 'Wanaparthy District', 'Kothakota', '09:30 AM', '06:30 PM', 0, '', 'EASY', 4.8, 197, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ghanpur Fort & Historic Gona Ganna Reddy Citadel', 'ghanpur-fort-historic-gona-ganna-reddy-citadel', 'Khilla Ghanpur or Ghanpur, Wanaparthy district was ruled by Recherla Padmanayaka, Malyala and Gona dynasties in 13th century. Recherla Padmanayaka, Gona and Malyala dynasty kings were the Feudatores of Kakatiya Kings. Khilla Ghanpur has a fort and a lake (known as Ganapa Samudram) built during Kakatiya dynasty rule.', 'Historical Forts & Monuments', 'Telangana', 'Wanaparthy District', 'Ghanpur', '07:00 AM', '05:30 PM', 0, '', 'EASY', 4.4, 116, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Rangasamudram Lake & Boating Promenade', 'rangasamudram-lake-boating-promenade', 'Wanaparthy Samsthanam or Raja of Wanaparthy was a semi-sovereign dynasty coming from the times of Kakatiyas, who were also vassal of the Nizam of Hyderabad. He controlled the feudatory of Wanaparthy. It was one of the three important Samsthanams in Telangana, the other two being Gadwal Samsthanam and Jatprole Samsthanam.', 'Lakes, Dams & Waterways', 'Telangana', 'Wanaparthy District', 'Srirangapur', '07:00 AM', '06:30 PM', 0, '', 'EASY', 4.7, 21, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Pebbair Agro-Market & Rural Corridors', 'pebbair-agro-market-rural-corridors', 'Pebbair (Telugu: పెబ్బేరు, romanized: Pebbēru) is a municipal corporation in Wanaparthy district, Telangana, India. The Pebbair Municipal corporation''s northern end extends from Pampuram to its southern end in Yaparla.', 'Scenic & Cultural', 'Telangana', 'Wanaparthy District', 'Pebbair', '07:00 AM', '07:00 PM', 0, '', 'EASY', 4.2, 768, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Pangal Historic Fort & Hill Citadel', 'pangal-historic-fort-hill-citadel', 'Pangal Fort is located at Pangal in Wanaparthy District of Telangana, India. Pangal Fort is one of the Famous Hill Forts in Telangana. It was built by Kalyani Chalukya Kings during 11th and 12th Centuries. The fort is spread across hundreds of acres with Seven Gateways. The Main entrance is called as Mundlagavini and is a special attraction of this fort.', 'Historical Forts & Monuments', 'Telangana', 'Wanaparthy District', 'Pangal', '07:00 AM', '05:30 PM', 0, '', 'MODERATE', 3.6, 19, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Gopalpete Rural Terracotta & Pottery Hub', 'gopalpete-rural-terracotta-pottery-hub', 'Wanaparthy Samsthanam or Raja of Wanaparthy was a semi-sovereign dynasty coming from the times of Kakatiyas, who were also vassal of the Nizam of Hyderabad. He controlled the feudatory of Wanaparthy. It was one of the three important Samsthanams in Telangana, the other two being Gadwal Samsthanam and Jatprole Samsthanam.', 'Artisans & Culture', 'Telangana', 'Wanaparthy District', 'Gopalpete', '09:00 AM', '06:00 PM', 0, '', 'EASY', 4, 259, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Alampur Sri Jogulamba Temple (5th Maha Shakti Peeth)', 'alampur-sri-jogulamba-temple-5th-maha-shakti-peeth', 'Jogulamba Temple is a Hindu temple dedicated to Goddess Jogulamba, a form of Shakti located in Alampuram, Telangana, India. The temple is one of the Maha Shakta pithas, a group of eighteen (Ashtadasa) temples considered the most significant shrines and pilgrimage destinations in Shaktism.', 'Heritage & Spiritual', 'Telangana', 'Jogulamba Gadwal District', 'Alampur', '06:00 AM', '08:30 PM', 0, '', 'EASY', 4.7, 23649, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Alampur Nava Brahma Temples & Archaeological Museum', 'alampur-nava-brahma-temples-archaeological-museum', 'Alampuram Navabrahma Temples are a group of nine early Badami Chalukyan Hindu temples dated between the 7th and 9th centuries that are located at Alampuram (Hemalapuram) in Telangana, India, near the meeting point of Tungabhadra River and Krishna River at the border of Andhra Pradesh. They are called Nava-Brahma temples though they are dedicated to Shiva.', 'Heritage & Spiritual', 'Telangana', 'Jogulamba Gadwal District', 'Alampur', '06:00 AM', '05:00 PM', 0, '', 'EASY', 4.8, 53, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Gadwal Fort & The Monolithic 32-Foot Bronze Cannon', 'gadwal-fort-the-monolithic-32-foot-bronze-cannon', 'Gadwal Samsthanam was a semi-sovereign dynasty coming from the times of late Kakatiyas and later vassal of the Nizam of Hyderabad. Once part of Raichur district, it is now Gadwal in Jogulamba Gadwal district.', 'Heritage & Spiritual', 'Telangana', 'Jogulamba Gadwal District', 'Gadwal', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.2, 3654, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Gadwal Handloom Silk Saree Weavers'' Guilds', 'gadwal-handloom-silk-saree-weavers-guilds', 'The history of the Gadwal handloom cluster is deeply rooted in the evolution of princely patronage, caste-based weaving traditions, and sacred-cultural functions that gave rise to one of South India''s most celebrated silk saree traditions.', 'Artisans & Culture', 'Telangana', 'Jogulamba Gadwal District', 'Gadwal Urban', '09:30 AM', '07:30 PM', 0, '', 'EASY', 4.5, 360, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Tungabhadra & Krishna River Sangam (Gundimalla Sangam)', 'tungabhadra-krishna-river-sangam-gundimalla-sangam', 'Then it joins the Krishna River near Gundimalla Village of Jogulamba Gadwal district of Telangana.', 'Scenic & Cultural', 'Telangana', 'Jogulamba Gadwal District', 'Alampur / Undavelli', '06:00 AM', '06:30 PM', 0, '', 'EASY', 3.9, 16, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Maldakal Sri Swayambhu Lakshmi Venkateswara Temple', 'maldakal-sri-swayambhu-lakshmi-venkateswara-temple', 'Jogulamba Gadwal District, Telangana Sri Swayambhu Lakshmi Venkateswara Swamy Devasthanam Aadishilakshetram, Maldakal A self-manifested deity worshipped for over a thousand years as Thimmappa Swamy, in a blessed village known as Maldakal.', 'Heritage & Spiritual', 'Telangana', 'Jogulamba Gadwal District', 'Maldakal', '06:00 AM', '08:00 PM', 0, '', 'EASY', 4.7, 198, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Rajoli Weavers'' Village & Tungabhadra Checkdam', 'rajoli-weavers-village-tungabhadra-checkdam', 'Jogulamba Gadwal district, named after the powerful deity Jogulamba and the historic fort of Gadwal, serves as the southern gateway of Telangana. Situated at the confluence of the Krishna and Tungabhadra rivers (Veni-Sangamam), it has historically been known as Antarvedi (the land between rivers).', 'Historical Forts & Monuments', 'Telangana', 'Jogulamba Gadwal District', 'Rajoli', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.7, 23649, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Jurala Backwaters & Fishing Villages', 'jurala-backwaters-fishing-villages', 'Gadwal is a city and the district Headquarter of Jogulamba Gadwal district in the Indian state of Telangana. It is located 188 km (117 mi) from the state capital of Hyderabad and is a state assembly constituency. Gadwal historically served as the capital of Gadwal Samsthanam, a vassal of the Nizam of Hyderabad.', 'Scenic & Cultural', 'Telangana', 'Jogulamba Gadwal District', 'Dharoor', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.4, 21, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ieeja Historic Fort Bastions & Handloom Center', 'ieeja-historic-fort-bastions-handloom-center', 'Ieeja is a town and known as Mandal Head quarter located in Jogulamba Gadwal district in the state of Telangana. It comes under the Alampur assembly constituency, in the state of Telangana and it was formed as a municipality in 2009. Total Population as per 2011 census is 82,000/-', 'Historical Forts & Monuments', 'Telangana', 'Jogulamba Gadwal District', 'Ieeja', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.2, 3654, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Dharoor Krishna River Sandy Inlets & Fishing Ghats', 'dharoor-krishna-river-sandy-inlets-fishing-ghats', 'Jogulamba Gadwal district, named after the powerful deity Jogulamba and the historic fort of Gadwal, serves as the southern gateway of Telangana. Situated at the confluence of the Krishna and Tungabhadra rivers (Veni-Sangamam), it has historically been known as Antarvedi (the land between rivers).', 'Historical Forts & Monuments', 'Telangana', 'Jogulamba Gadwal District', 'Dharoor', '06:30 AM', '06:00 PM', 0, '', 'MODERATE', 4.2, 3654, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Narayanpet Handloom Silk Sarees Guilds', 'narayanpet-handloom-silk-sarees-guilds', 'Narayanpet district of Telangana is renowned for its exquisite and unique cotton handloom and silk sarees, which are widely popular. There is a historic legacy behind the handloom industry of Narayanpet.', 'Heritage & Spiritual', 'Telangana', 'Narayanpet District', 'Narayanpet', '09:30 AM', '07:30 PM', 0, '', 'EASY', 4.3, 54, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Koilsagar Dam & Reservoir', 'koilsagar-dam-reservoir', 'Koilsagar Dam is a medium‑sized irrigation reservoir located in Koilkonda Mandal, Mahabubnagar district, Telangana, about 145 km from Hyderabad (≈3.5 hours). Constructed during the Nizam era between 1945 and 1948, it was built across the Peddavagu River, a minor tributary of the Krishna. The dam is about 10 km from Koilkonda Fort and 30 km from Mahabubnagar city.', 'Historical Forts & Monuments', 'Telangana', 'Narayanpet District', 'Narva / Koilkonda border', '07:00 AM', '06:30 PM', 0, '', 'EASY', 4.4, 441, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Makthal Sri Padmanabha Swamy Temple', 'makthal-sri-padmanabha-swamy-temple', 'The Lord Sri Padamati Anjenaya Swamy temple is situated at the city called "Makthal", the city that lies near Krishna river doab.', 'Heritage & Spiritual', 'Telangana', 'Narayanpet District', 'Makthal', '06:00 AM', '08:00 PM', 0, '/images/candidates/narayanpet/2019051613-rr7mojg6vkg1njo7fhtujbtcjb2b800e2zqmadt4oy.jpg', 'EASY', 4.7, 131, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Chandraghad Hill Fort & Krishna River Overlook', 'chandraghad-hill-fort-krishna-river-overlook', 'Chandraghad Fort (also Chandragad) is located at Chandraghad village, Narva Mandal, Narayanpet district, Telangana, on the banks of the River Krishna. This scenic hill fort was built during the Peshwa period and belonged to Chandrasena Jilledar. It served as a storehouse for grains and taxes collected from the region before being transferred to the Peshwas.', 'Historical Forts & Monuments', 'Telangana', 'Narayanpet District', 'Narva', '07:00 AM', '05:30 PM', 0, '', 'EASY', 4.5, 50, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Utkoor Historic Jain & Veerashaiva Heritage Site', 'utkoor-historic-jain-veerashaiva-heritage-site', 'Utkoor is one of the 64 Mandals (Tehsil) in Mahboobnagar located about 60 km towards west from the District headquarters District bordering Karnataka state. Utkoor has 8,879 Households spread across total 33 villages and 18 panchayats. The nearest town to Utkoor is Narayanpet about 15 km away with good road connectivity.', 'Heritage & Spiritual', 'Telangana', 'Narayanpet District', 'Utkoor', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.7, 25, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Damaragidda Handloom & Wool Blankets (Gongadi) Cluster', 'damaragidda-handloom-wool-blankets-gongadi-cluster', 'Damaragidda is the historic weaving center for the traditional black wool blanket, known as the Gongadi, crafted by the Kuruma pastoral community using indigenous hand spindles and pit looms without artificial dyes.', 'Historical Forts & Monuments', 'Telangana', 'Narayanpet District', 'Damaragidda', '09:00 AM', '06:00 PM', 0, '', 'EASY', 4.5, 2500, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Maganoor & Krishna River Border Ghats', 'maganoor-krishna-river-border-ghats', 'The district is also historically linked to the world-famous Golconda Diamonds, including the Kohinoor. Kallakelegu-500 was a provincial administrative division (vishaya or nadu) under Western Chalukyas of Kalyani that encompassed the area around modern Ujjelli under Maganoor Mandal of Narayanpet district in Telangana.', 'Scenic & Cultural', 'Telangana', 'Narayanpet District', 'Maganoor', '06:00 AM', '06:30 PM', 0, '', 'EASY', 3.9, 20, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Singambhotlapally Natural Springs & Hill Viewpoint', 'singambhotlapally-natural-springs-hill-viewpoint', 'Perennial fresh water natural spring pool and surrounding granite boulder hillocks in Narayanpet, offering a peaceful picnic retreat with panoramic Deccan plateau views.', 'Scenic & Cultural', 'Telangana', 'Narayanpet District', 'Narayanpet Rural', '07:00 AM', '05:30 PM', 0, '', 'EASY', 3.9, 29, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kosgi Ancient Chalukyan Sun Temple & Stepwell', 'kosgi-ancient-chalukyan-sun-temple-stepwell', 'Kosgi is a municipality in Narayanpet district of Telangana state in India. It has a population of 21,038 (Census 2001). It is a part of Kodangal constituency of the Telangana state''s Legislative Assembly. The notable towns nearby Kosgi are Tandur, Kodangal, Mahabubnagar, Pargi and Maddur, Narayanpet Narayanpet.', 'Heritage & Spiritual', 'Telangana', 'Narayanpet District', 'Kosgi', '06:30 AM', '07:30 PM', 0, '', 'EASY', 3.9, 17, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Marikal Hillock Viewpoint & Granite Boulders', 'marikal-hillock-viewpoint-granite-boulders', 'Prominent monolithic granite boulder formation and elevated rock ridge overlooking the agricultural plains of Marikal in Narayanpet district.', 'Scenic & Cultural', 'Telangana', 'Narayanpet District', 'Marikal', '06:30 AM', '06:00 PM', 0, '', 'MODERATE', 4.7, 239, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Medak Cathedral (The Diocese of Medak)', 'medak-cathedral-the-diocese-of-medak', 'Medak Cathedral at Medak in Telangana, India, is one of the largest churches in India and has been the cathedral church of the Diocese of Medak of the Church of South India since 1947. Originally built by Charles Walker Posnett British Wesleyan Methodists, it was consecrated on 25 December 1924.', 'Heritage & Spiritual', 'Telangana', 'Medak District', 'Medak', '07:00 AM', '09:30 AM', 0, '', 'EASY', 4.6, 13596, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Medak Fort (Methukudurgam Rock Citadel)', 'medak-fort-methukudurgam-rock-citadel', 'Medak Fort is situated in Medak district in the Indian state of Telangana, about 100 kilometres from the state capital, Hyderabad. Medak fort was constructed by the Kakatiya Kings.', 'Historical Forts & Monuments', 'Telangana', 'Medak District', 'Medak', '07:00 AM', '05:30 PM', 0, '', 'EASY', 4.3, 67, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Edupayala Sri Vana Durga Bhavani Temple', 'edupayala-sri-vana-durga-bhavani-temple', 'The temple of Sri Edupayala Vana Durga Bhavani is located in Nagasanpalli, Papannapet Mandal, Medak District, and 112km from Hyderabad and just 18km from Medak.', 'Heritage & Spiritual', 'Telangana', 'Medak District', 'Papannapet', '05:30 AM', '07:30 PM', 0, '/images/telangana/edupayala.jpg', 'EASY', 4.7, 9461, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Pocharam Dam & Wildlife Sanctuary', 'pocharam-dam-wildlife-sanctuary', 'Pocharam Wildlife Sanctuary is a forest and wildlife sanctuary located 15 km (9.3 mi) from Medak and 115 km (71 mi) from Hyderabad, Telangana, India.', 'Lakes, Dams & Waterways', 'Telangana', 'Medak District', 'Haveli Ghanpur / bordering Kamareddy', '08:00 AM', '05:30 PM', 0, '', 'EASY', 4.5, 224, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Kuchadri Sri Venkateswara Swamy Temple', 'kuchadri-sri-venkateswara-swamy-temple', 'It is an ancient Hindu temple located in Kuchanapalli village of Medak district in Telangana State. It is an abode of Sri. Venkateshwara Swamy, and considered a holy divine destination by worshippers and visitors. It is located on the western outskirts of the Kuchanapalli village, on a hillock. It is locally called as "Kuchadri".', 'Heritage & Spiritual', 'Telangana', 'Medak District', 'Kuchanpally / Medak Rural', '06:00 AM', '07:30 PM', 0, '', 'EASY', 4.7, 159, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Manjira Wildlife & Bird Sanctuary (Medak Stretch)', 'manjira-wildlife-bird-sanctuary-medak-stretch', 'Manjira Wildlife Sanctuary is located in the Medak District of Telangana, India, 50 km northwest of Hyderabad. The sanctuary follows the course of the Manjira River for 36 km. This man-made reservoir provides drinking water to Hyderabad and Secunderabad. It has nine small islands, including Puttigadda, Bapangadda, Sangamadda and Karnamgadda.', 'Nature & Wildlife', 'Telangana', 'Medak District', 'Kulcharam', '09:00 AM', '05:00 PM', 20, '', 'EASY', 4, 105, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Narsapur Forest Urban Park & Lake Trek', 'narsapur-forest-urban-park-lake-trek', 'Narsapur formally Gandi Narsapuram, is a census town in Medak district of the Indian state of Telangana. It is located in Narsapur mandal. Narsapur Trekking Picture Forest Narsapur is a Municipality. Narsapur is located 50 km from Hyderabad ', 'Lakes, Dams & Waterways', 'Telangana', 'Medak District', 'Narsapur', '08:00 AM', '05:30 PM', 30, '', 'EASY', 4.3, 1170, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Shankarampet Historic Stepwells & Temples', 'shankarampet-historic-stepwells-temples', 'Medak district is a district located in the northern region of the Indian state of Telangana. Medak region was named by QutubShahis as Gulshanabad due to the lush greenery.', 'Heritage & Spiritual', 'Telangana', 'Medak District', 'Shankarampet (A)', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.5, 87, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Alladurg Historic Veerashaiva Matha & Stone Shrines', 'alladurg-historic-veerashaiva-matha-stone-shrines', 'Historic spiritual center of the Veerashaiva tradition with ancient stone temples, samadhis, and peaceful shaded courtyards.', 'Heritage & Spiritual', 'Telangana', 'Medak District', 'Alladurg', '06:00 AM', '08:00 PM', 0, '', 'EASY', 4.8, 510, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ramayampet Ancient Stepwell & Shiva Temple', 'ramayampet-ancient-stepwell-shiva-temple', 'Ramayampet is a Municipality and a mandal in Medak District of Telangana State. Ramayampet was an Assembly Constituency in the former Andhra Pradesh State from 1952 to 2009 in Medak district in Indian state of Telangana.', 'Heritage & Spiritual', 'Telangana', 'Medak District', 'Ramayampet', '07:00 AM', '06:00 PM', 0, '', 'EASY', 5, 12, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Komuravelli Sri Mallikarjuna Swamy Temple', 'komuravelli-sri-mallikarjuna-swamy-temple', 'The Komuravelli Mallanna Swamy Temple is a Hindu temple located on a hill in Komuravelli village of Siddipet district in Telangana state, India. It is located near Siddipet on SH-1 Rajiv Rahadari. The primary deity is Mallanna or Mallikarjuna Swamy, a form of Shiva. The deity is also called as Khandoba by the Maharashtrian people.', 'Heritage & Spiritual', 'Telangana', 'Siddipet District', 'Komuravelli', '05:00 AM', '08:30 PM', 0, '', 'EASY', 4.7, 12143, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Ranganayaka Sagar Reservoir & Island Guesthouse Viewpoint', 'ranganayaka-sagar-reservoir-island-guesthouse-viewpoint', 'Guide to Sri Ranganayaka Sagar Reservoir near Siddipet: a vast scenic reservoir with paddy-field views, a causeway-linked island and a popular spot for photography.', 'Scenic & Cultural', 'Telangana', 'Siddipet District', 'Chinnakodur', '07:00 AM', '06:30 PM', 0, '', 'EASY', 4.6, 1180, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Mallanna Sagar Reservoir & Mega Surge Pool', 'mallanna-sagar-reservoir-mega-surge-pool', 'The chief minister performed a special puja at the reservoir before releasing water into the reservoir in Siddipet district. He called it a historic moment in the agriculture history of the state and a dream come true for people of the state. He said the government completed the work despite all the hurdles created by certain "evil forces" by filing about 600 court cases.', 'Lakes, Dams & Waterways', 'Telangana', 'Siddipet District', 'Thoguta / Kondapak', '08:00 AM', '06:00 PM', 0, '', 'EASY', 4.5, 362, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Konda Pochamma Sagar Reservoir & Bund Drive', 'konda-pochamma-sagar-reservoir-bund-drive', 'A revered regional goddess shrine. Konda Pochamma Temple is a prominent folk shrine dedicated to Goddess Kondapochamma, revered as a guardian and protector of the region. Located at Teegul Narsapur in Jagdevpur Mandal, the temple is surrounded by the rural landscape of Siddipet district and is closely associated with the Kondapochamma Sagar area.', 'Heritage & Spiritual', 'Telangana', 'Siddipet District', 'Markook', '07:00 AM', '06:30 PM', 0, '', 'EASY', 4.5, 7434, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Komati Cheruvu & Glow Garden (Mini Tank Bund)', 'komati-cheruvu-glow-garden-mini-tank-bund', 'Komati Cheruvu, popularly known as the Mini Tank Bund of Siddipet, is a prominent lake and recreational destination in Siddipet town, Siddipet district, Telangana. The lake has been developed with a range of tourism and recreation facilities, including the Ruby Necklace Suspension Bridge, gardens, boating, a Dinosaur Theme Park, a musical fountain, and a 4-km necklace road.', 'Lakes, Dams & Waterways', 'Telangana', 'Siddipet District', 'Siddipet Urban', '05:00 AM', '08:30 PM', 20, '', 'EASY', 4.5, 2350, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Dubbak Handloom Weavers'' Guilds', 'dubbak-handloom-weavers-guilds', 'Rewind: Gloom in the lives behind the loom—giving Telangana''s weavers their due From Pochampally and Gadwal to Narayanpet and Siddipet, Telangana''s handloom traditions carry generations of skill, but recognition seldom translates into fair incomes for weavers', 'Artisans & Culture', 'Telangana', 'Siddipet District', 'Dubbak', '09:30 AM', '06:30 PM', 0, '', 'EASY', 4.5, 26, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Wargal Sri Vidya Saraswathi Temple', 'wargal-sri-vidya-saraswathi-temple', 'Wargal Saraswati Temple or Sri Vidya Saraswati Temple is a Hindu temple located in Siddipet district in Telangana, India. The deity of education in Hinduism is Goddess Saraswati.', 'Heritage & Spiritual', 'Telangana', 'Siddipet District', 'Wargal', '06:00 AM', '08:30 PM', 0, '', 'EASY', 4.7, 11741, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Shanigaram Historic Kakatiya Tank & Narasimha Temple', 'shanigaram-historic-kakatiya-tank-narasimha-temple', 'Brief History Of The Kshetra (Sthala Puranam): This temple was built by Kakatiya kings Moolavar And Goddess Name: Sri Lakshmi Narasimha Swamy Sthala Vruksha: Elaga Vruksha Year Of Construction: 500 years back', 'Heritage & Spiritual', 'Telangana', 'Siddipet District', 'Koheda', '07:00 AM', '06:00 PM', 0, '', 'EASY', 4.4, 98, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Cheriyal Scroll Paintings & Mask Artisans Guild (GI Tagged)', 'cheriyal-scroll-paintings-mask-artisans-guild-gi-tagged', 'Cheriyal (Cherial) is a town and municipality in Siddipet district, Telangana, an hour''s drive from Hyderabad and 85 km from Warangal city. Known worldwide for its unique scroll paintings and ritual masks created by the Nakashi artisans.', 'Nature & Wildlife', 'Telangana', 'Siddipet District', 'Cheriyal', '09:30 AM', '06:30 PM', 0, '', 'EASY', 5, 7, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;
INSERT INTO places (name, slug, description, category, state, district, city, opening_time, closing_time, individual_price, image_url, physical_difficulty, average_rating, review_count, active) VALUES ('Husnabad Historic Yellamma Temple & Hillock', 'husnabad-historic-yellamma-temple-hillock', 'Yellamma Cheruvu, Husnabad, Siddipet District. Photo: vinayonthego Where a historic lake meets a modern tourism attraction. Yellamma Cheruvu has long been an important water body for Husnabad, and the nearby Yellamma temple is an important local place of worship.', 'Heritage & Spiritual', 'Telangana', 'Siddipet District', 'Husnabad', '06:00 AM', '08:00 PM', 0, '', 'EASY', 4.6, 117, TRUE) ON CONFLICT (slug) DO UPDATE SET image_url = EXCLUDED.image_url, description = EXCLUDED.description, active = TRUE;